/* SHAHID ERP 2.0 modular source segment 20/59. Source is assembled in original order and executed as one classic script to preserve global declaration hoisting. */
(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[19] = "\n\n// ===== OPEN BL MODAL =====\nfunction openBLModal(editIdx = null, shipmentIdx = null, mode = 'SEA') {\n    try {\n        const modal = document.getElementById('blModal');\n        const title = document.getElementById('blModalTitle');\n        const body = document.getElementById('blModalBody');\n        if (!modal || !title || !body) {\n            console.error('BL Modal elements missing');\n            return alert('BL Draft modal not found \u2013 please refresh the page.');\n        }\n        if (!db.bldrafts) db.bldrafts = [];\n        if (!db.shipments) db.shipments = [];\n        if (!db.pol) db.pol = [];\n        if (!db.pod) db.pod = [];\n        if (!db.containers) db.containers = [];\n        if (!db.carriers) db.carriers = [];\n        if (!db.hiddenItems) db.hiddenItems = { pol: [], pod: [], containers: [], carriers: [] };\n        if (!db.hiddenItems.pol) db.hiddenItems.pol = [];\n        if (!db.hiddenItems.pod) db.hiddenItems.pod = [];\n        if (!db.hiddenItems.containers) db.hiddenItems.containers = [];\n        if (!db.hiddenItems.carriers) db.hiddenItems.carriers = [];\n\n        const today = new Date().toISOString().split('T')[0];\n\t\tlet b = { \n\t\t\tstatus: 'Draft', \n\t\t\tissueDate: today,\n\t\t\tblDate: today,\n\t\t\tmode: mode,\n\t\t\tforwardingAgent: db.companyName || 'GATEWAY EXIM'   // <-- ADD THIS LINE\n\t\t};\n\n        let isEdit = false;\n\n        if (editIdx !== null && db.bldrafts[editIdx]) {\n            b = { ...db.bldrafts[editIdx] };\n            isEdit = true;\n            title.textContent = 'Edit BL Draft';\n        } else {\n            title.textContent = 'Bill of Lading Draft';\n            if (shipmentIdx !== null && db.shipments[shipmentIdx]) {\n                const s = db.shipments[shipmentIdx];\n                b.shipmentCode = s.code || '';\n                b.shipperName = s.shipper || s.shipperName || s.client || s.customer || '';\n                b.shipperAddr = s.shipperAddr || s.shipperAddress || '';\n                b.consigneeName = s.consignee || s.consigneeName || '';\n                b.consigneeAddr = s.consigneeAddr || s.consigneeAddress || '';\n                b.notifyName = s.notifyParty || s.notifyName || '';\n                b.notifyAddr = s.notifyAddr || s.notifyAddress || '';\n                b.vessel = s.liner || s.vessel || '';\n                b.pol = s.pol || '';\n                b.pod = s.pod || '';\n                b.placeOfIssue = s.pol || '';\n                b.containers = [];\n                if (s.containerNo) {\n                    b.containers.push({ containerNo: s.containerNo, type: '', seal: '', grossWeight: s.weight || 0, netWeight: 0, volume: 0, packages: '' });\n                }\n                if (s.mode === 'AIR' || s.type === 'AIR') {\n                    b.mode = 'AIR';\n                }\n            }\n        }\n\n        const ports = db.pod.filter(p => !db.hiddenItems.pod.includes(p)).sort();\n        const pols = db.pol.filter(p => !db.hiddenItems.pol.includes(p)).sort();\n        const containers = db.containers.filter(c => !db.hiddenItems.containers.includes(c)).sort();\n\n        // Build container rows (only for SEA)\n        let containerRows = '';\n        if (b.mode === 'SEA') {\n            (b.containers || []).forEach((c, i) => {\n                containerRows += `<div class=\"bl-container-row\" data-row=\"${i}\">\n                    <input type=\"text\" class=\"bl-cont-no\" value=\"${c.containerNo||''}\" placeholder=\"Container No.\" />\n                    <select class=\"bl-cont-type\"><option value=\"\">Type</option>${containers.map(t => `<option value=\"${t}\" ${c.type===t?'selected':''}>${t}</option>`).join('')}</select>\n                    <input type=\"text\" class=\"bl-cont-seal\" value=\"${c.seal||''}\" placeholder=\"Seal\" />\n                    <input type=\"number\" class=\"bl-cont-weight\" value=\"${c.grossWeight||''}\" placeholder=\"Gross Wt (KGS)\" step=\"0.01\" oninput=\"updateBLTotals()\" />\n                    <input type=\"number\" class=\"bl-cont-net-weight\" value=\"${c.netWeight||''}\" placeholder=\"Net Wt (KGS)\" step=\"0.01\" oninput=\"updateBLTotals()\" />\n                    <input type=\"number\" class=\"bl-cont-volume\" value=\"${c.volume||''}\" placeholder=\"Volume (CBM)\" step=\"0.01\" oninput=\"updateBLTotals()\" />\n                    <input type=\"text\" class=\"bl-cont-packages\" value=\"${c.packages||''}\" placeholder=\"Packages\" />\n                    <button type=\"button\" class=\"btn btn-sm btn-info bl-cont-ldb-track\" title=\"Track this container on LDB\" onclick=\"trackBLContainerLdb(this)\">\ud83d\udd17 LDB Tracking</button>\n                    <button type=\"button\" class=\"btn btn-sm btn-preview bl-cont-duplicate\" title=\"Duplicate container with all data\" onclick=\"duplicateBLContainerRow(this)\">\u29c9</button>\n                    <button type=\"button\" class=\"btn btn-sm btn-clear\" title=\"Remove container\" onclick=\"this.closest('.bl-container-row').remove(); updateBLTotals();\">\u00d7</button>\n                </div>`;\n            });\n        }\n\n        const companyName = db.companyName || 'GATEWAY EXIM';\n\n        // Movement options\n        const seaMovements = ['OCEAN (PORT TO PORT)','OCEAN (PORT TO RAMP)','OCEAN (PORT TO DOOR)','OCEAN (RAMP TO RAMP)'];\n        const airMovements = ['AIR (PORT TO PORT)','AIR (PORT TO DOOR)','AIR (DOOR TO DOOR)'];\n        const movementOptions = b.mode === 'AIR' ? airMovements : seaMovements;\n\n        const modeSelectHtml = isEdit ? `<input type=\"hidden\" id=\"bl-mode\" value=\"${b.mode}\" />` :\n            `<select id=\"bl-mode\" onchange=\"onBLModeChange()\">\n                <option value=\"SEA\" ${b.mode === 'SEA' ? 'selected' : ''}>\ud83d\udea2 SEA</option>\n                <option value=\"AIR\" ${b.mode === 'AIR' ? 'selected' : ''}>\u2708\ufe0f AIR</option>\n                <option value=\"LCL\" ${b.mode === 'LCL' ? 'selected' : ''}>\ud83d\udce6 LCL</option>\n            </select>`;\n\n        const showContainerSection = b.mode === 'SEA';\n\n        // Determine voyage input type and value\n        const voyageInputType = b.mode === 'AIR' ? 'date' : 'text';\n        const voyageInputValue = b.voyage || '';\n\n        body.innerHTML = `\n            <!-- TOP ROW -->\n            <div style=\"display:grid; grid-template-columns:1fr 1.25fr 1.1fr 1fr 1fr 1fr; gap:10px; margin-bottom:16px;\">\n                <div class=\"form-group\"><label>Mode</label>${modeSelectHtml}</div>\n                <div class=\"form-group\"><label>JOB NO. / Reference</label><input type=\"text\" id=\"bl-job-no\" list=\"bl-job-quote-ref-list\" value=\"${b.jobNo || b.shipmentCode||''}\" oninput=\"onBLJobNoChange()\" onblur=\"onBLJobNoChange()\" onchange=\"onBLJobNoChange()\" placeholder=\"JOB NO. / select Quote Ref\" /><datalist id=\"bl-job-quote-ref-list\"></datalist><datalist id=\"bl-job-list\"></datalist><small id=\"bl-job-status\" style=\"display:block;min-height:14px;color:#64748b;\"></small></div>\n                <div class=\"form-group\"><label>QUOTE REF</label><input type=\"text\" id=\"bl-quote-ref\" list=\"bl-quote-ref-list\" value=\"${b.quoteRef||''}\" oninput=\"onBLReferenceChange()\" onchange=\"onBLReferenceChange()\" onblur=\"onBLReferenceChange()\" placeholder=\"Quote Ref\" /><datalist id=\"bl-quote-ref-list\"></datalist></div>\n                <div class=\"form-group\"><label>BL Number *</label><input type=\"text\" id=\"bl-number\" value=\"${b.blNumber || 'HBL'+Date.now().toString(36).toUpperCase()}\" style=\"font-weight:bold;font-size:1.1rem;\" /></div>\n                <div class=\"form-group\"><label>Date *</label><input type=\"date\" id=\"bl-date\" value=\"${b.blDate || today}\" style=\"font-weight:bold;\" /></div>\n                <div class=\"form-group\"><label>Booking No.</label><input type=\"text\" id=\"bl-booking-no\" value=\"${b.bookingNo||''}\" /></div>\n            </div>\n\n\t\t\t<!-- Export References & Forwarding Agent & Show Agent Toggle -->\n\t\t\t<div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px; margin-bottom:16px;\">\n\t\t\t\t<div class=\"form-group\"><label>Export References</label><input type=\"text\" id=\"bl-export-ref\" value=\"${b.exportRef||''}\" /></div>\n\t\t\t\t<div class=\"form-group\"><label>Forwarding Agent / FMC No.</label><input type=\"text\" id=\"bl-forwarding-agent\" value=\"${b.forwardingAgent || db.companyName || 'GATEWAY EXIM'}\" style=\"width:100%;\" /></div>\n\t\t\t\t<div class=\"form-group\" style=\"display:flex; align-items:center; gap:8px; margin-top:6px;\">\n\t\t\t\t\t<input type=\"checkbox\" id=\"bl-show-agent\" ${b.showAgent !== false ? 'checked' : ''} style=\"width:18px; height:18px;\" />\n\t\t\t\t\t<label for=\"bl-show-agent\" style=\"font-weight:600; font-size:0.8rem; cursor:pointer;\">Show Agent Details</label>\n\t\t\t\t</div>\n\t\t\t</div>\n\n            <!-- Shipper & Consignee -->\n            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\">\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Shipper / Exporter</h4>\n                    <div class=\"form-group\"><label>Name</label><input type=\"text\" id=\"bl-shipper-name\" value=\"${b.shipperName||''}\" style=\"width:100%;\" /></div>\n                    <div class=\"form-group\"><label>Address</label><textarea id=\"bl-shipper-addr\" rows=\"3\" style=\"width:100%;\">${b.shipperAddr||''}</textarea></div>\n                </div>\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Consignee</h4>\n                    <div class=\"form-group\"><label>Name</label><input type=\"text\" id=\"bl-consignee-name\" value=\"${b.consigneeName||''}\" style=\"width:100%;\" /></div>\n                    <div class=\"form-group\"><label>Address</label><textarea id=\"bl-consignee-addr\" rows=\"3\" style=\"width:100%;\">${b.consigneeAddr||''}</textarea></div>\n                </div>\n            </div>\n\n            <!-- Notify Party & Delivery Agent -->\n            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\">\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Notify Party</h4>\n                    <div class=\"form-group\"><label>Name</label><input type=\"text\" id=\"bl-notify-name\" value=\"${b.notifyName||''}\" style=\"width:100%;\" /></div>\n                    <div class=\"form-group\"><label>Address</label><textarea id=\"bl-notify-addr\" rows=\"3\" style=\"width:100%;\">${b.notifyAddr||''}</textarea></div>\n                </div>\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Delivery Agent</h4>\n                    <div class=\"form-group\"><label>Name</label><input type=\"text\" id=\"bl-delivery-agent-name\" value=\"${b.deliveryAgentName||''}\" style=\"width:100%;\" /></div>\n                    <div class=\"form-group\"><label>Address</label><textarea id=\"bl-delivery-agent-addr\" rows=\"3\" style=\"width:100%;\">${b.deliveryAgentAddr||''}</textarea></div>\n                </div>\n            </div>\n\n            <!-- Vessel & Port Details -->\n            <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr 1fr; gap:10px; margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\" id=\"bl-vessel-row\">\n                <div class=\"form-group\"><label id=\"bl-label-pre-carriage\">PRE-CARRIAGE BY</label><input type=\"text\" id=\"bl-pre-carriage\" value=\"${b.preCarriage||''}\" /></div>\n                <div class=\"form-group\"><label id=\"bl-label-receipt\">PLACE OF RECEIPT</label><input type=\"text\" id=\"bl-receipt\" value=\"${b.placeOfReceipt||''}\" /></div>\n                <div class=\"form-group\"><label id=\"bl-label-vessel\">${b.mode==='AIR'?'15. FLIGHT NO.':'VESSEL NAME'}</label><input type=\"text\" id=\"bl-vessel\" value=\"${b.vessel||''}\" /></div>\n                <div class=\"form-group\">\n                    <label id=\"bl-label-voyage\">${b.mode==='AIR'?'DATE':'VOYAGE NO.'}</label>\n                    <input type=\"${voyageInputType}\" id=\"bl-voyage\" value=\"${voyageInputValue}\" ${b.mode==='AIR' ? '' : 'placeholder=\"e.g., 123W\"'} style=\"width:100%;\" />\n                </div>\n                <div class=\"form-group\"><label id=\"bl-label-pol\">${b.mode==='AIR'?'16. AIRPORT OF DEPARTURE':'PORT OF LOADING'}</label><input type=\"text\" id=\"bl-pol\" value=\"${b.pol||''}\" list=\"bl-pol-list\" /></div>\n                <datalist id=\"bl-pol-list\">${pols.map(p => `<option value=\"${p}\">`).join('')}</datalist>\n                <div class=\"form-group\"><label id=\"bl-label-pod\">${b.mode==='AIR'?'17. AIRPORT OF DESTINATION':'PORT OF DISCHARGE'}</label><input type=\"text\" id=\"bl-pod\" value=\"${b.pod||''}\" list=\"bl-pod-list\" /></div>\n                <datalist id=\"bl-pod-list\">${ports.map(p => `<option value=\"${p}\">`).join('')}</datalist>\n                <div class=\"form-group\"><label id=\"bl-label-delivery\">18. PLACE OF DELIVERY</label><input type=\"text\" id=\"bl-delivery\" value=\"${b.placeOfDelivery||''}\" /></div>\n                <div class=\"form-group\"><label id=\"bl-label-freight\">11. FREIGHT PAYABLE</label><select id=\"bl-freight-payable\"><option value=\"ORIGIN\" ${b.freightPayable==='ORIGIN'?'selected':''}>ORIGIN</option><option value=\"DESTINATION\" ${b.freightPayable==='DESTINATION'?'selected':''}>DESTINATION</option></select></div>\n                <div class=\"form-group\" style=\"grid-column:1/-1;\">\n                    <label id=\"bl-label-movement\">12. TYPE OF MOVEMENT</label>\n                    <select id=\"bl-movement\">${movementOptions.map(m => `<option value=\"${m}\" ${b.movement === m ? 'selected' : ''}>${m}</option>`).join('')}</select>\n                </div>\n            </div>\n\n            <!-- Goods Details -->\n            <div style=\"margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\">\n                <h4 style=\"color:var(--primary); margin-bottom:6px;\">Goods Details</h4>\n                <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px;\">\n                    <div class=\"form-group\"><label>Marks & Numbers</label><textarea id=\"bl-marks\" rows=\"3\" style=\"width:100%;\">${b.marks||''}</textarea></div>\n                    <div class=\"form-group\"><label>No. of Packages</label><input type=\"text\" id=\"bl-packages-count\" value=\"${b.packagesCount||''}\" /></div>\n                    <div class=\"form-group\" style=\"grid-column:1/-1;\"><label>Description of Goods</label><textarea id=\"bl-goods\" rows=\"3\" style=\"width:100%;\">${b.goodsDesc||''}</textarea></div>\n                    <div class=\"form-group\"><label>Gross Weight (KGS)</label><input type=\"number\" id=\"bl-gross-weight\" value=\"${b.grossWeight||''}\" step=\"0.01\" oninput=\"updateBLTotals()\" /></div>\n                    <div class=\"form-group\"><label>Measurement (CBM)</label><input type=\"number\" id=\"bl-measurement\" value=\"${b.measurement||''}\" step=\"0.01\" oninput=\"updateBLTotals()\" /></div>\n                </div>\n            </div>\n\n            <!-- Container Details (only for SEA) -->\n            ${showContainerSection ? `\n            <div style=\"margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\">\n                <h4 style=\"color:var(--primary); margin-bottom:6px;\">Container Details <button class=\"btn btn-sm btn-success\" onclick=\"addBLContainerRow()\">+ Add Row</button></h4>\n                <div id=\"bl-container-rows\">${containerRows}</div>\n                <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:10px;\">\n                    <div class=\"form-group\"><label>Total Gross Weight (KGS)</label><input type=\"text\" id=\"bl-total-weight\" readonly style=\"background:#f1f5f9;font-weight:bold;\" /></div>\n                    <div class=\"form-group\"><label>Total Measurement (CBM)</label><input type=\"text\" id=\"bl-total-volume\" readonly style=\"background:#f1f5f9;font-weight:bold;\" /></div>\n                </div>\n            </div>\n            ` : `\n            <div style=\"display:none;\"></div>\n            `}\n\n            <!-- Freight & Issuance -->\n            <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px; margin-bottom:16px; background:var(--bg); padding:12px; border-radius:8px;\">\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Freight & Charges</h4>\n                    <div class=\"form-group\"><label>Freight Terms</label><select id=\"bl-freight\"><option value=\"Prepaid\" ${b.freightType==='Prepaid'?'selected':''}>Prepaid</option><option value=\"Collect\" ${b.freightType==='Collect'?'selected':''}>Collect</option></select></div>\n                    <div class=\"form-group\"><label>Amount</label><input type=\"number\" id=\"bl-freight-amt\" value=\"${b.freightAmount||''}\" step=\"0.01\" /></div>\n                    <div class=\"form-group\"><label>Currency</label><select id=\"bl-freight-cur\">${getCurrencyOptions(b.freightCurrency||'INR')}</select></div>\n                </div>\n                <div>\n                    <h4 style=\"color:var(--primary); margin-bottom:6px;\">Issuance Details</h4>\n                    <div class=\"form-group\"><label>BL TYPE</label><select id=\"bl-type\"><option value=\"ORIGINAL\" ${b.blType==='ORIGINAL' || !b.blType?'selected':''}>ORIGINAL</option><option value=\"SEAWAY\" ${b.blType==='SEAWAY'?'selected':''}>SEAWAY</option><option value=\"SURRENDER\" ${b.blType==='SURRENDER'?'selected':''}>SURRENDER</option></select></div>\n                     <div class=\"form-group\"><label>No. of Original B/L</label><select id=\"bl-originals\"><option value=\"1\" ${b.numOriginals===1?'selected':''}>1</option><option value=\"2\" ${b.numOriginals===2?'selected':''}>2</option><option value=\"3\" ${b.numOriginals===3?'selected':''}>3</option></select></div>\n                    <div class=\"form-group\"><label>Place of Issue</label><input type=\"text\" id=\"bl-place\" value=\"${b.placeOfIssue||''}\" /></div>\n                    <div class=\"form-group\"><label>Issue Date</label><input type=\"date\" id=\"bl-issue-date\" value=\"${b.issueDate||today}\" /></div>\n                    <div class=\"form-group\"><label>Signature (Agent)</label><input type=\"text\" id=\"bl-signature\" value=\"${b.signature||companyName}\" style=\"width:100%;\" /></div>\n                </div>\n            </div>\n\n            <!-- Buttons -->\n            <div style=\"margin-top:16px; text-align:right; display:flex; gap:8px; justify-content:flex-end;\">\n                <button class=\"btn btn-clear\" onclick=\"closeModal('blModal')\">Cancel</button>\n                <button class=\"btn btn-success\" onclick=\"saveBLDraft(${editIdx !== null ? editIdx : 'null'})\">\ud83d\udcbe Save Draft</button>\n                ${isEdit ? `<button class=\"btn btn-quoted\" onclick=\"finalizeBLDraft(${editIdx})\">\u2705 Finalize</button>` : ''}\n            </div>\n        `;\n        openModal('blModal');\n        populateBLReferenceLists();\n        setTimeout(() => { updateBLTotals(); if (b.quoteRef || b.shipmentCode || b.jobNo) onBLReferenceChange(); }, 200);\n        if (!isEdit) {\n            updateBLLabels(b.mode);\n        }\n    } catch (e) {\n        console.error('Error opening BL modal:', e);\n        alert('Failed to open BL Draft. Please check the console for details.');\n    }\n}\n\n// Helper to update labels when mode changes\nfunction onBLModeChange() {\n    const mode = document.getElementById('bl-mode').value;\n    const movementSelect = document.getElementById('bl-movement');\n    const seaMovements = ['OCEAN (PORT TO PORT)','OCEAN (PORT TO RAMP)','OCEAN (PORT TO DOOR)','OCEAN (RAMP TO RAMP)'];\n    const airMovements = ['AIR (PORT TO PORT)','AIR (PORT TO DOOR)','AIR (DOOR TO DOOR)'];\n    const options = mode === 'AIR' ? airMovements : seaMovements;\n    const currentVal = movementSelect.value;\n    movementSelect.innerHTML = options.map(m => `<option value=\"${m}\" ${currentVal === m ? 'selected' : ''}>${m}</option>`).join('');\n    updateBLLabels(mode); // This will now also change the voyage input type\n}\n\nfunction updateBLLabels(mode) {\n    const isAir = mode === 'AIR';\n    document.getElementById('bl-label-vessel').textContent = isAir ? 'FLIGHT NO.' : 'VESSEL NAME';\n    document.getElementById('bl-label-voyage').textContent = isAir ? 'DATE' : 'VOYAGE NO.';\n    document.getElementById('bl-label-pol').textContent = isAir ? 'AIRPORT OF DEPARTURE' : 'PORT OF LOADING';\n    document.getElementById('bl-label-pod').textContent = isAir ? 'AIRPORT OF DESTINATION' : 'PORT OF DISCHARGE';\n    document.getElementById('bl-label-receipt').textContent = isAir ? ' PLACE OF RECEIPT (AIRPORT)' : 'PLACE OF RECEIPT';\n    \n    // Toggle voyage input type\n    const voyageInput = document.getElementById('bl-voyage');\n    if (voyageInput) {\n        if (isAir) {\n            voyageInput.type = 'date';\n            voyageInput.placeholder = '';\n        } else {\n            voyageInput.type = 'text';\n            voyageInput.placeholder = 'e.g., 123W';\n        }\n    }\n    // Update container placeholders\n    document.querySelectorAll('#bl-container-rows .bl-cont-no').forEach(el => {\n        el.placeholder = isAir ? 'ULD No.' : 'Container No.';\n    });\n}\n\n\n\n/* ===== END JS/15-bl-draft.js ===== */\n\n/* ===== BEGIN JS/43-master-pol.js ===== */\n/* Original source preserved from 07-master-admin.js; assigned to this functional module without code changes. */\n// ==================== DATABASE RENDER ====================\nfunction renderDatabase() {\n    // Database tab is a persistent admin panel. Normalize only missing containers/fields\n    // so older saved databases cannot stop the remaining Database Management UI from rendering.\n    db = db || {};\n    if (!db.hiddenItems) db.hiddenItems = { pol: [], pod: [], incoterms: [], containers: [], carriers: [], cargostatus: [], docsstatus: [] };\n    ['pol','pod','incoterms','containers','carriers','cargostatus','docsstatus'].forEach(k => { if (!Array.isArray(db.hiddenItems[k])) db.hiddenItems[k] = []; });\n    if (!db.exchangeRates || typeof db.exchangeRates !== 'object') db.exchangeRates = { INR: 1, USD: 83, EUR: 90 };\n    if (!db.defaults || typeof db.defaults !== 'object') db.defaults = {};\n    if (!Array.isArray(db.users)) db.users = [];\n\n    const setValue = (id, value) => { const el = document.getElementById(id); if (el) el.value = value ?? ''; };\n    const setText = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value ?? ''; };\n    setValue('company-name', db.companyName || '');\n    setValue('company-address', db.companyAddress || '');\n    setText('current-company-name', db.companyName || 'Not Set');\n    setValue('default-user-input', db.defaultUser || '');\n    setText('current-default-user', db.defaultUser || 'Not Set');\n    try{renderExchangeRates();}catch(e){console.warn(e);}\n    try{switchMasterTab(currentMasterTab||'pol');}catch(e){console.warn(e);}\n    try{renderUserTable();}catch(e){console.warn(e);}\n    const d = db.defaults || {};\n\ttry{loadDefaultCC();}catch(e){console.warn(e);}\n\n    setValue('def-gst', d.gst || 0);\n    setValue('def-insurance', d.insurance || 0);\n    setValue('def-profit', d.profitMargin || 0);\n    setValue('def-us-duty', d.usDuty || 0);\n    setValue('def-us-tariff', d.usTariff || 0);\n    setValue('def-us-mpf', d.usMPF || 0);\n    setValue('def-us-hmf', d.usHMF || 0);\n    setValue('def-in-duty', d.inDuty || 0);\n    setValue('def-in-social', d.inSocialWelfare || 0);\n    setValue('def-drawback', d.drawback || 0);\n    setValue('def-rodtep', d.rodtep || 0);\n\n    const dbPanel = document.getElementById('database');\n    if (dbPanel) {\n        dbPanel.classList.add('database-management-active');\n        dbPanel.setAttribute('data-db-rendered', 'true');\n    }\n\n    const curSelect = document.getElementById('def-currency');\n    if (curSelect) {\n        curSelect.innerHTML = Object.keys(db.exchangeRates).map(c =>\n            `<option value=\"${c}\" ${c === (d.defaultCurrency || 'USD') ? 'selected' : ''}>${c}</option>`\n        ).join('');\n    }\n}\n\n// ==================== MASTER DATA ====================\nfunction switchMasterTab(tab) {\n    currentMasterTab = tab;\n    masterSelected = {};\n    masterPage = 1;\n    document.querySelectorAll('.master-tab').forEach(t => t.classList.toggle('active', t.dataset.master === tab));\n    renderMasterData();\n}\nfunction getMasterListKey(tab) {\n    return tab === 'carriers' ? 'carriers' :\n        tab === 'pol' ? 'pol' :\n        tab === 'pod' ? 'pod' :\n        tab === 'incoterms' ? 'incoterms' :\n        tab === 'containers' ? 'containers' :\n        tab === 'cargostatus' ? 'cargoStatusMaster' :\n        tab === 'docsstatus' ? 'docsStatusMaster' :\n        'carriers';\n}\nfunction normalizeMasterValue(value) {\n    return String(value ?? '').trim().toUpperCase();\n}\nfunction renderMasterData() {\n    const list = document.getElementById('master-list');\n    const pagination = document.getElementById('master-pagination');\n    const bulkBar = document.getElementById('master-bulk-actions');\n    if (!list || !pagination) return;\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const hidden = db.hiddenItems[currentMasterTab] || [];\n    let filteredData = data.map((item, idx) => ({ item, idx }));\n    if (masterShowMode === 'visible') filteredData = filteredData.filter(({ item }) => !hidden.includes(item));\n    else if (masterShowMode === 'hidden') filteredData = filteredData.filter(({ item }) => hidden.includes(item));\n    // Prevent duplicate master entries from being displayed while preserving existing stored data.\n    const seenMasterValues = new Set();\n    filteredData = filteredData.filter(({ item }) => {\n        const norm = normalizeMasterValue(item);\n        if (seenMasterValues.has(norm)) return false;\n        seenMasterValues.add(norm);\n        return true;\n    });\n    if (masterSearch) {\n        const searchLower = masterSearch.toLowerCase();\n        filteredData = filteredData.filter(({ item }) => item.toLowerCase().includes(searchLower));\n    }\n    if (masterSort === 'alpha-asc') filteredData.sort((a, b) => a.item.localeCompare(b.item));\n    else if (masterSort === 'alpha-desc') filteredData.sort((a, b) => b.item.localeCompare(a.item));\n    const perPage = parseInt(masterPerPage) || 20;\n    const totalPages = Math.ceil(filteredData.length / perPage) || 1;\n    if (masterPage > totalPages) masterPage = totalPages;\n    if (masterPage < 1) masterPage = 1;\n    const start = (masterPage - 1) * perPage;\n    const pageData = filteredData.slice(start, start + perPage);\n    const selectedSet = new Set((masterSelected[currentMasterTab] || []).map(normalizeMasterValue));\n    const selectedCount = (masterSelected[currentMasterTab] || []).length;\n    const pageAllSelected = pageData.length > 0 && pageData.every(({ item }) => selectedSet.has(normalizeMasterValue(item)));\n    const allFilteredSelected = filteredData.length > 0 && filteredData.every(({ item }) => selectedSet.has(normalizeMasterValue(item)));\n    if (bulkBar) {\n        bulkBar.innerHTML = `\n            <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap;width:100%;\">\n                <label style=\"display:flex;align-items:center;gap:6px;font-weight:600;cursor:pointer;\">\n                    <input type=\"checkbox\" ${allFilteredSelected ? 'checked' : ''} onchange=\"toggleMasterSelectAll(this.checked)\">\n                    Select All\n                </label>\n                <span id=\"master-selected-count\" style=\"font-weight:600;color:var(--text-light);\">Selected: ${selectedCount}</span>\n                <button class=\"btn btn-sm btn-preview\" type=\"button\" onclick=\"masterBulkAction('show')\" ${selectedCount ? '' : 'disabled'}>\ud83d\udc41 Show Selected</button>\n                <button class=\"btn btn-sm btn-warning\" type=\"button\" onclick=\"masterBulkAction('hide')\" ${selectedCount ? '' : 'disabled'}>\ud83d\ude48 Hide Selected</button>\n                <button class=\"btn btn-sm btn-clear\" type=\"button\" onclick=\"masterBulkAction('delete')\" ${selectedCount ? '' : 'disabled'}>\ud83d\uddd1 Delete Selected</button>\n                <button class=\"btn btn-sm btn-info\" type=\"button\" onclick=\"clearMasterSelection()\" ${selectedCount ? '' : 'disabled'}>Clear Selection</button>\n            </div>`;\n    }\n    if (pageData.length === 0) {\n        list.innerHTML = '<p style=\"padding:20px;text-align:center;color:var(--text-light);\">No items found.</p>';\n        pagination.innerHTML = '';\n        return;\n    }\n    list.innerHTML = `\n        <div style=\"display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--border);background:var(--card-bg);font-size:0.8rem;color:var(--text-light);\">\n            <label style=\"display:flex;align-items:center;gap:6px;cursor:pointer;font-weight:600;\">\n                <input type=\"checkbox\" ${pageAllSelected ? 'checked' : ''} onchange=\"toggleMasterPageSelection(this.checked)\">\n                Select page\n            </label>\n        </div>\n        ${pageData.map(({ item, idx: originalIdx }) => {\n            const isHidden = hidden.includes(item);\n            const hiddenClass = isHidden ? 'hidden-item' : '';\n            const isSelected = selectedSet.has(normalizeMasterValue(item));\n            return `<div class=\"master-item ${hiddenClass}\">\n                <label style=\"display:flex;align-items:center;gap:10px;min-width:0;flex:1;cursor:pointer;\">\n                    <input type=\"checkbox\" ${isSelected ? 'checked' : ''} onchange=\"toggleMasterSelection(${originalIdx}, this.checked)\">\n                    <span>${item}</span>\n                </label>\n            </div>`;\n        }).join('')}`;\n    if (totalPages <= 1) { pagination.innerHTML = ''; return; }\n    let pagHtml = `<button class=\"page-btn\" onclick=\"changeMasterPage(${masterPage - 1})\" ${masterPage === 1 ? 'disabled' : ''}>\u2039 Prev</button>`;\n    pagHtml += `<span class=\"page-info\">Page ${masterPage} of ${totalPages}</span>`;\n    pagHtml += `<button class=\"page-btn\" onclick=\"changeMasterPage(${masterPage + 1})\" ${masterPage === totalPages ? 'disabled' : ''}>Next \u203a</button>`;\n    pagination.innerHTML = pagHtml;\n}\nfunction toggleMasterSelection(originalIdx, checked) {\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const item = data[originalIdx];\n    if (!item) return;\n    if (!masterSelected[currentMasterTab]) masterSelected[currentMasterTab] = [];\n    const norm = normalizeMasterValue(item);\n    masterSelected[currentMasterTab] = masterSelected[currentMasterTab].filter(v => normalizeMasterValue(v) !== norm);\n    if (checked) masterSelected[currentMasterTab].push(item);\n    renderMasterData();\n}\nfunction toggleMasterSelectAll(checked) {\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const hidden = db.hiddenItems[currentMasterTab] || [];\n    let filteredData = data.map((item, idx) => ({ item, idx }));\n    if (masterShowMode === 'visible') filteredData = filteredData.filter(({ item }) => !hidden.includes(item));\n    else if (masterShowMode === 'hidden') filteredData = filteredData.filter(({ item }) => hidden.includes(item));\n    if (masterSearch) filteredData = filteredData.filter(({ item }) => item.toLowerCase().includes(masterSearch.toLowerCase()));\n    if (checked) masterSelected[currentMasterTab] = filteredData.map(({ item }) => item);\n    else masterSelected[currentMasterTab] = [];\n    renderMasterData();\n}\nfunction toggleMasterPageSelection(checked) {\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const hidden = db.hiddenItems[currentMasterTab] || [];\n    let filteredData = data.map((item, idx) => ({ item, idx }));\n    if (masterShowMode === 'visible') filteredData = filteredData.filter(({ item }) => !hidden.includes(item));\n    else if (masterShowMode === 'hidden') filteredData = filteredData.filter(({ item }) => hidden.includes(item));\n    if (masterSearch) filteredData = filteredData.filter(({ item }) => item.toLowerCase().includes(masterSearch.toLowerCase()));\n    if (masterSort === 'alpha-asc') filteredData.sort((a, b) => a.item.localeCompare(b.item));\n    else if (masterSort === 'alpha-desc') filteredData.sort((a, b) => b.item.localeCompare(a.item));\n    const perPage = parseInt(masterPerPage) || 20;\n    const pageData = filteredData.slice((masterPage - 1) * perPage, masterPage * perPage);\n    if (!masterSelected[currentMasterTab]) masterSelected[currentMasterTab] = [];\n    const selected = masterSelected[currentMasterTab];\n    const pageNorms = new Set(pageData.map(({ item }) => normalizeMasterValue(item)));\n    masterSelected[currentMasterTab] = selected.filter(v => !pageNorms.has(normalizeMasterValue(v)));\n    if (checked) pageData.forEach(({ item }) => masterSelected[currentMasterTab].push(item));\n    renderMasterData();\n}\nfunction clearMasterSelection() {\n    masterSelected[currentMasterTab] = [];\n    renderMasterData();\n}\nfunction masterBulkAction(action) {\n    if (!requireMasterAccess('manage Master Data')) return;\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const selected = masterSelected[currentMasterTab] || [];\n    if (!selected.length) return alert('Select at least one item');\n    const selectedNorms = new Set(selected.map(normalizeMasterValue));\n    const hidden = db.hiddenItems[currentMasterTab] || [];\n    let changed = 0;\n    if (action === 'delete') {\n        if (!confirm(`Delete ${selected.length} selected item(s)?`)) return;\n        for (let i = data.length - 1; i >= 0; i--) {\n            if (selectedNorms.has(normalizeMasterValue(data[i]))) {\n                data.splice(i, 1);\n                changed++;\n            }\n        }\n        db.hiddenItems[currentMasterTab] = hidden.filter(item => !selectedNorms.has(normalizeMasterValue(item)));\n    } else if (action === 'hide') {\n        selected.forEach(item => {\n            if (!hidden.some(h => normalizeMasterValue(h) === normalizeMasterValue(item))) {\n                hidden.push(item);\n                changed++;\n            }\n        });\n        db.hiddenItems[currentMasterTab] = hidden;\n    } else if (action === 'show') {\n        const nextHidden = hidden.filter(item => selectedNorms.has(normalizeMasterValue(item)) ? (changed++, false) : true);\n        db.hiddenItems[currentMasterTab] = nextHidden;\n    }\n    masterSelected[currentMasterTab] = [];\n    saveDB();\n    renderMasterData();\n    populateDropdowns();\n    autoBackup();\n}\nfunction changeMasterPage(page) {\n    const listKey = getMasterListKey(currentMasterTab);\n    const data = db[listKey] || [];\n    const hidden = db.hiddenItems[currentMasterTab] || [];\n    let filteredData = data.map((item, idx) => ({ item, idx }));\n    if (masterShowMode === 'visible') filteredData = filteredData.filter(({ item }) => !hidden.includes(item));\n    else if (masterShowMode === 'hidden') filteredData = filteredData.filter(({ item }) => hidden.includes(item));\n    if (masterSearch) filteredData = filteredData.filter(({ item }) => item.toLowerCase().includes(masterSearch.toLowerCase()));\n    const perPage = parseInt(masterPerPage) || 20;\n    const totalPages = Math.ceil(filteredData.length / perPage) || 1;\n    if (page < 1 || page > totalPages) return;\n    masterPage = page;\n    renderMasterData();\n}\nfunction addMasterItem() {\n    if (!requireMasterAccess('add Master Data')) return;\n    const input = document.getElementById('new-master-item');\n    const val = input.value.trim();\n    if (!val) return alert('Enter a value');\n    const listKey = getMasterListKey(currentMasterTab);\n    const normalized = normalizeMasterValue(val);\n    if ((db[listKey] || []).some(item => normalizeMasterValue(item) === normalized)) return alert('Item already exists');\n    db[listKey].push(val);\n    saveDB();\n    input.value = '';\n    masterSelected[currentMasterTab] = [];\n    renderMasterData();\n    populateDropdowns();\n    autoBackup();\n}";
})(window);


/* ===== ORIGINAL MODULE: JS/carrier-charges-b.js ===== */
/* SHAHID ERP 2.0 modular source segment 21/59. Source is assembled in original order and executed as one classic script to preserve global declaration hoisting. */
(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[20] = "\nfunction addMultipleMasterItems() {\n    if (!requireMasterAccess('add Master Data')) return;\n    const textarea = document.getElementById('new-master-items');\n    const items = textarea.value.split(/[\\n.]+/).map(s => s.trim()).filter(s => s);\n    if (!items.length) return alert('Enter at least one item');\n    const listKey = getMasterListKey(currentMasterTab);\n    const existing = new Set((db[listKey] || []).map(normalizeMasterValue));\n    const batch = new Set();\n    let added = 0, skipped = 0;\n    items.forEach(raw => {\n        const item = raw.trim();\n        const norm = normalizeMasterValue(item);\n        if (!norm || existing.has(norm) || batch.has(norm)) { skipped++; return; }\n        batch.add(norm);\n        db[listKey].push(item.toUpperCase());\n        added++;\n    });\n    saveDB();\n    textarea.value = '';\n    masterSelected[currentMasterTab] = [];\n    renderMasterData();\n    populateDropdowns();\n    alert(`Added ${added} items${skipped ? `; skipped ${skipped} duplicate item(s)` : ''}`);\n    autoBackup();\n}\nfunction editMasterItem(tab, originalIdx) {\n    if (!requireMasterAccess('edit Master Data')) return;\n    const listKey = getMasterListKey(tab);\n    const data = db[listKey];\n    const item = data[originalIdx];\n    if (!item) return alert('Item not found');\n    appPrompt('Edit item:', item, (newVal) => {\n        if (newVal && newVal.trim() !== item) {\n            const cleaned = newVal.trim();\n            const norm = normalizeMasterValue(cleaned);\n            if (data.some((existing, idx) => idx !== originalIdx && normalizeMasterValue(existing) === norm)) return alert('Item already exists');\n            data[originalIdx] = cleaned;\n            saveDB();\n            masterSelected[tab] = [];\n            renderMasterData();\n            populateDropdowns();\n            autoBackup();\n        }\n    });\n}\nfunction toggleHiddenMasterItem(tab, originalIdx) {\n    if (!requireMasterAccess('change Master Data visibility')) return;\n    const listKey = getMasterListKey(tab);\n    const data = db[listKey];\n    const item = data[originalIdx];\n    if (!item) return;\n    const hidden = db.hiddenItems[tab] || [];\n    if (hidden.includes(item)) {\n        db.hiddenItems[tab] = hidden.filter(h => h !== item);\n    } else {\n        db.hiddenItems[tab].push(item);\n    }\n    saveDB();\n    masterSelected[tab] = [];\n    renderMasterData();\n    populateDropdowns();\n    autoBackup();\n}\nfunction deleteMasterItem(tab, originalIdx) {\n    if (!requireMasterAccess('delete Master Data')) return;\n    const listKey = getMasterListKey(tab);\n    const data = db[listKey];\n    const item = data[originalIdx];\n    if (!item) return alert('Item not found');\n    if (confirm(`Delete \"${item}\"?`)) {\n        data.splice(originalIdx, 1);\n        const hidden = db.hiddenItems[tab] || [];\n        if (hidden.includes(item)) {\n            db.hiddenItems[tab] = hidden.filter(h => h !== item);\n        }\n        saveDB();\n        masterSelected[tab] = [];\n        renderMasterData();\n        populateDropdowns();\n        autoBackup();\n    }\n}\n\n// ==================== EXCHANGE RATES ====================\nfunction renderExchangeRates() {\n    const table = document.getElementById('exchange-table');\n    if (!table) return;\n    table.innerHTML = `\n        <thead><tr><th>Currency</th><th>Rate (1 INR = ?)</th><th>Action</th></tr></thead>\n        <tbody>\n            ${Object.entries(db.exchangeRates).map(([cur, rate]) => `\n                <tr>\n                    <td><strong>${cur}</strong></td>\n                    <td><input type=\"number\" step=\"0.0001\" value=\"${rate}\" onchange=\"updateExchangeRate('${cur}', this.value)\" style=\"width:120px;padding:4px;border:1px solid var(--border);border-radius:3px;\" onfocus=\"highlightInput(this)\" onblur=\"unhighlightInput(this)\"></td>\n                    <td><button class=\"btn btn-sm btn-clear\" onclick=\"deleteExchangeRate('${cur}')\">\u00d7</button></td>\n                </tr>\n            `).join('')}\n        </tbody>\n    `;\n}\nfunction updateExchangeRate(currency, rate) {\n    const val = parseFloat(rate);\n    if (!isNaN(val) && val > 0) {\n        db.exchangeRates[currency] = val;\n        saveDB();\n        ['sea', 'air', 'lcl'].forEach(m => {\n            if (document.getElementById(m).classList.contains('active')) {\n                recalcTotal(m);\n            }\n        });\n        autoBackup();\n    }\n}\nfunction addExchangeRate() {\n    const cur = document.getElementById('new-currency').value.trim().toUpperCase();\n    const rate = parseFloat(document.getElementById('new-rate').value);\n    if (!cur || isNaN(rate) || rate <= 0) return alert('Enter valid currency and rate');\n    if (db.exchangeRates[cur]) return alert('Currency already exists');\n    db.exchangeRates[cur] = rate;\n    saveDB();\n    document.getElementById('new-currency').value = '';\n    document.getElementById('new-rate').value = '';\n    renderExchangeRates();\n    autoBackup();\n}\nfunction deleteExchangeRate(currency) {\n    if (currency === 'INR') return alert('Cannot delete INR');\n    if (confirm(`Delete exchange rate for ${currency}?`)) {\n        delete db.exchangeRates[currency];\n        saveDB();\n        renderExchangeRates();\n        autoBackup();\n    }\n}\n\n// ==================== COMPANY INFO ====================\nfunction saveCompanyInfo() {\n    const name = document.getElementById('company-name').value.trim();\n    const address = document.getElementById('company-address').value.trim();\n    if (!name) return alert('Company name is required');\n    db.companyName = name;\n    db.companyAddress = address;\n    saveDB();\n    document.getElementById('current-company-name').textContent = name;\n    alert('Company info saved!');\n    autoBackup();\n}\nfunction saveDefaultUser() {\n    const user = document.getElementById('default-user-input').value.trim();\n    if (!user) return alert('User name is required');\n    db.defaultUser = user;\n    saveDB();\n    document.getElementById('current-default-user').textContent = user;\n    alert('Default user saved!');\n    autoBackup();\n}\n\n// ==================== POPULATE DROPDOWNS ====================\nfunction populateSelect(id, values = [], selectedValue = '') {\n    const el = document.getElementById(id);\n    if (!el) return;\n    const list = Array.isArray(values) ? values : [];\n    const current = String(selectedValue ?? el.value ?? '').trim();\n    const unique = [...new Set(list.map(v => String(v ?? '').trim()).filter(Boolean))];\n    el.innerHTML = '<option value=\"\">Select</option>' + unique.map(v => `<option value=\"${escapeHtml(v)}\">${escapeHtml(v)}</option>`).join('');\n    if (current) {\n        const exact = unique.find(v => v === current);\n        const ci = unique.find(v => v.toLowerCase() === current.toLowerCase());\n        if (exact || ci) el.value = exact || ci;\n    }\n}\n\nfunction getMasterDropdownLists() {\n    // UI fallback only: never writes fallback values into db.\n    // This keeps older saved databases usable if a previous build stored an empty master array.\n    const embedded = (typeof EMBEDDED_BACKUP === 'object' && EMBEDDED_BACKUP) || {};\n    const carriers = Array.isArray(db.carriers) && db.carriers.length ? db.carriers : (embedded.carriers || []);\n    const pol = Array.isArray(db.pol) && db.pol.length ? db.pol : (embedded.pol || []);\n    const pod = Array.isArray(db.pod) && db.pod.length ? db.pod : (embedded.pod || []);\n    const containers = Array.isArray(db.containers) && db.containers.length ? db.containers : defaultContainerDimensions.map(x => x.type);\n    const incoterms = Array.isArray(db.incoterms) && db.incoterms.length ? db.incoterms : ['EXW','FCA','FOB','CFR','CIF','DAP','DDP'];\n    return { carriers, pol, pod, containers, incoterms };\n}\n\nfunction getJobReferenceList() {\n    const out = [];\n    const add = v => { const x = String(v ?? '').trim(); if (x && !out.includes(x)) out.push(x); };\n    (db.shipments || []).forEach(s => { add(s.jobNo); add(s.code); add(s.shipmentCode); });\n    ['sea','air','lcl'].forEach(m => (db.rates?.[m] || []).forEach(q => { add(q.jobNo); add(q.shipmentCode); }));\n    return out.sort((a,b) => a.localeCompare(b, undefined, {numeric:true, sensitivity:'base'}));\n}\n\nfunction getQuoteReferenceList() {\n    const out = [];\n    const add = v => {\n        const x = String(v ?? '').trim();\n        if (x && !out.some(y => y.toLowerCase() === x.toLowerCase())) out.push(x);\n    };\n    getAllRateQuoteRows().forEach(x => {\n        const q = x.data || {};\n        // Quote Ref is intentionally prioritised over JOB NO. so the dropdown\n        // shown from every JOB NO. field is useful for quote-driven auto-fill.\n        add(q.quoteNumber);\n        add(q.quoteNo);\n        add(q.quoteRef);\n        add(q.reference);\n        add(q.id);\n    });\n    (db.shipments || []).forEach(s => {\n        add(s.quoteRef);\n        add(s.quoteNumber);\n        add(s.rateQuoteRef);\n    });\n    return out.sort((a,b) => a.localeCompare(b, undefined, {numeric:true, sensitivity:'base'}));\n}\n\nfunction refreshJobReferenceDropdowns() {\n    const jobs = getJobReferenceList();\n    const quotes = getQuoteReferenceList();\n    const jobHtml = jobs.map(v => `<option value=\"${escapeHtml(v)}\">`).join('');\n    const quoteHtml = quotes.map(v => `<option value=\"${escapeHtml(v)}\">`).join('');\n\n    ['dsr-job-list','bl-job-list'].forEach(id => {\n        const el = document.getElementById(id);\n        if (el) el.innerHTML = jobHtml;\n    });\n\n    // Every JOB NO. input also exposes Quote Ref numbers in its dropdown.\n    // Selecting a Quote Ref is handled by the existing auto-fetch handlers.\n    ['dsr-job-quote-ref-list','bl-job-quote-ref-list'].forEach(id => {\n        const el = document.getElementById(id);\n        if (el) el.innerHTML = quoteHtml;\n    });\n\n    // Keep the dedicated Quote Ref controls synchronised as well.\n    ['dsr-quote-ref-list','bl-quote-ref-list'].forEach(id => {\n        const el = document.getElementById(id);\n        if (el) el.innerHTML = quoteHtml;\n    });\n}\n\nfunction refreshOperationalDropdowns() {\n    const {carriers, pol, pod, containers, incoterms} = getMasterDropdownLists();\n    const hidden = db.hiddenItems || {};\n    const visibleCarriers = ['ALL', ...carriers.filter(c => !(hidden.carriers || []).includes(c))];\n    const visiblePol = pol.filter(x => !(hidden.pol || []).includes(x));\n    const visiblePod = pod.filter(x => !(hidden.pod || []).includes(x));\n    const visibleContainers = containers.filter(x => !(hidden.containers || []).includes(x));\n    const visibleIncoterms = incoterms.filter(x => !(hidden.incoterms || []).includes(x));\n\n    ['sea','air','lcl'].forEach(mode => {\n        const setList = (id, vals) => { const el=document.getElementById(id); if(el) el.innerHTML=[...new Set(vals)].map(v=>`<option value=\"${escapeHtml(v)}\">`).join(''); };\n        setList(`${mode}-pol-list`, visiblePol);\n        setList(`${mode}-pod-list`, visiblePod);\n        setList(`${mode}-carrier-list`, visibleCarriers);\n        setList(`${mode}-incoterm-list`, visibleIncoterms);\n        setList(`${mode}-commodity-list`, ['NON HAZ','HAZ']);\n        if(mode==='sea') setList(`${mode}-container-list`, visibleContainers);\n    });\n\n    ['rr-pol-list-sea1','rr-pol-list-sea2','rr-pol-list-air'].forEach(id=>{ const el=document.getElementById(id); if(el) el.innerHTML=[...new Map(visiblePol.map(v=>[String(v).trim().toUpperCase(),v])).values()].map(v=>`<option value=\"${escapeHtml(v)}\">`).join(''); });\n    ['rr-pod-list-sea1','rr-pod-list-sea2','rr-pod-list-air'].forEach(id=>{ const el=document.getElementById(id); if(el) el.innerHTML=[...new Map(visiblePod.map(v=>[String(v).trim().toUpperCase(),v])).values()].map(v=>`<option value=\"${escapeHtml(v)}\">`).join(''); });\n    // Rate Request autocomplete lists (POL/POD + Commodity/Inventory/Free Time).\n    const rrInventoryValues = [...new Set(['20 GP & 40 HC', '20 GP', '40 HC', ...visibleContainers])];\n    ['sea1','sea2','air'].forEach(suffix => {\n        const setRRList = (id, vals) => {\n            const el = document.getElementById(id);\n            if (el) el.innerHTML = [...new Set(vals)].map(v => `<option value=\"${escapeHtml(v)}\">`).join('');\n        };\n        setRRList(`rr-commodity-list-${suffix}`, ['NON HAZ','HAZ']);\n        setRRList(`rr-inventory-list-${suffix}`, rrInventoryValues);\n        setRRList(`rr-freeTime-list-${suffix}`, ['14 Days','21 Days']);\n    });\n\n    // Any currently rendered DSR form.\n    if(document.getElementById('dsr-pol')) populateSelect('dsr-pol', visiblePol, document.getElementById('dsr-pol').value);\n    if(document.getElementById('dsr-pod')) populateSelect('dsr-pod', visiblePod, document.getElementById('dsr-pod').value);\n    if(document.getElementById('dsr-liner')) populateSelect('dsr-liner', visibleCarriers, document.getElementById('dsr-liner').value);\n    refreshJobReferenceDropdowns();\n}\n\nfunction populateDropdowns() {\n    if (!db.carriers) db.carriers = [];\n    if (!db.pol) db.pol = [];\n    if (!db.pod) db.pod = [];\n    if (!db.incoterms) db.incoterms = [];\n    if (!db.containers) db.containers = [];\n    if (!db.exchangeRates) db.exchangeRates = { USD: 94.50, INR: 1 };\n    const {carriers, pol, pod, containers, incoterms} = getMasterDropdownLists();\n    const hiddenCarriers = db.hiddenItems?.carriers || [];\n    const hiddenPol = db.hiddenItems?.pol || [];\n    const hiddenPod = db.hiddenItems?.pod || [];\n    const hiddenIncoterms = db.hiddenItems?.incoterms || [];\n    const hiddenContainers = db.hiddenItems?.containers || [];\n\n    const visibleCarriers = ['ALL', ...carriers.filter(c => !hiddenCarriers.includes(c))];\n    const visiblePol = pol.filter(p => !hiddenPol.includes(p));\n    const visiblePod = pod.filter(p => !hiddenPod.includes(p));\n    const visibleIncoterms = incoterms.filter(i => !hiddenIncoterms.includes(i));\n    const visibleContainers = containers.filter(c => !hiddenContainers.includes(c));\n\n    // For each mode, populate datalists and selects\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        // POL/POD datalists. SEA Import deliberately reverses the master lists.\n        const isImportContext = mode === 'sea-import' || ((mode === 'air' || mode === 'lcl') && String(window.__quoteDirection || 'EXPORT').toUpperCase() === 'IMPORT');\n        const polList = document.getElementById(`${mode}-pol-list`);\n        if (polList) polList.innerHTML = (isImportContext ? visiblePod : visiblePol).map(p => `<option value=\"${p}\">`).join('');\n        const podList = document.getElementById(`${mode}-pod-list`);\n        if (podList) podList.innerHTML = (isImportContext ? visiblePol : visiblePod).map(p => `<option value=\"${p}\">`).join('');\n        // Carrier datalist\n        const carrierList = document.getElementById(`${mode}-carrier-list`);\n        if (carrierList) carrierList.innerHTML = visibleCarriers.map(c => `<option value=\"${c}\">`).join('');\n\n        // Incoterm datalist\n        const incotermList = document.getElementById(`${mode}-incoterm-list`);\n        if (incotermList) incotermList.innerHTML = visibleIncoterms.map(i => `<option value=\"${i}\">`).join('');\n\n        // Container datalist (only for sea)\n        if (mode === 'sea' || mode === 'sea-import') {\n            const containerList = document.getElementById(`${mode}-container-list`);\n            if (containerList) containerList.innerHTML = visibleContainers.map(c => `<option value=\"${c}\">`).join('');\n        }\n\n        // Commodity datalist (common for all modes) \u2013 we can either use a fixed list or from db; we'll create a fixed one.\n        // We'll define a global commodity list or use the existing <select> options.\n        // For simplicity, we'll populate with the same values as the select: NON HAZ, HAZ.\n        const commodityList = document.getElementById(`${mode}-commodity-list`);\n        if (commodityList) {\n            commodityList.innerHTML = `<option value=\"NON HAZ\"><option value=\"HAZ\">`;\n        }\n    });\n    // Keep all dynamically rendered tabs synchronized as well.\n    refreshOperationalDropdowns();\n}\n\n\n// ==================== DEFAULT CHARGES MASTER ====================\nfunction renderDefaultChargesMaster(mode) {\n    const search = (document.getElementById(`dc-${mode}-search`)?.value || '').toLowerCase();\n    const sourceRecords = mode === 'sea' ? (db.defaultSeaCharges || []) :\n        mode === 'air' ? (db.defaultAirCharges || []) : (db.defaultLclCharges || []);\n    const records = sourceRecords\n        .map((rec, originalIdx) => ({ rec, originalIdx }))\n        .filter(({ rec }) => !rec.deleted);\n\n    const filterPol = document.getElementById(`dc-${mode}-filter-pol`)?.value || '';\n    const filtered = records\n        .filter(({ rec }) => {\n            const text = `${rec.pol || ''} ${rec.commodity || ''}`.toLowerCase();\n            if (search && !text.includes(search)) return false;\n            if (filterPol && rec.pol !== filterPol) return false;\n            return true;\n        });\n\n    const disp = document.getElementById(`dc-${mode}-master-table`);\n    if (!disp) return;\n\n    let html = `<table class=\"master-table\"><thead><tr>\n        <th style=\"width:30px;\"><input type=\"checkbox\" class=\"select-all-dc\" data-mode=\"${mode}\" /></th>\n        <th>POL</th><th>HAZ / NON HAZ</th><th>CONTAINER</th><th>CURRENCY</th><th>Charges</th><th>Valid From</th><th>Valid To</th><th>Updated</th></tr></thead><tbody>`;\n\n    const virtualRows = [];\n    filtered.forEach(({ rec, originalIdx }) => {\n        if (mode === 'sea') {\n            const groups = lcContainerRowsForDefault('sea', rec);\n            groups.forEach(group => {\n                const currencies = new Set(Object.values(group.charges || {}).map(v => v?.currency || 'INR'));\n                if (!currencies.size) currencies.add('INR');\n                currencies.forEach(currency => virtualRows.push({ rec, originalIdx, container: group.container, currency, charges: group.charges }));\n            });\n        } else {\n            const currencies = new Set(Object.values(rec.charges || {}).map(v => v?.currency || 'INR'));\n            if (!currencies.size) currencies.add('INR');\n            currencies.forEach(currency => virtualRows.push({ rec, originalIdx, container: 'ALL', currency, charges: rec.charges || {} }));\n        }\n    });\n\n    if (!virtualRows.length) {\n        html += `<tr><td colspan=\"9\" style=\"text-align:center;padding:16px;color:var(--text-light);\">No records.</td></tr>`;\n    } else {\n        virtualRows.forEach(({ rec, originalIdx, container, currency, charges }) => {\n            const chargeCount = Object.values(charges || {}).filter(v => (v?.currency || 'INR') === currency && Number(v?.amount || 0) > 0).length;\n            const created = rec.validFrom || '';\n            const validTo = rec.validTo || '';\n            const updated = rec.updatedAt ? new Date(rec.updatedAt).toLocaleDateString('en-IN') : '\u2014';\n            html += `<tr>\n                <td><input type=\"checkbox\" class=\"dc-checkbox\" data-mode=\"${mode}\" data-idx=\"${originalIdx}\" data-type=\"default\" /></td>\n                <td>${rec.pol || '\u2014'}</td>\n                <td>${rec.commodity || '\u2014'}</td>\n                <td>${container}</td>\n                <td><strong>${currency}</strong></td>\n                <td style=\"text-align:center;\"><strong>${chargeCount}</strong></td>\n                <td>${created || '\u2014'}</td><td>${validTo || '\u2014'}</td><td>${updated}</td>\n                </tr>`;\n        });\n    }\n    html += '</tbody></table>';\n    disp.innerHTML = html;\n\n    document.querySelectorAll('.select-all-dc').forEach(cb => {\n        cb.addEventListener('change', function() {\n            const mode = this.dataset.mode;\n            document.querySelectorAll(`.dc-checkbox[data-mode=\"${mode}\"][data-type=\"default\"]`).forEach(c => c.checked = this.checked);\n            updateSelectedCount();\n        });\n    });\n    document.querySelectorAll('.dc-checkbox').forEach(cb => cb.addEventListener('change', updateSelectedCount));\n    updateSelectedCount();\n    updateLocalChargeToolbar('dc', mode, virtualRows.length);\n}\n\n// ==================== SEA THC MASTER (DEDICATED) ====================\nfunction renderSeaTHCMaster(){\n    const disp=document.getElementById('sea-thc-master-table');\n    if(!disp) return;\n    const search=(document.getElementById('sea-thc-search')?.value||'').toLowerCase().trim();\n    const rows=(db.seaTHCRates||[]).map((rec,idx)=>({rec,idx})).filter(({rec})=>!rec.deleted).filter(({rec})=>{\n        const text=`${rec.carrier||''} ${rec.pol||''} ${rec.commodity||''} ${rec.currency||''}`.toLowerCase();\n        return !search || text.includes(search);\n    });\n    let html=`<table class=\"master-table\"><thead><tr><th style=\"width:30px;\"><input type=\"checkbox\" class=\"select-all-thc\" data-mode=\"sea\" /></th><th>Carrier</th><th>POL</th><th>Cargo</th><th>Currency</th><th>THC 20 GP</th><th>THC 40 HC</th><th>Valid From</th><th>Valid To</th><th>Updated</th></tr></thead><tbody>`;\n    if(!rows.length) html+=`<tr><td colspan=\"10\" style=\"text-align:center;padding:16px;color:var(--text-light);\">No SEA THC records.</td></tr>`;\n    rows.forEach(({rec,idx})=>{\n        html+=`<tr><td><input type=\"checkbox\" class=\"thc-checkbox\" data-mode=\"sea\" data-idx=\"${idx}\" /></td><td>${rec.carrier||'\u2014'}</td><td>${rec.pol||'\u2014'}</td><td>${rec.commodity||'\u2014'}</td><td><strong>${rec.currency||'INR'}</strong></td><td>${rec.thc20??'\u2014'}</td><td>${rec.thc40??'\u2014'}</td><td>${rec.validFrom||'\u2014'}</td><td>${rec.validTo||'\u2014'}</td><td>${rec.updated?new Date(rec.updated).toLocaleDateString('en-IN'):'\u2014'}</td></tr>`;\n    });\n    html+='</tbody></table>'; disp.innerHTML=html;\n    document.querySelectorAll('.select-all-thc').forEach(cb=>cb.addEventListener('change',function(){\n        document.querySelectorAll('.thc-checkbox[data-mode=\"sea\"]').forEach(c=>c.checked=this.checked);\n        updateSelectedCount(); updateLocalChargeToolbar('thc','sea',rows.length);\n    }));\n    document.querySelectorAll('.thc-checkbox').forEach(cb=>cb.addEventListener('change',function(){ updateSelectedCount(); updateLocalChargeToolbar('thc','sea',rows.length); }));\n    updateLocalChargeToolbar('thc','sea',rows.length);\n}\nfunction seaTHCFormHTML(rec={}){\n    const carrier=rec.carrier||'', pol=rec.pol||'', commodity=rec.commodity||'NON HAZ', currency=rec.currency||'INR';\n    return `<div class=\"form-grid-2col\">\n      <div class=\"form-group\"><label>Carrier</label><select id=\"modal-thc-carrier\"><option value=\"\">Select</option>${db.carriers.map(c=>`<option value=\"${c}\" ${c===carrier?'selected':''}>${c}</option>`).join('')}</select></div>\n      <div class=\"form-group\"><label>POL</label><select id=\"modal-thc-pol\"><option value=\"\">Select</option>${db.pol.map(p=>`<option value=\"${p}\" ${p===pol?'selected':''}>${p}</option>`).join('')}</select></div>\n      <div class=\"form-group\"><label>Cargo</label><select id=\"modal-thc-cargo\"><option value=\"NON HAZ\" ${commodity==='NON HAZ'?'selected':''}>NON HAZ</option><option value=\"HAZ\" ${commodity==='HAZ'?'selected':''}>HAZ</option></select></div>\n      <div class=\"form-group\"><label>Currency</label><select id=\"modal-thc-currency\"><option value=\"INR\" ${currency==='INR'?'selected':''}>INR</option><option value=\"USD\" ${currency==='USD'?'selected':''}>USD</option></select></div>\n      <div class=\"form-group\"><label>THC 20 GP</label><input type=\"number\" id=\"modal-thc20\" step=\"0.01\" value=\"${rec.thc20??''}\"></div>\n      <div class=\"form-group\"><label>THC 40 HC</label><input type=\"number\" id=\"modal-thc40\" step=\"0.01\" value=\"${rec.thc40??''}\"></div>\n      <div class=\"form-group\"><label>Valid From</label><input type=\"date\" id=\"modal-thc-from\" value=\"${rec.validFrom||''}\"></div>\n      <div class=\"form-group\"><label>Valid To</label><input type=\"date\" id=\"modal-thc-to\" value=\"${rec.validTo||''}\"></div>\n    </div>`;\n}\nfunction openAddSeaTHCModal(){\n    document.getElementById('modal-title').textContent='Add SEA THC Rate';\n    document.getElementById('previewBody').innerHTML=`<h3 style=\"color:var(--primary);margin-bottom:12px;\">Dedicated SEA THC \u2013 Carrier + POL + Cargo</h3>${seaTHCFormHTML()}<div style=\"margin-top:16px;text-align:right;\"><button class=\"btn btn-clear\" onclick=\"closeModal('previewModal')\">Cancel</button><button class=\"btn btn-quoted\" onclick=\"saveSeaTHC(null)\">Save</button></div>`;\n    openModal('previewModal');\n}\nfunction openEditSeaTHCModal(idx){\n    const rec=db.seaTHCRates?.[idx]; if(!rec) return alert('SEA THC record not found.');\n    document.getElementById('modal-title').textContent='Edit SEA THC Rate';\n    document.getElementById('previewBody').innerHTML=`<h3 style=\"color:var(--primary);margin-bottom:12px;\">Edit SEA THC \u2013 Carrier + POL + Cargo</h3>${seaTHCFormHTML(rec)}<div style=\"margin-top:16px;text-align:right;\"><button class=\"btn btn-clear\" onclick=\"closeModal('previewModal')\">Cancel</button><button class=\"btn btn-quoted\" onclick=\"saveSeaTHC(${idx})\">Save</button></div>`;\n    openModal('previewModal');\n}\nfunction saveSeaTHC(idx){\n    const carrier=document.getElementById('modal-thc-carrier').value.trim();\n    const pol=document.getElementById('modal-thc-pol').value.trim();\n    const commodity=document.getElementById('modal-thc-cargo').value.trim().toUpperCase();\n    const currency=document.getElementById('modal-thc-currency').value.trim().toUpperCase();\n    const thc20=parseFloat(document.getElementById('modal-thc20').value)||0;\n    const thc40=parseFloat(document.getElementById('modal-thc40').value)||0;\n    const validFrom=document.getElementById('modal-thc-from').value;\n    const validTo=document.getElementById('modal-thc-to').value;\n    if(!carrier||!pol||!['HAZ','NON HAZ'].includes(commodity)) return alert('Carrier, POL and HAZ/NON HAZ are required.');\n    if(!['INR','USD'].includes(currency)) return alert('Currency must be INR or USD.');\n    if(!thc20&&!thc40) return alert('Enter THC 20 GP or THC 40 HC.');\n    if(validFrom&&validTo&&validFrom>validTo) return alert('Valid From cannot be after Valid To.');\n    const duplicate=(db.seaTHCRates||[]).findIndex((r,i)=>i!==idx && r.carrier===carrier&&r.pol===pol&&r.commodity===commodity&&r.currency===currency);\n    if(duplicate>=0) return alert('Duplicate SEA THC record already exists for Carrier + POL + Cargo + Currency.');\n    const rec={mode:'sea',carrier,pol,commodity,currency,thc20:thc20||null,thc40:thc40||null,validFrom,validTo,updated:new Date().toISOString()};\n    if(idx===null) db.seaTHCRates.push(rec); else db.seaTHCRates[idx]=rec;\n    saveDB(); closeModal('previewModal'); renderSeaTHCMaster(); autoBackup();\n    alert(idx===null?'\u2705 SEA THC added.':'\u2705 SEA THC updated.');\n}\nfunction deleteSeaTHC(idx){ const rec=db.seaTHCRates?.[idx]; if(!rec||rec.deleted)return alert('Record not found.'); if(!confirm(`Delete SEA THC rate for ${rec.carrier} / ${rec.pol} / ${rec.commodity} / ${rec.currency}?`))return; markMasterChargeDeleted(db.seaTHCRates,idx); saveDB(); renderSeaTHCMaster(); autoBackup(); }\nfunction duplicateSeaTHC(idx){ const rec=db.seaTHCRates?.[idx]; if(!rec)return alert('Record not found.'); const copy={...rec,updated:new Date().toISOString()}; copy.carrier=rec.carrier+' (Copy)'; db.seaTHCRates.push(copy); saveDB(); renderSeaTHCMaster(); autoBackup(); }\nfunction previewSeaTHC(idx){ const r=db.seaTHCRates?.[idx]; if(!r)return alert('Record not found.'); document.getElementById('modal-title').textContent='SEA THC Rate Preview'; document.getElementById('previewBody').innerHTML=`<div class=\"preview-card\"><h3>Dedicated SEA THC</h3><div class=\"preview-grid\"><div class=\"item\"><span class=\"label\">Carrier</span><span class=\"value\">${r.carrier}</span></div><div class=\"item\"><span class=\"label\">POL</span><span class=\"value\">${r.pol}</span></div><div class=\"item\"><span class=\"label\">Cargo</span><span class=\"value\">${r.commodity}</span></div><div class=\"item\"><span class=\"label\">Currency</span><span class=\"value\">${r.currency}</span></div><div class=\"item\"><span class=\"label\">THC 20 GP</span><span class=\"value\">${r.thc20??'\u2014'}</span></div><div class=\"item\"><span class=\"label\">THC 40 HC</span><span class=\"value\">${r.thc40??'\u2014'}</span></div><div class=\"item\"><span class=\"label\">Valid From</span><span class=\"value\">${r.validFrom||'\u2014'}</span></div><div class=\"item\"><span class=\"label\">Valid To</span><span class=\"value\">${r.validTo||'\u2014'}</span></div></div></div>`; openModal('previewModal'); }\n\n// ==================== CARRIER CHARGES MASTER ====================\nfunction renderCarrierChargesMaster(type) {\n    const search = (document.getElementById(`cc-${type}-search`)?.value || '').toLowerCase();\n    let records = [];\n    let filterMode = '';\n\n    if (type === 'sealcl') {\n        records = db.carrierChargesSeaLcl;\n        filterMode = document.getElementById('cc-sealcl-filter-mode')?.value || '';\n    } else if (type === 'air') {\n        records = db.carrierChargesAir;\n    } else if (type === 'lcl') {\n        records = db.carrierChargesSeaLcl;\n        filterMode = 'lcl';\n    }\n\n    const filtered = records.map((rec, originalIdx) => ({ rec, originalIdx }))\n        .filter(({ rec }) => !rec.deleted)\n        .filter(({ rec }) => {\n            // Container no longer used for display, but we keep it in data for backward compatibility\n            const text = `${rec.carrier} ${rec.pol}`.toLowerCase();\n            if (search && !text.includes(search)) return false;\n            if (filterMode && rec.mode !== filterMode) return false;\n            return true;\n        });\n\n    const disp = document.getElementById(`cc-${type}-master-table`);\n    if (!disp) return;\n\n    let html = `<table class=\"master-table\"><thead><tr>\n        <th style=\"width:30px;\"><input type=\"checkbox\" class=\"select-all-cc\" data-type=\"${type}\" /></th>`;\n    // SEA THC is managed exclusively in the dedicated SEA THC table.\n    html += `<th>Carrier</th><th>POL</th><th>Commodity</th>`;\n    html += `<th>Charges</th>`;\n    html += `<th>Updated</th></tr></thead><tbody>`;\n\n    if (filtered.length === 0) {\n        const cols = (type === 'air' ? 6 : 5);\n        html += `<tr><td colspan=\"${cols}\" style=\"text-align:center;padding:16px;color:var(--text-light);\">No records.</td></tr>`;\n    } else {\n        filtered.forEach(({ rec, originalIdx }) => {\n            const chargeCount = Object.keys(rec.charges || {}).filter(k => k !== 'THC_20' && k !== 'THC_40' && k !== 'THC').length;\n            const updated = rec.updated ? new Date(rec.updated).toLocaleDateString('en-IN') : '\u2014';\n            html += `<tr>`;\n            html += `<td><input type=\"checkbox\" class=\"cc-checkbox\" data-type=\"${type}\" data-idx=\"${originalIdx}\" /></td>`;\n            html += `<td>${rec.carrier}</td><td>${rec.pol}</td>`;\n            html += `<td>${rec.commodity || '\u2014'}</td>`;\n            html += `<td style=\"text-align:center;\"><strong>${chargeCount}</strong></td>`;\n            html += `<td>${updated}</td></tr>`;\n        });\n    }\n    html += '</tbody></table>';\n    disp.innerHTML = html;\n\n    document.querySelectorAll('.select-all-cc').forEach(cb => {\n        cb.addEventListener('change', function() {\n            const type = this.dataset.type;\n            document.querySelectorAll(`.cc-checkbox[data-type=\"${type}\"]`).forEach(c => c.checked = this.checked);\n            updateSelectedCount();\n        });\n    });\n    document.querySelectorAll('.cc-checkbox').forEach(cb => {\n        cb.addEventListener('change', updateSelectedCount);\n    });\n    updateSelectedCount();\n    updateLocalChargeToolbar('cc', type, filtered.length);\n}";
})(window);


