(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[22] = "\nfunction saveEditCarrierCharge(type, idx) {\n    let arr;\n    if (type === 'sealcl') arr = db.carrierChargesSeaLcl;\n    else if (type === 'air') arr = db.carrierChargesAir;\n    else arr = db.carrierChargesSeaLcl;\n\n    if (!arr || idx < 0 || idx >= arr.length) {\n        alert('Record not found.');\n        return;\n    }\n    const rec = arr[idx];\n\n    // Collect data (container removed)\n    let carrier, pol, commodity, mode;\n    if (type === 'sealcl') {\n        mode = 'sea';\n        carrier = document.getElementById('modal-cc-carrier-edit').value.trim();\n        pol = document.getElementById('modal-cc-pol-edit').value.trim();\n        commodity = document.getElementById('modal-cc-commodity-edit').value.trim();\n        if (!carrier || !pol) return alert('Carrier and POL are required.');\n        // Handle THC\n        // We'll set later\n    } else if (type === 'air') {\n        carrier = document.getElementById('modal-cc-carrier-edit').value.trim();\n        pol = document.getElementById('modal-cc-pol-edit').value.trim();\n        commodity = document.getElementById('modal-cc-commodity-edit').value.trim();\n        if (!carrier || !pol) return alert('Carrier and POL are required.');\n        mode = 'air';\n    } else {\n        // LCL\n        mode = 'lcl';\n        carrier = document.getElementById('modal-cc-carrier-edit').value.trim();\n        pol = document.getElementById('modal-cc-pol-edit').value.trim();\n        commodity = document.getElementById('modal-cc-commodity-edit').value.trim();\n        if (!carrier || !pol) return alert('Carrier and POL are required.');\n    }\n\n    // Build charges from the list (other charges)\n    const charges = {};\n    document.querySelectorAll('#modal-cc-charges-list [data-charge-key]').forEach(row => {\n        const key = row.getAttribute('data-charge-key');\n        const sellAmt = parseFloat(row.querySelector('.modal-cc-sell-amt').value) || 0;\n        const sellCur = row.querySelector('.modal-cc-sell-cur').value;\n        const buyAmt = parseFloat(row.querySelector('.modal-cc-buy-amt').value) || 0;\n        const buyCur = row.querySelector('.modal-cc-buy-cur').value;\n        if (sellAmt > 0 || buyAmt > 0) {\n            charges[key] = { amount: sellAmt, currency: sellCur, buyAmount: buyAmt, buyCurrency: buyCur };\n        }\n    });\n\n    // Update rec \u2013 container removed\n    rec.mode = mode;\n    rec.carrier = carrier;\n    rec.pol = pol;\n    rec.commodity = commodity;\n    rec.charges = charges;\n    rec.updated = new Date().toISOString();\n\n    saveDB();\n    closeModal('previewModal');\n    renderCarrierChargesMaster(type);\n    alert('\u2705 Carrier charge updated.');\n    autoBackup();\n}\n\nfunction openAddCarrierChargeModal(type) {\n    const mode = (type === 'sealcl') ? 'sea' : (type === 'air' ? 'air' : 'lcl');\n    const modeCharges = getDefaultChargeTypes(mode);\n    let html = `<h3 style=\"color:var(--primary);margin-bottom:12px;\">Add Carrier-Wise Charge</h3><div class=\"form-grid-2col\">`;\n    if (type === 'sealcl') {\n        html += `<input type=\"hidden\" id=\"modal-cc-mode\" value=\"sea\" />`;\n    }\n    html += `<div class=\"form-group\"><label>Carrier</label><select id=\"modal-cc-carrier\"><option value=\"\">Select</option>${db.carriers.map(c => `<option value=\"${c}\">${c}</option>`).join('')}</select></div>`;\n    html += `<div class=\"form-group\"><label>POL</label><select id=\"modal-cc-pol\"><option value=\"\">Select</option>${db.pol.map(p => `<option value=\"${p}\">${p}</option>`).join('')}</select></div>`;\n    html += `<div class=\"form-group\"><label>Commodity</label><select id=\"modal-cc-commodity\"><option value=\"\">Select</option><option value=\"NON HAZ\">Non Haz</option><option value=\"HAZ\">Haz</option></select></div>`;\n    html += `</div>`;\n\n    html += `<h4 style=\"color:var(--primary);margin:12px 0 8px;\">Other Charges (Sell & Buy)</h4><div id=\"modal-cc-charges-list\"></div>\n    <div style=\"margin-top:8px;display:flex;gap:8px;align-items:end;\">\n        <div class=\"form-group\" style=\"flex:1;\"><label>Add Charge</label><select id=\"modal-cc-add-charge\">${modeCharges.map(c => `<option value=\"${c}\">${c}</option>`).join('')}</select></div>\n        <button class=\"btn btn-sm btn-success\" style=\"height:33px;\" onclick=\"addCCChargeToModal()\">+</button>\n    </div>\n    <div style=\"margin-top:16px;text-align:right;\">\n        <button class=\"btn btn-clear\" onclick=\"closeModal('previewModal')\">Cancel</button>\n        <button class=\"btn btn-quoted\" onclick=\"saveNewCarrierCharge('${type}')\">Save</button>\n    </div>`;\n    document.getElementById('modal-title').textContent = 'Add Carrier-Wise Charge';\n    document.getElementById('previewBody').innerHTML = html;\n    openModal('previewModal');\n}\n\nfunction saveNewCarrierCharge(type) {\n    let record;\n    if (type === 'sealcl') {\n        const mode = 'sea';\n        const carrier = document.getElementById('modal-cc-carrier').value;\n        const pol = document.getElementById('modal-cc-pol').value;\n        const commodity = document.getElementById('modal-cc-commodity').value;\n        if (!carrier || !pol) return alert('Carrier and POL are required');\n        record = { mode, carrier, pol, commodity, charges: {}, updated: new Date().toISOString() };\n        if (findCarrierChargeDuplicate(type, record)) return alert('Duplicate entry!');\n        db.carrierChargesSeaLcl.push(record);\n    } else if (type === 'air') {\n        const carrier = document.getElementById('modal-cc-carrier').value;\n        const pol = document.getElementById('modal-cc-pol').value;\n        const commodity = document.getElementById('modal-cc-commodity').value;\n        if (!carrier || !pol) return alert('Carrier and POL are required');\n        record = { carrier, pol, commodity, charges: {}, updated: new Date().toISOString() };\n        if (findCarrierChargeDuplicate(type, record)) return alert('Duplicate entry!');\n        db.carrierChargesAir.push(record);\n    } else {\n        // LCL\n        const mode = 'lcl';\n        const carrier = document.getElementById('modal-cc-carrier').value;\n        const pol = document.getElementById('modal-cc-pol').value;\n        const commodity = document.getElementById('modal-cc-commodity').value;\n        if (!carrier || !pol) return alert('Carrier and POL are required');\n        record = { mode, carrier, pol, commodity, charges: {}, updated: new Date().toISOString() };\n        if (findCarrierChargeDuplicate(type, record)) return alert('Duplicate entry!');\n        db.carrierChargesSeaLcl.push(record);\n    }\n\n    // Collect other charges (excluding THC_20/THC_40)\n    document.querySelectorAll('#modal-cc-charges-list [data-charge-key]').forEach(row => {\n        const key = row.getAttribute('data-charge-key');\n        const sellAmt = parseFloat(row.querySelector('.modal-cc-sell-amt').value) || 0;\n        const sellCur = row.querySelector('.modal-cc-sell-cur').value;\n        const buyAmt = parseFloat(row.querySelector('.modal-cc-buy-amt').value) || 0;\n        const buyCur = row.querySelector('.modal-cc-buy-cur').value;\n        if (sellAmt > 0 || buyAmt > 0) {\n            record.charges[key] = { amount: sellAmt, currency: sellCur, buyAmount: buyAmt, buyCurrency: buyCur };\n        }\n    });\n\n    saveDB();\n    closeModal('previewModal');\n    renderCarrierChargesMaster(type);\n    alert('Added!');\n    autoBackup();\n}\n\n// ==================== DELETE FUNCTIONS ====================\nfunction deleteDefaultChargeEntry(mode, idx) {\n    let arr;\n    if (mode === 'sea') arr = db.defaultSeaCharges;\n    else if (mode === 'air') arr = db.defaultAirCharges;\n    else arr = db.defaultLclCharges;\n\n    if (!arr || idx < 0 || idx >= arr.length) {\n        alert('Record not found.');\n        return;\n    }\n\n    const record = arr[idx];\n    if (!confirm(`Delete this default charge?\\n\\n${record.pol || 'N/A'} (${mode.toUpperCase()})`)) return;\n\n    // Re-check index in case array changed during confirm\n    if (idx >= arr.length) {\n        alert('Record already deleted.');\n        return;\n    }\n    if (!markMasterChargeDeleted(arr, idx)) return alert('Record not found.');\n    saveDB();\n    renderDefaultChargesMaster(mode);\n    autoBackup();\n}\n\n// Soft-delete master charge records so SQLite/backup merge cannot resurrect them.\nfunction markMasterChargeDeleted(arr, idx) {\n    const rec = arr?.[idx];\n    if (!rec) return false;\n    const now = new Date().toISOString();\n    rec.deleted = true;\n    rec.deletedAt = now;\n    rec.updatedAt = now;\n    rec.updated = now;\n    return true;\n}\n\n// ==================== PREVIEW FUNCTIONS ====================\nfunction previewDefaultCharge(mode, idx) {\n    let rec;\n    if (mode === 'sea') rec = db.defaultSeaCharges[idx];\n    else if (mode === 'air') rec = db.defaultAirCharges[idx];\n    else rec = db.defaultLclCharges[idx];\n    if (!rec) return alert('Record not found');\n\n    const isSea = (mode === 'sea');\n    const charges = rec.charges || {};\n    const modeLabel = { sea: 'SEA', air: 'AIR', lcl: 'LCL' }[mode];\n\n    let chargeRows = '';\n    let grandTotalSellINR = 0;\n\n    if (isSea) {\n        const baseNames = new Set();\n        Object.keys(charges).forEach(key => {\n            let base = key;\n            if (key.endsWith('_20') || key.endsWith('_40')) {\n                base = key.slice(0, -3);\n            }\n            baseNames.add(base);\n        });\n\n        let sr = 0;\n        baseNames.forEach(base => {\n            const v20 = charges[base + '_20'] || null;\n            const v40 = charges[base + '_40'] || null;\n\n            if (v20) {\n                sr++;\n                const sellINR = toINR(v20.amount, v20.currency);\n                grandTotalSellINR += sellINR;\n                chargeRows += `\n                    <tr>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${sr}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; font-weight: 600;\">${base} (20')</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(v20.amount).toLocaleString('en-IN')}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(v20.buyAmount || 0).toLocaleString('en-IN')}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${v20.currency || 'INR'}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right; font-weight: 600;\">${formatINR(sellINR)}</td>\n                    </tr>\n                `;\n            }\n            if (v40) {\n                sr++;\n                const sellINR = toINR(v40.amount, v40.currency);\n                grandTotalSellINR += sellINR;\n                chargeRows += `\n                    <tr>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${sr}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; font-weight: 600;\">${base} (40')</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(v40.amount).toLocaleString('en-IN')}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(v40.buyAmount || 0).toLocaleString('en-IN')}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${v40.currency || 'INR'}</td>\n                        <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right; font-weight: 600;\">${formatINR(sellINR)}</td>\n                    </tr>\n                `;\n            }\n        });\n    } else {\n        let sr = 0;\n        Object.entries(charges).forEach(([chargeName, val]) => {\n            sr++;\n            const sellINR = toINR(val.amount, val.currency);\n            grandTotalSellINR += sellINR;\n            chargeRows += `\n                <tr>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${sr}</td>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; font-weight: 600;\">${chargeName}</td>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(val.amount).toLocaleString('en-IN')}</td>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right;\">${Number(val.buyAmount || 0).toLocaleString('en-IN')}</td>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: center;\">${val.currency || 'INR'}</td>\n                    <td style=\"padding: 6px 10px; border-bottom: 1px solid #e2e8f0; text-align: right; font-weight: 600;\">${formatINR(sellINR)}</td>\n                </tr>\n            `;\n        });\n    }\n\n    const html = `\n        <div style=\"font-family: 'Segoe UI', Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 10px;\">\n            <div style=\"background: linear-gradient(135deg, #1e3a8a, #3b82f6); color: white; padding: 16px 20px; border-radius: 12px 12px 0 0; margin-bottom: 0;\">\n                <div style=\"display: flex; justify-content: space-between; align-items: center;\">\n                    <div style=\"font-size: 1.2rem; font-weight: 700;\">\ud83d\udccb Default Charges Preview</div>\n                    <div style=\"background: rgba(255,255,255,0.2); padding: 4px 14px; border-radius: 20px; font-size: 0.8rem; font-weight: 600;\">${modeLabel}</div>\n                </div>\n            </div>\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 12px; background: white; padding: 16px 20px; border-left: 1px solid #e2e8f0; border-right: 1px solid #e2e8f0;\">\n                <div><span style=\"font-weight: 600; color: #64748b; font-size: 0.7rem; text-transform: uppercase; display: block;\">POL</span><span style=\"font-weight: 700;\">${rec.pol}</span></div>\n                <div><span style=\"font-weight: 600; color: #64748b; font-size: 0.7rem; text-transform: uppercase; display: block;\">Commodity</span><span style=\"font-weight: 700;\">${rec.commodity || '\u2014'}</span></div>\n            </div>\n            <div style=\"background: white; border: 1px solid #e2e8f0; border-radius: 0 0 12px 12px; overflow: hidden; margin-top: 0;\">\n                <div style=\"padding: 10px 16px; background: #f8fafc; border-bottom: 1px solid #e2e8f0; font-weight: 700; color: #1e3a8a;\">\ud83d\udcb2 Charges Breakdown</div>\n                <div style=\"overflow-x: auto;\">\n                    <table style=\"width: 100%; border-collapse: collapse; font-size: 0.85rem;\">\n                        <thead>\n                            <tr style=\"background: #f1f5f9;\">\n                                <th style=\"padding: 8px 12px; text-align: center; border-bottom: 1px solid #e2e8f0;\">#</th>\n                                <th style=\"padding: 8px 12px; text-align: left; border-bottom: 1px solid #e2e8f0;\">Charge Name</th>\n                                <th style=\"padding: 8px 12px; text-align: right; border-bottom: 1px solid #e2e8f0;\">Sell Amt</th>\n                                <th style=\"padding: 8px 12px; text-align: right; border-bottom: 1px solid #e2e8f0;\">Buy Amt</th>\n                                <th style=\"padding: 8px 12px; text-align: center; border-bottom: 1px solid #e2e8f0;\">Currency</th>\n                                <th style=\"padding: 8px 12px; text-align: right; border-bottom: 1px solid #e2e8f0;\">INR Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            ${chargeRows || `<tr><td colspan=\"6\" style=\"padding: 20px; text-align: center; color: #94a3b8;\">No charges found</td></tr>`}\n                        </tbody>\n                        <tfoot>\n                            <tr style=\"background: linear-gradient(135deg, #10b981, #059669); color: white; font-weight: 700; font-size: 1rem;\">\n                                <td colspan=\"5\" style=\"padding: 8px 12px; text-align: right;\">\ud83d\udcb0 Grand Total(INR)</td>\n                                <td style=\"padding: 8px 12px; text-align: right;\">${formatINR(grandTotalSellINR)}</td>\n                            </tr>\n                        </tfoot>\n                    </table>\n                </div>\n            </div>\n        </div>\n    `;\n\n    document.getElementById('modal-title').textContent = `Preview Default ${mode.toUpperCase()} Charge`;\n    document.getElementById('previewBody').innerHTML = html;\n    openModal('previewModal');\n}\n\n\nfunction duplicateDefaultCharge(mode, idx) {\n    let rec;\n    if (mode === 'sea') rec = db.defaultSeaCharges[idx];\n    else if (mode === 'air') rec = db.defaultAirCharges[idx];\n    else rec = db.defaultLclCharges[idx];\n    if (!rec) return alert('Record not found');\n    const copy = JSON.parse(JSON.stringify(rec));\n    if (mode === 'sea') {\n        copy.carrier = rec.carrier + ' (Copy)';\n    } else {\n        copy.pol = rec.pol + ' (Copy)';\n    }\n    copy.createdAt = new Date().toISOString();\n    copy.updatedAt = copy.createdAt;\n    if (mode === 'sea') db.defaultSeaCharges.push(copy);\n    else if (mode === 'air') db.defaultAirCharges.push(copy);\n    else db.defaultLclCharges.push(copy);\n    saveDB();\n    renderDefaultChargesMaster(mode);\n    alert('Default charge duplicated successfully!');\n}\n\n\nfunction deleteCarrierChargeEntry(type, idx) {\n    let arr;\n    if (type === 'sealcl') arr = db.carrierChargesSeaLcl;\n    else if (type === 'air') arr = db.carrierChargesAir;\n    else arr = db.carrierChargesSeaLcl;\n\n    if (!arr || idx < 0 || idx >= arr.length) {\n        alert('Record not found.');\n        return;\n    }\n\n    const record = arr[idx];\n    if (!confirm(`Delete this carrier charge?\\n\\n${record.carrier} (${record.pol})`)) return;\n\n    if (idx >= arr.length) {\n        alert('Record already deleted.');\n        return;\n    }\n    if (!markMasterChargeDeleted(arr, idx)) return alert('Record not found.');\n    saveDB();\n    renderCarrierChargesMaster(type);\n    autoBackup();\n}\n\n\nfunction previewCarrierCharge(type, idx) {\n    let rec = type === 'sealcl' ? db.carrierChargesSeaLcl[idx] : db.carrierChargesAir[idx];\n    if (!rec) return alert('Record not found');\n    \n    let html = `\n        <div class=\"preview-card\">\n            <h3>Carrier Charge Details</h3>\n            <div class=\"preview-grid\">\n                <div class=\"item\"><span class=\"label\">Mode</span><span class=\"value\">${type.toUpperCase()}</span></div>\n                <div class=\"item\"><span class=\"label\">Carrier</span><span class=\"value\">${rec.carrier}</span></div>\n                <div class=\"item\"><span class=\"label\">POL</span><span class=\"value\">${rec.pol}</span></div>\n                <div class=\"item\"><span class=\"label\">Commodity</span><span class=\"value\">${rec.commodity || '\u2014'}</span></div>\n                <div class=\"item\"><span class=\"label\">Updated</span><span class=\"value\">${rec.updated ? new Date(rec.updated).toLocaleString() : '\u2014'}</span></div>\n            </div>\n        </div>\n        <div class=\"preview-card\">\n            <h3>Other Charges</h3>\n            <table class=\"preview-charges-table\">\n                <thead><tr><th>Charge Name</th><th>Sell Amount</th><th>Buy Amount</th><th>Currency</th></tr></thead>\n                <tbody>`;\n    \n    let hasCharges = false;\n    for (const [k, v] of Object.entries(rec.charges)) {\n        if (k === 'THC_20' || k === 'THC_40') continue;\n        hasCharges = true;\n        html += `<tr><td>${k}</td><td>${v.amount || '\u2014'}</td><td>${v.buyAmount || '\u2014'}</td><td>${v.currency || 'INR'}</td></tr>`;\n    }\n    if (!hasCharges) {\n        html += `<tr><td colspan=\"4\" style=\"text-align:center;color:var(--text-light);\">No additional charges</td></tr>`;\n    }\n    html += `</tbody></table></div>`;\n    \n    document.getElementById('modal-title').textContent = 'Preview Carrier Charge';\n    document.getElementById('previewBody').innerHTML = html;\n    openModal('previewModal');\n}\n\n\nfunction duplicateCarrierCharge(type, idx) {\n    let rec = type === 'sealcl' ? db.carrierChargesSeaLcl[idx] : db.carrierChargesAir[idx];\n    if (!rec) return alert('Record not found');\n    const copy = JSON.parse(JSON.stringify(rec));\n    copy.carrier = rec.carrier + ' (Copy)';\n    copy.updated = new Date().toISOString();\n    if (type === 'sealcl') db.carrierChargesSeaLcl.push(copy);\n    else db.carrierChargesAir.push(copy);\n    saveDB();\n    renderCarrierChargesMaster(type);\n    alert('Carrier charge duplicated successfully!');\n}\n\n// ==================== HELPER FUNCTIONS ====================\nfunction getDefaultChargeTypes(mode) {\n    return defaultCharges[mode] || [];\n}\n\n// Return the horizontal carrier-charge columns used by AIR/LCL Local Charges.\n// Freight itself is handled by the quote/freight layer, while custom carrier\n// charge names already stored in the database are preserved and included.\nfunction getHorizontalChargeColumns(mode) {\n    const m = String(mode || '').toLowerCase();\n    const freightName = m === 'air' ? 'AIR FREIGHT' : m === 'lcl' ? 'FREIGHT' : '';\n    const columns = [];\n\n    (getDefaultChargeTypes(m) || []).forEach(name => {\n        const key = String(name || '').trim().toUpperCase();\n        if (!key || key === freightName || /^THC(?:_|$)/i.test(key)) return;\n        if (!columns.includes(key)) columns.push(key);\n    });\n\n    const existing = m === 'air'\n        ? (Array.isArray(db.carrierChargesAir) ? db.carrierChargesAir : [])\n        : (Array.isArray(db.carrierChargesSeaLcl) ? db.carrierChargesSeaLcl : []).filter(r => String(r.mode || '').toLowerCase() === m);\n\n    existing.forEach(rec => {\n        Object.keys(rec && rec.charges || {}).forEach(name => {\n            const key = String(name || '').trim().toUpperCase();\n            if (!key || key === freightName || /^THC(?:_|$)/i.test(key)) return;\n            if (!columns.includes(key)) columns.push(key);\n        });\n    });\n\n    return columns;\n}\n\nfunction findDefaultChargeDuplicate(mode, record, excludeIndex) {\n    let arr;\n    if (mode === 'sea') arr = db.defaultSeaCharges;\n    else if (mode === 'air') arr = db.defaultAirCharges;\n    else arr = db.defaultLclCharges;\n    return arr.some((r, i) => {\n        if (i === excludeIndex) return false;\n        return r.pol === record.pol && r.commodity === record.commodity;\n    });\n}\n\nfunction findCarrierChargeDuplicate(type, record, excludeIndex) {\n    let arr;\n    if (type === 'sealcl') arr = db.carrierChargesSeaLcl;\n    else if (type === 'air') arr = db.carrierChargesAir;\n    else arr = db.carrierChargesSeaLcl;\n    return arr.some((r, i) => {\n        if (i === excludeIndex) return false;\n        if (type === 'sealcl') {\n            return r.mode === record.mode &&\n                   r.carrier === record.carrier &&\n                   r.pol === record.pol &&\n                   r.commodity === record.commodity; // container removed\n        } else {\n            return r.carrier === record.carrier &&\n                   r.pol === record.pol &&\n                   r.commodity === record.commodity;\n        }\n    });\n}\n\n// ==================== LOGIN, SECURITY & USER MANAGEMENT ====================\nconst AUTH_CONFIG = {\n    idleTimeoutMs: 30 * 60 * 1000,\n    lockoutMs: 5 * 60 * 1000,\n    maxAttempts: 5,\n    sessionKey: 'loggedInUser',\n    sessionStartedKey: 'erpSessionStartedAt',\n    lastActivityKey: 'erpLastActivityAt',\n    failKey: 'erpLoginFailures',\n    rememberKey: 'erpRememberedLogin'\n};\n\nconst SHAHID_RBAC = Object.freeze({\n    roles: Object.freeze({ MASTER: 'master', DSR_USER: 'dsr_user' }),\n    permissions: Object.freeze({ FULL_ACCESS: '*', DSR: 'dsr', BL_DRAFT: 'bldraft', INVOICE: 'invoice' }),\n    dsrTabs: Object.freeze(['dsr', 'bldraft', 'invoice'])\n});\n\nlet authIdleTimer = null;\nlet alertCenterOpen = false;\n\nfunction getCurrentUserPermissions(user = checkLogin()) {\n    if (!user) return [];\n    if (user.role === SHAHID_RBAC.roles.MASTER || user.permissions === SHAHID_RBAC.permissions.FULL_ACCESS) return ['*'];\n    return Array.isArray(user.permissions) ? user.permissions.slice() : [];\n}\nfunction hasPermission(permission, user = checkLogin()) {\n    if (!user) return false;\n    const permissions = getCurrentUserPermissions(user);\n    return permissions.includes('*') || permissions.includes(permission);\n}\nfunction hasTabAccess(tabId, user = checkLogin()) {\n    if (!user || !tabId) return false;\n    if (user.role === SHAHID_RBAC.roles.MASTER || user.permissions === '*') return true;\n\n    // Quote hub permissions control the underlying SEA/AIR/LCL quote forms.\n    // The navigation hub uses export-quote/import-quote, while the actual\n    // rendered forms use sea/air/lcl/sea-import as their internal tab IDs.\n    // Normalize those internal IDs before checking RBAC so a user who has\n    // Export Quote access is not incorrectly blocked after selecting SEA/AIR/LCL.\n    const accessKeyMap = {\n        sea: 'export-quote',\n        air: 'export-quote',\n        lcl: 'export-quote',\n        'sea-import': 'import-quote',\n        'recycle-bin': 'database'\n    };\n    const accessKey = accessKeyMap[String(tabId).toLowerCase()] || tabId;\n    return Array.isArray(user.permissions) && user.permissions.includes(accessKey);\n}\nfunction requireTabAccess(tabId, action = 'open this module') {\n    const user = checkLogin();\n    if (!user) { alert('Please login again to continue.'); return false; }\n    if (!hasTabAccess(tabId, user)) { alert(`You do not have permission to ${action}.`); return false; }\n    return true;\n}\nfunction isMasterUser(user = checkLogin()) {\n    return !!user && (user.role === SHAHID_RBAC.roles.MASTER || user.permissions === '*');\n}\nfunction updateLoggedInUserBadge() {\n    const user = checkLogin();\n    let badge = document.getElementById('shahid-current-user-badge');\n    if (!badge) {\n        const headerActions = document.querySelector('.header-actions');\n        if (!headerActions) return;\n        badge = document.createElement('div');\n        badge.id = 'shahid-current-user-badge';\n        badge.style.cssText = 'display:flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid var(--border);border-radius:8px;background:var(--bg);font-size:.72rem;line-height:1.15;white-space:nowrap;';\n        headerActions.insertBefore(badge, headerActions.querySelector('.logout-btn') || null);\n    }\n    if (!user) { badge.style.display='none'; return; }\n    badge.style.display='flex';\n    const roleLabel = isMasterUser(user) ? 'MASTER' : 'DSR USER';\n    badge.innerHTML = `<span>\ud83d\udc64</span><span><strong>${escapeHtml(user.name || user.id)}</strong><br><small>${roleLabel}</small></span>`;\n}\nfunction applyRoleVisibility() {\n    const user = checkLogin();\n    if (!user) return;\n    const dsrOnly = !isMasterUser(user);\n    ['global-search','action-center-header-badge','alertCenterBtn'].forEach(id => {\n        const el=document.getElementById(id);\n        if (!el) return;\n        const host=el.closest('.global-search-wrapper, .header-action-center-btn, .alert-center-wrap') || el;\n        host.style.display=dsrOnly?'none':'';\n    });\n    document.querySelectorAll('.nav-category').forEach(category => {\n        const visible=[...category.querySelectorAll('.tab-btn-vertical')].some(btn => hasTabAccess(btn.dataset.tab,user));\n        category.style.display=visible?'':'none';\n    });\n    updateLoggedInUserBadge();\n}\n\nfunction getAuthFailures(){\n    try { return JSON.parse(localStorage.getItem(AUTH_CONFIG.failKey) || '{\"count\":0,\"until\":0}'); }\n    catch(e){ return {count:0,until:0}; }\n}\nfunction setAuthFailures(v){ localStorage.setItem(AUTH_CONFIG.failKey, JSON.stringify(v)); }\nfunction resetAuthFailures(){ localStorage.removeItem(AUTH_CONFIG.failKey); }\nfunction isLoginLocked(){\n    const f=getAuthFailures();\n    if(f.until && Date.now()<f.until) return true;\n    if(f.until && Date.now()>=f.until) resetAuthFailures();\n    return false;\n}\nfunction lockRemainingMs(){ const f=getAuthFailures(); return Math.max(0,(f.until||0)-Date.now()); }\nfunction formatDuration(ms){ const sec=Math.ceil(ms/1000); const m=Math.floor(sec/60); const s=sec%60; return `${m}m ${String(s).padStart(2,'0')}s`; }\n\nfunction loadRememberedLogin(){\n    try {\n        const raw=localStorage.getItem(AUTH_CONFIG.rememberKey);\n        if(!raw) return;\n        const saved=JSON.parse(raw);\n        const idEl=document.getElementById('login-id');\n        const rememberEl=document.getElementById('remember-login');\n        if(idEl && saved.id) idEl.value=saved.id;\n        // Security migration: older builds stored the plaintext password.\n        // Keep only the remembered User ID and immediately remove the password.\n        if(saved && Object.prototype.hasOwnProperty.call(saved,'password')){\n            localStorage.setItem(AUTH_CONFIG.rememberKey, JSON.stringify({id:String(saved.id||'')}));\n        }\n        if(rememberEl) rememberEl.checked=!!saved.id;\n    } catch(e){\n        localStorage.removeItem(AUTH_CONFIG.rememberKey);\n    }\n}\nfunction saveRememberedLogin(id){\n    const rememberEl=document.getElementById('remember-login');\n    try {\n        if(rememberEl?.checked){\n            // Never persist the password. Only the User ID is remembered.\n            localStorage.setItem(AUTH_CONFIG.rememberKey, JSON.stringify({id:String(id||'')}));\n        } else {\n            localStorage.removeItem(AUTH_CONFIG.rememberKey);\n        }\n    } catch(e){ console.warn('Remember login save skipped:', e); }\n}\nasync function sha256(text){\n    if(window.crypto?.subtle){\n        const data=new TextEncoder().encode(text);\n        const hash=await crypto.subtle.digest('SHA-256',data);\n        return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');\n    }\n    // Compatibility fallback; real production security should use a server-side password verifier.\n    return text;\n}\nfunction normalizeUser(user){\n    if(!user) return null;\n    return {id:user.id,name:user.name||user.id,role:user.role||'user',permissions:user.permissions||[],passwordHash:user.passwordHash||null};\n}\nfunction requireMasterAccess(action = 'perform this action') {\n    const user = checkLogin();\n    if (!user) {\n        alert('Please login again to continue.');\n        return false;\n    }\n    const allowed = isMasterUser(user);\n    if (!allowed) {\n        alert(`You do not have permission to ${action}.`);\n        return false;\n    }\n    return true;\n}\n\nfunction getLoggedInUserName() {\n    try { const user=checkLogin(); return user ? (user.name||user.id||null) : null; } catch(e){ return null; }\n}\nfunction checkLogin() {\n    try {\n        const raw=sessionStorage.getItem(AUTH_CONFIG.sessionKey);\n        if(!raw) return null;\n        const sessionUser=JSON.parse(raw);\n        const last=Number(sessionStorage.getItem(AUTH_CONFIG.lastActivityKey)||0);\n        if(last && Date.now()-last>AUTH_CONFIG.idleTimeoutMs){ performLogout(true); return null; }\n\n        // Keep the active session synchronized with the current runtime user\n        // record. This is important after permissions are amended in\n        // default-data.js or migrated into an existing local database: an old\n        // session must not retain stale tab permissions. Password/session\n        // credentials are not changed here.\n        const liveUser = Array.isArray(db?.users)\n            ? db.users.find(u => String(u?.id || '').toLowerCase() === String(sessionUser?.id || '').toLowerCase())\n            : null;\n        if (liveUser) {\n            const mergedUser = { ...sessionUser, ...liveUser };\n            sessionStorage.setItem(AUTH_CONFIG.sessionKey, JSON.stringify(mergedUser));\n            return mergedUser;\n        }\n        return sessionUser;\n    } catch(e){ sessionStorage.removeItem(AUTH_CONFIG.sessionKey); return null; }\n}\nfunction markAuthActivity(){\n    if(sessionStorage.getItem(AUTH_CONFIG.sessionKey)) sessionStorage.setItem(AUTH_CONFIG.lastActivityKey,String(Date.now()));\n}\nfunction startAuthWatchdog(){\n    clearInterval(authIdleTimer);\n    authIdleTimer=setInterval(()=>{\n        const user=checkLogin();\n        if(user){\n            const last=Number(sessionStorage.getItem(AUTH_CONFIG.lastActivityKey)||0);\n            if(last && Date.now()-last>AUTH_CONFIG.idleTimeoutMs){ performLogout(true); }\n        }\n    },15000);\n    ['click','keydown','mousemove','touchstart','scroll'].forEach(evt=>document.addEventListener(evt,markAuthActivity,{passive:true}));\n}\nfunction showLoginError(message, locked=false){\n    const errorEl=document.getElementById('login-error'); const box=document.querySelector('#login-overlay .login-box');\n    if(errorEl){ errorEl.textContent=message; errorEl.style.display='block'; }\n    if(box) box.classList.toggle('login-locked',locked);\n}\nfunction updateLoginLockUI(){\n    const btn=document.getElementById('login-submit'); const existing=document.getElementById('login-lock-message');\n    const locked=isLoginLocked();\n    if(btn) btn.disabled=locked;\n    if(locked){\n        const msg=`Too many failed attempts. Try again in ${formatDuration(lockRemainingMs())}.`;\n        showLoginError(msg,true);\n        if(!existing){ const el=document.createElement('div'); el.id='login-lock-message'; el.className='login-lock-message'; el.textContent=msg; document.querySelector('.login-form')?.appendChild(el); }\n        else existing.textContent=msg;\n    } else if(existing){ existing.remove(); }\n    return locked;\n}\nasync function securePasswordHash(password, saltB64) {\n    if (!window.crypto?.subtle) throw new Error('Web Crypto is required for secure password storage.');\n    const salt = saltB64 ? Uint8Array.from(atob(saltB64), c => c.charCodeAt(0)) : crypto.getRandomValues(new Uint8Array(16));\n    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);\n    const bits = await crypto.subtle.deriveBits({name:'PBKDF2', salt, iterations:150000, hash:'SHA-256'}, key, 256);\n    const hash = btoa(String.fromCharCode(...new Uint8Array(bits)));\n    return {hash, salt: btoa(String.fromCharCode(...salt)), algorithm:'PBKDF2-SHA256', iterations:150000};\n}\nasync function verifySecurePassword(password, user) {\n    if (!user?.passwordHashV2 || !user?.passwordSalt) return false;\n    const result = await securePasswordHash(password, user.passwordSalt);\n    return result.hash === user.passwordHashV2;\n}\nasync function performLogin() {\n    if(updateLoginLockUI()) return;\n    const id=(document.getElementById('login-id')?.value||'').trim();\n    const pass=(document.getElementById('login-password')?.value||'').trim();\n    if(!id||!pass){ showLoginError('Please enter User ID and Password.'); return; }\n    const btn=document.getElementById('login-submit'); if(btn) btn.disabled=true;\n    try{\n        const user=db.users.find(u=>String(u.id).toLowerCase()===id.toLowerCase());\n        const hash=await sha256(pass);\n        const valid=user && ((user.passwordHashV2 && await verifySecurePassword(pass,user)) || (user.passwordHash && user.passwordHash===hash));\n        if(!valid){\n            const f=getAuthFailures(); f.count=(f.count||0)+1;\n            if(f.count>=AUTH_CONFIG.maxAttempts){ f.until=Date.now()+AUTH_CONFIG.lockoutMs; }\n            setAuthFailures(f);\n            const remaining=Math.max(0,AUTH_CONFIG.maxAttempts-f.count);\n            if(f.until) showLoginError(`Too many failed attempts. Try again in ${formatDuration(AUTH_CONFIG.lockoutMs)}.`,true);\n            else showLoginError(`Invalid User ID or Password.${remaining?` ${remaining} attempt(s) remaining.`:''}`);\n            updateLoginLockUI(); return;\n        }\n        // Legacy SHA-256 hashes remain readable for backward compatibility.\n        // Plaintext passwords are never accepted or stored by the current engine.\n        if(user.password){ delete user.password; user.passwordHash=hash; saveDB(); }\n        resetAuthFailures();\n        saveRememberedLogin(id, pass);\n        const safeUser=normalizeUser(user);\n        sessionStorage.setItem(AUTH_CONFIG.sessionKey,JSON.stringify(safeUser));\n        sessionStorage.setItem(AUTH_CONFIG.sessionStartedKey,String(Date.now()));\n        sessionStorage.setItem(AUTH_CONFIG.lastActivityKey,String(Date.now()));\n        const overlay=document.getElementById('login-overlay'); if(overlay) overlay.classList.add('hidden');\n        const err=document.getElementById('login-error'); if(err) err.style.display='none';\n        applyPermissions(); updateLoggedInUserBadge(); startAuthWatchdog(); init();\n    }catch(e){ console.error(e); showLoginError('Login service error. Please refresh and try again.'); }\n    finally{ if(btn && !isLoginLocked()) btn.disabled=false; }\n}";
})(window);


