(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[23] = "\nfunction performLogout(auto=false){\n    sessionStorage.removeItem(AUTH_CONFIG.sessionKey); sessionStorage.removeItem(AUTH_CONFIG.sessionStartedKey); sessionStorage.removeItem(AUTH_CONFIG.lastActivityKey);\n    if(auto) sessionStorage.setItem('erpLogoutReason','Your session expired after 30 minutes of inactivity.');\n    else sessionStorage.removeItem('erpLogoutReason');\n    const badge=document.getElementById('shahid-current-user-badge');\n    if(badge) badge.style.display='none';\n    location.reload();\n}\nfunction applyPermissions() {\n    const user=checkLogin();\n    if(!user) return;\n    // Amendment: the DSR user is explicitly allowed the separate user-scoped\n    // Data Backup & Restore tab. This migration only adds the requested tab\n    // permission and does not change any other permission.\n    if(String(user.id||'').toLowerCase()==='shaikh shadab' && user.role==='dsr_user') {\n        const stored=db.users?.find(u=>String(u.id||'').toLowerCase()==='shaikh shadab');\n        if(stored && Array.isArray(stored.permissions) && !stored.permissions.includes('data-backup')) {\n            stored.permissions.push('data-backup');\n            saveDB();\n            user.permissions = stored.permissions.slice();\n            sessionStorage.setItem(AUTH_CONFIG.sessionKey, JSON.stringify(normalizeUser(stored)));\n        }\n    }\n    const adminUserMgmt=document.getElementById('admin-user-management');\n    if(adminUserMgmt) adminUserMgmt.style.display=isMasterUser(user)?'block':'none';\n    document.querySelectorAll('.tab-btn-vertical').forEach(btn=>{\n        const allowed=hasTabAccess(btn.dataset.tab,user);\n        btn.style.display=allowed?'block':'none';\n        btn.disabled=!allowed;\n        btn.setAttribute('aria-hidden', allowed ? 'false' : 'true');\n    });\n    const localRoutingBtn=document.querySelector('.local-sub-tabs .master-tab[data-local=\"routing\"]');\n    if(localRoutingBtn){\n        const routingAllowed=hasTabAccess('routing',user);\n        localRoutingBtn.style.display=routingAllowed?'inline-flex':'none';\n        localRoutingBtn.disabled=!routingAllowed;\n        localRoutingBtn.setAttribute('aria-hidden',routingAllowed?'false':'true');\n    }\n    applyRoleVisibility();\n}\n\nfunction renderUserTable() {\n    const tbody=document.getElementById('user-table-body'); if(!tbody) return;\n    tbody.innerHTML=db.users.map((u,idx)=>{\n        const permDisplay=u.role==='master'?'All Access':(Array.isArray(u.permissions)?u.permissions.join(', '):'-');\n        const editButton=`<button type=\"button\" class=\"btn btn-sm btn-preview user-edit-btn\" data-user-index=\"${idx}\" title=\"Edit User\">\u270f\ufe0f</button>`;\n        const deleteButton=u.id!=='Shaikh Shahid'?`<button type=\"button\" class=\"btn btn-sm btn-clear user-delete-btn\" data-user-index=\"${idx}\" title=\"Delete User\">\u00d7</button>`:'';\n        return `<tr><td><strong>${escapeHtml(u.id)}</strong></td><td>${escapeHtml(u.name||'-')}</td><td><span class=\"status-badge ${u.role==='master'?'status-active':'status-expiring'}\">${escapeHtml(String(u.role||'USER').toUpperCase())}</span></td><td style=\"font-size:0.7rem;\">${escapeHtml(permDisplay)}</td><td>${editButton} ${deleteButton}</td></tr>`;\n    }).join('');\n    if(!tbody.__userManagementEventsBound){\n        tbody.__userManagementEventsBound=true;\n        tbody.addEventListener('click',function(event){\n            const edit=event.target.closest('.user-edit-btn');\n            if(edit){\n                event.preventDefault();\n                openEditUserModal(Number(edit.dataset.userIndex));\n                return;\n            }\n            const del=event.target.closest('.user-delete-btn');\n            if(del){\n                event.preventDefault();\n                deleteUser(Number(del.dataset.userIndex));\n            }\n        });\n    }\n}\n/* ===== Amendment: Dynamic User Management Tab Auto-Sync =====\n * The User Management permission matrix is derived from the live ERP\n * navigation DOM every time the editor is opened. This prevents the matrix\n * from becoming stale when a new user-facing navigation tab is added.\n * Existing stored permissions are preserved; this only changes how the\n * available permission choices are discovered and displayed.\n */\nfunction getDynamicUserAccessGroups(){\n    const fallback = (typeof DEFAULT_USER_ACCESS_GROUPS !== 'undefined' && Array.isArray(DEFAULT_USER_ACCESS_GROUPS))\n        ? DEFAULT_USER_ACCESS_GROUPS\n        : [];\n    const nav = document.querySelector('.tab-nav-vertical');\n    if(!nav) return fallback.map(group => ({\n        key: group.key,\n        title: group.title,\n        items: Array.isArray(group.items) ? group.items.map(item => ({...item})) : []\n    }));\n\n    const groups=[];\n    nav.querySelectorAll(':scope > .nav-category').forEach((category, categoryIndex)=>{\n        const header=category.querySelector(':scope > .nav-category-header');\n        const items=[];\n        category.querySelectorAll(':scope > .nav-category-items > .tab-btn-vertical[data-tab]').forEach(btn=>{\n            const id=String(btn.dataset.tab||'').trim();\n            if(!id || items.some(item=>item.id===id)) return;\n            const label=String(btn.textContent||'').replace(/\\s+/g,' ').trim();\n            if(label) items.push({id,label});\n        });\n        if(items.length){\n            const title=String(header?.querySelector('span')?.textContent || header?.textContent || `Section ${categoryIndex+1}`)\n                .replace(/\\s+/g,' ').trim();\n            const key=String(category.querySelector(':scope > .nav-category-items')?.id || `dynamic-${categoryIndex}`)\n                .replace(/^cat-/,'');\n            groups.push({key,title,items});\n        }\n    });\n\n    // Routing is a real user-facing permission tab, but is intentionally a\n    // Local Charges sub-tab in the existing UI. Keep it in its own dynamic\n    // group so its existing RBAC behaviour remains unchanged.\n    const routingBtn=document.querySelector('.local-sub-tabs .master-tab[data-local=\"routing\"]');\n    if(routingBtn){\n        const id='routing';\n        if(!groups.some(group=>group.items.some(item=>item.id===id))){\n            groups.push({\n                key:'localChargesSubTabs',\n                title:'\ud83d\udccb LOCAL CHARGES \u2014 SUB TABS',\n                items:[{id,label:String(routingBtn.textContent||'').replace(/\\s+/g,' ').trim()||'\ud83e\udded Routing'}]\n            });\n        }\n    }\n\n    return groups.length ? groups : fallback.map(group => ({\n        key: group.key,\n        title: group.title,\n        items: Array.isArray(group.items) ? group.items.map(item => ({...item})) : []\n    }));\n}\n\nfunction getDynamicUserPermissionIds(){\n    const ids=new Set();\n    getDynamicUserAccessGroups().forEach(group => (group.items||[]).forEach(item => {\n        if(item?.id) ids.add(String(item.id));\n    }));\n    return ids;\n}\n\nfunction openAddUserModal(){ openUserModal(null); }\nfunction openEditUserModal(idx){\n    // Amendment 8: resolve the live user record by index first, then pass a\n    // clean snapshot to the modal. This prevents a stale table index from\n    // causing the wrong record to be loaded/saved after another render.\n    if(!Array.isArray(db.users)) return alert('User data is not available.');\n    const numericIdx=Number(idx);\n    const user=db.users[numericIdx];\n    if(!user) return alert('User not found.');\n    const snapshot={...user, permissions:Array.isArray(user.permissions)?user.permissions.slice():user.permissions};\n    openUserModal(numericIdx,snapshot);\n}\nfunction openUserModal(idx,userData=null){\n    const isEdit=idx!==null; const title=isEdit?'Edit User':'Add New User'; const data=userData||{id:'',name:'',password:'',passwordHash:'',role:'user',permissions:(typeof DEFAULT_USER_ACCESS !== 'undefined' && Array.isArray(DEFAULT_USER_ACCESS.newUserPermissions)?DEFAULT_USER_ACCESS.newUserPermissions:[])};\n    // Always rebuild the permission choices from the current ERP navigation.\n    const accessGroups = getDynamicUserAccessGroups();\n    const isMaster=data.role==='master';\n    // Normalize existing permissions only for display in the editor. The\n    // stored db.users record is not modified until Save User is clicked.\n    const currentPermissions=Array.isArray(data.permissions)?data.permissions.slice():[];\n    const legacyMap={sea:'export-quote',air:'export-quote',lcl:'export-quote',sealocal:'localcharges',airlocal:'localcharges',lcllocal:'localcharges',dashboard:'reporting'};\n    const effectivePermissions=new Set(currentPermissions.flatMap(p=>legacyMap[p]?[legacyMap[p]]:[p]));\n    let permHtml='<div class=\"user-access-groups\">';\n    accessGroups.forEach(group=>{\n        permHtml+=`<div class=\"user-access-group\"><div class=\"user-access-group-title\">${escapeHtml(group.title)}</div><div class=\"perm-grid user-access-grid\">`;\n        (group.items||[]).forEach(item=>{\n            const checked=isMaster||effectivePermissions.has(item.id)?' checked':'';\n            const disabled=isMaster?' disabled':'';\n            permHtml+=`<label class=\"${isMaster?'disabled':''}\"><input type=\"checkbox\" class=\"user-perm-cb\" name=\"user-permission\" data-permission=\"${escapeHtml(item.id)}\" value=\"${escapeHtml(item.id)}\"${checked}${disabled}>${escapeHtml(item.label)}</label>`;\n        });\n        permHtml+='</div></div>';\n    });\n    permHtml+='</div>';\n    const safeIdx=isEdit?Number(idx):null;\n    const safeId=String(data.id||'');\n    const html=`<h3 style=\"color:var(--primary);margin-bottom:12px;\">${title}</h3><div class=\"form-grid-2col\"><div class=\"form-group\"><label>User ID *</label><input type=\"text\" id=\"modal-user-id\" value=\"${escapeHtml(safeId)}\" ${isEdit?'readonly':''}></div><div class=\"form-group\"><label>Full Name</label><input type=\"text\" id=\"modal-user-name\" value=\"${escapeHtml(data.name||'')}\"></div><div class=\"form-group\"><label>Password ${isEdit?'(leave blank to keep current)':'*'}</label><input type=\"password\" id=\"modal-user-pass\" value=\"\" placeholder=\"Set password\" autocomplete=\"new-password\"></div><div class=\"form-group\"><label>Role</label><select id=\"modal-user-role\"><option value=\"user\" ${data.role==='user'?'selected':''}>User</option><option value=\"master\" ${data.role==='master'?'selected':''}>Master (Full Access)</option></select></div></div><div style=\"margin-top:10px;\"><label style=\"font-weight:700;font-size:0.85rem;color:var(--text-light);\">Tab Permissions (for Users)</label>${permHtml}</div><div id=\"user-edit-status\" style=\"display:none;margin-top:10px;padding:8px;border-radius:6px;font-size:.8rem;\"></div><div style=\"margin-top:16px;text-align:right;\"><button type=\"button\" class=\"btn btn-clear\" id=\"user-edit-cancel\">Cancel</button><button type=\"button\" class=\"btn btn-quoted\" id=\"user-edit-save\">\ud83d\udcbe Save User</button></div>`;\n    document.getElementById('modal-title').textContent=title;\n    const previewBody=document.getElementById('previewBody');\n    previewBody.innerHTML=html;\n    const roleEl=previewBody.querySelector('#modal-user-role');\n    if(roleEl) roleEl.addEventListener('change',toggleUserPerms);\n    const cancelEl=previewBody.querySelector('#user-edit-cancel');\n    if(cancelEl) cancelEl.addEventListener('click',()=>closeModal('previewModal'));\n    const saveEl=previewBody.querySelector('#user-edit-save');\n    if(saveEl){\n        saveEl.dataset.userIndex=safeIdx===null?'':String(safeIdx);\n        saveEl.dataset.originalId=safeId;\n        saveEl.addEventListener('click',function(){\n            const currentIdx=this.dataset.userIndex===''?null:Number(this.dataset.userIndex);\n            const original=this.dataset.originalId||'';\n            saveUser(currentIdx,original);\n        });\n    }\n    openModal('previewModal');\n}\nfunction toggleUserPerms(){ const role=document.getElementById('modal-user-role').value; document.querySelectorAll('#previewBody .user-perm-cb').forEach(cb=>{cb.checked=role==='master';cb.disabled=role==='master';cb.closest('label').classList.toggle('disabled',role==='master');}); }\nasync function saveUser(idx,originalId=''){\n    if (!requireMasterAccess('manage users')) return;\n    try {\n        if(!Array.isArray(db.users)) db.users=[];\n        const idEl=document.getElementById('modal-user-id');\n        const nameEl=document.getElementById('modal-user-name');\n        const passEl=document.getElementById('modal-user-pass');\n        const roleEl=document.getElementById('modal-user-role');\n        if(!idEl||!nameEl||!passEl||!roleEl) return alert('User editor is not ready. Please reopen Edit User.');\n        const id=idEl.value.trim();\n        const name=nameEl.value.trim();\n        const pass=passEl.value;\n        const role=roleEl.value;\n        if(!id) return alert('User ID is required.');\n\n        const isEdit=idx!==null && idx!==undefined && idx!=='';\n        let recordIndex=-1;\n        if(isEdit){\n            const original=String(originalId||'').trim();\n            recordIndex=db.users.findIndex(u=>String(u?.id||'').trim().toLowerCase()===original.toLowerCase());\n            if(recordIndex<0){\n                const n=Number(idx);\n                if(Number.isInteger(n) && n>=0 && n<db.users.length) recordIndex=n;\n            }\n            if(recordIndex<0) return alert('The user record could not be found. Please close and reopen Edit User.');\n        }\n        if(!isEdit && !pass) return alert('New users must have a password.');\n\n        const existing=isEdit?db.users[recordIndex]:null;\n        const existingId=String(existing?.id||originalId||id);\n        // User ID is intentionally immutable while editing.\n        if(isEdit && id.toLowerCase()!==existingId.toLowerCase()) return alert('User ID cannot be changed while editing an existing user.');\n\n        let passwordHash=existing?.passwordHash||null;\n        let passwordHashV2=existing?.passwordHashV2||null;\n        let passwordSalt=existing?.passwordSalt||null;\n        if(pass){\n            const secure=await securePasswordHash(pass);\n            passwordHashV2=secure.hash;\n            passwordSalt=secure.salt;\n            passwordHash=null;\n        } else if(!passwordHash && !passwordHashV2 && existing?.password){\n            const secure=await securePasswordHash(existing.password);\n            passwordHashV2=secure.hash;\n            passwordSalt=secure.salt;\n        }\n        if(!passwordHash && !passwordHashV2) return alert('A valid password is required.');\n\n        let permissions=[];\n        if(role!=='master'){\n            document.querySelectorAll('#previewBody .user-perm-cb').forEach(cb=>{ if(cb.checked) permissions.push(String(cb.value)); });\n\n            // Preserve any legacy/technical permission keys that are not part\n            // of the live user-facing tab matrix. This prevents an edit/save\n            // operation from silently deleting older permissions or future\n            // non-navigation access keys.\n            const managedIds=getDynamicUserPermissionIds();\n            const existingPermissions=Array.isArray(existing?.permissions) ? existing.permissions : [];\n            existingPermissions.forEach(permission=>{\n                const key=String(permission||'');\n                if(key && !managedIds.has(key)) permissions.push(key);\n            });\n\n            permissions=[...new Set(permissions)];\n            if(permissions.length===0 && !confirm('User has no permissions assigned. Continue?')) return;\n        } else {\n            permissions='all';\n        }\n\n        const userData={\n            ...(existing||{}),\n            id:existingId||id,\n            name:name||existing?.name||id,\n            passwordHash:passwordHash||null,\n            passwordHashV2:passwordHashV2||null,\n            passwordSalt:passwordSalt||null,\n            role,\n            permissions\n        };\n        if(isEdit){\n            if(existingId.toLowerCase()==='shaikh shahid' && role!=='master') return alert('The Master user must remain Master.');\n            db.users[recordIndex]=userData;\n        } else {\n            if(db.users.some(u=>String(u?.id||'').trim().toLowerCase()===id.toLowerCase())) return alert('User ID already exists.');\n            db.users.push(userData);\n        }\n\n        if(!saveDB()) return;\n        // Refresh the active session immediately if the edited user is the\n        // currently logged-in user, so permission changes take effect now.\n        const session=checkLogin();\n        if(session && String(session.id||'').toLowerCase()===String(userData.id||'').toLowerCase()){\n            sessionStorage.setItem(AUTH_CONFIG.sessionKey,JSON.stringify(normalizeUser(userData)));\n            sessionStorage.setItem(AUTH_CONFIG.lastActivityKey,String(Date.now()));\n        }\n        closeModal('previewModal');\n        renderUserTable();\n        applyPermissions();\n        alert('User saved successfully!');\n    } catch(err){\n        console.error('Edit/Save User failed:',err);\n        alert('Unable to save user. Please check the selected permissions and try again.');\n    }\n}\nfunction deleteUser(idx){ if(!requireMasterAccess('delete users')) return; if(idx<0||idx>=db.users.length)return alert('User not found.'); const user=db.users[idx]; if(user.id==='Shaikh Shahid')return alert('Cannot delete the Master user.'); if(!confirm(`Delete user \"${user.id}\"?`))return; db.users.splice(idx,1); saveDB(); renderUserTable(); }\n\n\n\n/* ===== BEGIN AMENDMENT: USER DATA BACKUP & RESTORE ===== */\n(function(){\n    'use strict';\n\n    const USER_BACKUP_SCHEMA = 'SHAHID-ERP-USER-DATA-BACKUP-V1';\n    const USER_BACKUP_JSON = 'SHAHID_ERP_USER_BACKUP.json';\n    const USER_BACKUP_HANDLES = Object.create(null);\n\n    function currentBackupUser(){\n        return (typeof checkLogin === 'function') ? checkLogin() : null;\n    }\n\n    function setUserBackupStatus(message, ok){\n        const el=document.getElementById('user-backup-status');\n        if(!el) return;\n        el.textContent=message;\n        el.className='backup-status ' + (ok ? 'success' : 'error');\n    }\n\n    function isMasterBackupUser(user){\n        return !!user && (user.role === 'master' || user.permissions === '*' || user.permissions === 'all');\n    }\n\n    function userBackupKey(user){\n        return String(user?.id || '').trim().toLowerCase();\n    }\n\n    function ensureUserBackupStore(){\n        if(!db.userBackupFolders || typeof db.userBackupFolders !== 'object' || Array.isArray(db.userBackupFolders)){\n            db.userBackupFolders = {};\n        }\n        return db.userBackupFolders;\n    }\n\n    function getUserBackupPath(user){\n        const store=ensureUserBackupStore();\n        return String(store[userBackupKey(user)] || '').trim();\n    }\n\n    function setUserBackupPath(user,path){\n        const store=ensureUserBackupStore();\n        store[userBackupKey(user)] = String(path || '').trim();\n        saveDB();\n    }\n\n    function getUserBackupScope(user){\n        return isMasterBackupUser(user) ? 'MASTER \u2014 Complete ERP data (excluding authentication/session metadata)' : 'DSR USER \u2014 Shipment List, BL Draft and Invoice data only';\n    }\n\n    function clone(value){\n        return JSON.parse(JSON.stringify(value));\n    }\n\n    function buildUserBackupPayload(user){\n        if(!user) throw new Error('Please login again.');\n        const timestamp=new Date().toISOString();\n        if(isMasterBackupUser(user)){\n            const data=clone(db);\n            // Never use a user-data backup to restore credentials or live session state.\n            delete data.users;\n            delete data.userBackupFolders;\n            delete data.backupFolderPath;\n            delete data.lastBackup;\n            delete data.googleDriveFolderPath;\n            delete data.lastGoogleDriveBackup;\n            delete data.navState;\n            return {\n                schema: USER_BACKUP_SCHEMA,\n                version: 1,\n                userId: user.id,\n                role: 'master',\n                scope: 'MASTER_FULL_ERP_DATA',\n                timestamp,\n                data\n            };\n        }\n\n        return {\n            schema: USER_BACKUP_SCHEMA,\n            version: 1,\n            userId: user.id,\n            role: 'dsr_user',\n            scope: 'DSR_DATA_ONLY',\n            timestamp,\n            data: {\n                shipments: clone(Array.isArray(db.shipments) ? db.shipments : []),\n                bldrafts: clone(Array.isArray(db.bldrafts) ? db.bldrafts : []),\n                invoices: clone(Array.isArray(db.invoices) ? db.invoices : [])\n            }\n        };\n    }\n\n    async function writeUserBackup(payload,user,path,handle){\n        const json=JSON.stringify(payload,null,2);\n        if(window.electronAPI && typeof window.electronAPI.writeBackupFile==='function'){\n            const result=await window.electronAPI.writeBackupFile(path, USER_BACKUP_JSON, json);\n            if(!result || result.success!==true) throw new Error(result?.error || 'Local backup write failed.');\n            return true;\n        }\n        if(!handle) throw new Error('Browser backup folder authorization is required. Click Select Folder.');\n        if(typeof handle.queryPermission==='function'){\n            const permission=await handle.queryPermission({mode:'readwrite'});\n            if(permission!=='granted') throw new Error('Backup folder permission is not available. Click Select Folder again.');\n        }\n        const fileHandle=await handle.getFileHandle(USER_BACKUP_JSON,{create:true});\n        const writable=await fileHandle.createWritable({keepExistingData:false});\n        await writable.write(json);\n        await writable.close();\n        return true;\n    }\n\n    async function readUserBackup(user,path,handle){\n        let text;\n        if(window.electronAPI && typeof window.electronAPI.readBackupFile==='function'){\n            const result=await window.electronAPI.readBackupFile(path, USER_BACKUP_JSON);\n            if(!result || result.success!==true) throw new Error(result?.error || 'Backup file could not be read.');\n            if(typeof result.data === 'string') {\n                text = result.data;\n            } else if(result.data && (Array.isArray(result.data) || ArrayBuffer.isView(result.data))) {\n                text = new TextDecoder().decode(new Uint8Array(result.data));\n            } else {\n                text = result.content || result.text || '';\n            }\n            if(!text) throw new Error('Backup file is empty.');\n        }else{\n            if(!handle) throw new Error('Browser backup folder authorization is required. Click Select Folder.');\n            if(typeof handle.queryPermission==='function'){\n                const permission=await handle.queryPermission({mode:'readwrite'});\n                if(permission!=='granted') throw new Error('Backup folder permission is not available. Click Select Folder again.');\n            }\n            const fileHandle=await handle.getFileHandle(USER_BACKUP_JSON,{create:false});\n            const file=await fileHandle.getFile();\n            text=await file.text();\n        }\n        const payload=JSON.parse(text);\n        if(payload?.schema!==USER_BACKUP_SCHEMA || Number(payload.version)!==1){\n            throw new Error('Invalid SHAHID ERP user backup format.');\n        }\n        if(String(payload.userId||'').trim().toLowerCase()!==userBackupKey(user)){\n            throw new Error('This backup belongs to a different user and cannot be restored here.');\n        }\n        if(!payload.data || typeof payload.data!=='object' || Array.isArray(payload.data)){\n            throw new Error('Backup data is invalid.');\n        }\n        return payload;\n    }\n\n    async function selectUserDataBackupFolder(){\n        const user=currentBackupUser();\n        if(!user || !hasTabAccess('data-backup',user)){\n            alert('You do not have permission to use Data Backup & Restore.');\n            return false;\n        }\n        try{\n            if(window.electronAPI && typeof window.electronAPI.selectBackupFolder==='function'){\n                const path=await window.electronAPI.selectBackupFolder();\n                if(!path) return false;\n                if(typeof window.electronAPI.checkBackupFolder==='function'){\n                    const check=await window.electronAPI.checkBackupFolder(path);\n                    if(!check || check.success!==true || check.writable!==true) throw new Error(check?.error || 'Selected folder is not writable.');\n                }\n                setUserBackupPath(user,path);\n                renderUserDataBackupPanel();\n                setUserBackupStatus(`\ud83d\udcc1 Folder authorized: ${path}`,true);\n                return true;\n            }\n            if(!window.showDirectoryPicker) throw new Error('Your browser does not support local folder selection. Please use Chrome/Edge or the EXE version.');\n            const handle=await window.showDirectoryPicker({mode:'readwrite'});\n            if(typeof handle.requestPermission==='function'){\n                const permission=await handle.requestPermission({mode:'readwrite'});\n                if(permission!=='granted') throw new Error('Backup folder permission was not granted.');\n            }\n            USER_BACKUP_HANDLES[userBackupKey(user)]=handle;\n            setUserBackupPath(user,handle.name);\n            renderUserDataBackupPanel();\n            setUserBackupStatus(`\ud83d\udcc1 Folder authorized: ${handle.name}`,true);\n            return true;\n        }catch(error){\n            if(error?.name==='AbortError') return false;\n            console.error('User backup folder selection failed:',error);\n            setUserBackupStatus(`\u274c Folder selection failed: ${error.message}`,false);\n            return false;\n        }\n    }\n\n    async function backupCurrentUserData(){\n        const user=currentBackupUser();\n        if(!user || !hasTabAccess('data-backup',user)){\n            alert('You do not have permission to use Data Backup & Restore.'); return false;\n        }\n        const path=getUserBackupPath(user);\n        const handle=USER_BACKUP_HANDLES[userBackupKey(user)] || null;\n        if(!path && !handle){ alert('Please select your local backup folder first.'); return false; }\n        try{\n            setUserBackupStatus('\u23f3 Creating user-scoped backup...',true);\n            const payload=buildUserBackupPayload(user);\n            await writeUserBackup(payload,user,path,handle);\n            const now=new Date().toISOString();\n            if(!db.userBackupMeta || typeof db.userBackupMeta!=='object') db.userBackupMeta={};\n            db.userBackupMeta[userBackupKey(user)]={lastBackup:now,scope:payload.scope};\n            saveDB();\n            renderUserDataBackupPanel();\n            setUserBackupStatus(`\u2705 Backup completed: ${new Date(now).toLocaleString('en-IN')}`,true);\n            return true;\n        }catch(error){\n            console.error('User backup failed:',error);\n            setUserBackupStatus(`\u274c Backup failed: ${error.message}`,false);\n            return false;\n        }\n    }\n\n    async function restoreCurrentUserData(){\n        const user=currentBackupUser();\n        if(!user || !hasTabAccess('data-backup',user)){\n            alert('You do not have permission to use Data Backup & Restore.'); return false;\n        }\n        const path=getUserBackupPath(user);\n        const handle=USER_BACKUP_HANDLES[userBackupKey(user)] || null;\n        if(!path && !handle){ alert('Please select your local backup folder first.'); return false; }\n        if(!confirm('Restore this user-scoped backup into the current ERP data? Existing records will be merged; unrelated data will remain unchanged.')) return false;\n        try{\n            setUserBackupStatus('\u23f3 Validating backup...',true);\n            const payload=await readUserBackup(user,path,handle);\n            if(payload.role==='master' && !isMasterBackupUser(user)) throw new Error('Only MASTER can restore a MASTER backup.');\n            if(payload.scope==='DSR_DATA_ONLY' && isMasterBackupUser(user)){\n                // MASTER may restore a DSR backup, but only its three permitted datasets.\n            }\n            const incoming=payload.data;\n            if(!isMasterBackupUser(user)){\n                if(typeof window.shahidMasterMergeDatabase!=='function') throw new Error('Canonical merge engine is unavailable.');\n                const merged=window.shahidMasterMergeDatabase(db,{shipments:incoming.shipments||[],bldrafts:incoming.bldrafts||[],invoices:incoming.invoices||[]});\n                db.shipments=merged.shipments||db.shipments||[];\n                db.bldrafts=merged.bldrafts||db.bldrafts||[];\n                db.invoices=merged.invoices||db.invoices||[];\n            }else{\n                if(typeof window.shahidMasterMergeDatabase!=='function') throw new Error('Canonical merge engine is unavailable.');\n                const merged=window.shahidMasterMergeDatabase(db,incoming);\n                Object.keys(incoming).forEach(key=>{ if(Object.prototype.hasOwnProperty.call(merged,key)) db[key]=merged[key]; });\n            }\n            if(saveDB()!==true) throw new Error('ERP database could not be saved after restore.');\n            const now=new Date().toISOString();\n            if(!db.userBackupMeta || typeof db.userBackupMeta!=='object') db.userBackupMeta={};\n            db.userBackupMeta[userBackupKey(user)]={...(db.userBackupMeta[userBackupKey(user)]||{}),lastRestore:now};\n            saveDB();\n            setUserBackupStatus(`\u2705 Restore completed: ${new Date(now).toLocaleString('en-IN')}`,true);\n            if(typeof renderShipments==='function') renderShipments();\n            if(typeof renderBLDrafts==='function') renderBLDrafts();\n            if(typeof renderInvoicesV11==='function') renderInvoicesV11();\n            return true;\n        }catch(error){\n            console.error('User backup restore failed:',error);\n            setUserBackupStatus(`\u274c Restore failed: ${error.message}`,false);\n            return false;\n        }\n    }\n\n    function renderUserDataBackupPanel(){\n        const user=currentBackupUser();\n        if(!user) return;\n        const path=getUserBackupPath(user);\n        const meta=(db.userBackupMeta && db.userBackupMeta[userBackupKey(user)]) || {};\n        const input=document.getElementById('user-backup-folder-path-input');\n        const display=document.getElementById('user-backup-folder-path');\n        const scope=document.getElementById('user-backup-scope');\n        const last=document.getElementById('user-backup-last');\n        if(input) input.value=path;\n        if(display) display.textContent=path ? `\ud83d\udcc1 ${path}` : 'No folder selected.';\n        if(scope) scope.textContent=getUserBackupScope(user);\n        if(last){\n            const b=meta.lastBackup ? new Date(meta.lastBackup).toLocaleString('en-IN') : 'Never';\n            const r=meta.lastRestore ? new Date(meta.lastRestore).toLocaleString('en-IN') : 'Never';\n            last.textContent=`Last backup: ${b} \u2022 Last restore: ${r}`;\n        }\n    }\n\n    window.selectUserDataBackupFolder=selectUserDataBackupFolder;\n    window.backupCurrentUserData=backupCurrentUserData;\n    window.restoreCurrentUserData=restoreCurrentUserData;\n    window.renderUserDataBackupPanel=renderUserDataBackupPanel;\n\n    document.addEventListener('DOMContentLoaded',function(){\n        setTimeout(function(){\n            const user=currentBackupUser();\n            if(user && hasTabAccess('data-backup',user)) renderUserDataBackupPanel();\n        },0);\n    });\n})();\n/* ===== END AMENDMENT: USER DATA BACKUP & RESTORE ===== */\n\n/* ===== END JS/43-master-pol.js ===== */\n\n/* ===== BEGIN JS/02-rate-request-sea-without-shipper.js ===== */\n/* Original source preserved from 08-action-report.js; assigned to this functional module without code changes. */\n// ==================== ACTION & EXCEPTION CENTER ====================\nlet actionCenterView = 'actions';\nlet actionCenterFilter = 'all';\nfunction actionCenterIsException(a){ return ['margin','quote-expired','quote-expiry','rate-expired','rate-expiry','shipment'].includes(a.type); }\nfunction actionCenterIsOverdue(a){ return a.type === 'quote-expired' || a.type === 'rate-expired' || a.type === 'task'; }\nfunction actionCenterIsDue(a){ return a.type === 'followup' || a.type === 'task' || a.type === 'quote-expiry' || a.type === 'rate-expiry'; }\nfunction actionCenterFilterAlerts(alerts){\n    if(actionCenterFilter==='critical') return alerts.filter(a=>a.priority==='critical');\n    if(actionCenterFilter==='warning') return alerts.filter(a=>a.priority==='warning');\n    if(actionCenterFilter==='due') return alerts.filter(actionCenterIsDue);\n    if(actionCenterFilter==='overdue') return alerts.filter(actionCenterIsOverdue);\n    return alerts;\n}\nfunction setActionCenterView(view){\n    actionCenterView = view === 'exceptions' ? 'exceptions' : 'actions';\n    document.querySelectorAll('.action-center-tab').forEach(b=>b.classList.toggle('active',b.dataset.acView===actionCenterView));\n    actionCenterFilter='all';\n    renderActionCenter();\n}\nfunction filterActionCenter(filter){\n    actionCenterFilter=filter||'all';\n    const panel=document.getElementById('actioncenter');\n    if(panel && !panel.classList.contains('active')) switchToTab('actioncenter');\n    renderActionCenter();\n}\nfunction actionCenterOpenAlert(index){\n    const alerts=window._shahidActionCenterAlerts||[];\n    const a=alerts[index];\n    if(a) handleERPAlert(a);\n}\nfunction renderActionCenter(){\n    const wrap=document.getElementById('action-center-table-wrap');\n    if(!wrap) return;\n    const all=collectERPAlerts();\n    const critical=all.filter(a=>a.priority==='critical').length;\n    const high=all.filter(a=>a.priority==='warning').length;\n    const due=all.filter(actionCenterIsDue).length;\n    const overdue=all.filter(actionCenterIsOverdue).length;\n    const set=(id,v)=>{const el=document.getElementById(id); if(el) el.textContent=String(v);};\n    set('ac-critical',critical); set('ac-high',high); set('ac-due',due); set('ac-overdue',overdue);\n    const scoped=all.filter(a=>actionCenterView==='exceptions' ? actionCenterIsException(a) : !actionCenterIsException(a));\n    const alerts=actionCenterFilterAlerts(scoped);\n    window._shahidActionCenterAlerts=alerts;\n    const title=document.getElementById('action-center-view-title');\n    if(title) title.textContent=(actionCenterView==='exceptions'?'EXCEPTIONS':'MY ACTIONS') + (actionCenterFilter!=='all' ? ` \u2022 ${actionCenterFilter.toUpperCase()}` : '');\n    if(!alerts.length){wrap.innerHTML='<div class=\"action-center-empty\">\u2713 CLEAR<br><small>No matching actions or exceptions.</small></div>';return;}\n    wrap.innerHTML=`<table class=\"action-center-table\"><thead><tr><th>Priority</th><th>Type</th><th>Reference</th><th>Action / Issue</th><th>Date</th><th></th></tr></thead><tbody>${alerts.map((a,i)=>{\n        const priority=a.priority==='critical'?'\ud83d\udd34 CRITICAL':a.priority==='warning'?'\ud83d\udfe0 HIGH':'\ud83d\udd35 INFO';\n        const type=(a.type||'').replaceAll('-',' ').toUpperCase();\n        return `<tr><td class=\"action-center-priority\">${priority}</td><td>${escapeHtml(type)}</td><td>${escapeHtml(a.ref||'-')}</td><td>${escapeHtml(a.title||'-')}<div style=\"font-size:.65rem;color:var(--text-light);margin-top:2px;\">${escapeHtml(a.detail||'')}</div></td><td>${escapeHtml(a.dateKey||'-')}</td><td><button type=\"button\" class=\"action-center-open\" onclick=\"actionCenterOpenAlert(${i})\">OPEN</button></td></tr>`;\n    }).join('')}</tbody></table>`;\n}\n\n// ==================== AUTOMATED ALERT CENTER ====================\nfunction getAlertDismissals(){ try{return JSON.parse(localStorage.getItem('erpAlertDismissals')||'{}');}catch(e){return{};} }\nfunction alertKey(a){ return `${a.type}|${a.ref||a.title}|${a.dateKey||''}`; }";
})(window);


/* ===== ORIGINAL MODULE: JS/documents-pdf-i.js ===== */
/* SHAHID ERP 2.0 modular source segment 25/59. Source is assembled in original order and executed as one classic script to preserve global declaration hoisting. */
(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[24] = "\nfunction collectERPAlerts(){\n    const alerts=[], now=new Date();\n    const dismissed=getAlertDismissals();\n    const push=(type,icon,title,detail,action,ref,priority='warning')=>{const a={type,icon,title,detail,action,ref,priority,dateKey:now.toISOString().slice(0,10)}; if(!dismissed[alertKey(a)]) alerts.push(a);};\n    const allQuotes=[...(db.rates?.sea||[]),...(db.rates?.air||[]),...(db.rates?.lcl||[])];\n    allQuotes.forEach(r=>{\n        if(r.marginINR<0) push('margin','\ud83d\udd34','Negative Margin',`${r.client||'Customer'} \u2022 ${r.quoteNumber||'Quote'} \u2022 ${formatINR(r.marginINR)}`,'rates',r.quoteNumber,'critical');\n        if(r.validityDate){const d=new Date(r.validityDate+'T23:59:59'); const days=Math.ceil((d-now)/86400000); if(days<0) push('quote-expired','\u26d4','Quote Expired',`${r.quoteNumber||'Quote'} \u2022 ${r.client||'Customer'} expired ${Math.abs(days)} day(s) ago.`,'rates',r.quoteNumber,'critical'); else if(days<=3) push('quote-expiry','\u26a0\ufe0f','Quote Expiring',`${r.quoteNumber||'Quote'} \u2022 ${days} day(s) remaining.`,'rates',r.quoteNumber,'warning'); }\n        if((r.followUpStatus||'PENDING')==='PENDING') push('followup','\ud83d\udcde','Follow-up Pending',`${r.client||'Customer'} \u2022 ${r.quoteNumber||'Quote'}`,'followup',r.quoteNumber,'warning');\n    });\n    (db.rateSheet||[]).forEach(r=>{ if(!r.validTo)return; const d=new Date(r.validTo+'T23:59:59'); const days=Math.ceil((d-now)/86400000); if(days<0) push('rate-expired','\u26d4','Rate Expired',`${r.carrierName||r.carrier||'Carrier'} \u2022 ${r.pol||'-'} \u2192 ${r.pod||'-'}`,'ratesheet',r.id||r.carrierName,'critical'); else if(days<=7) push('rate-expiry','\ud83d\udfe1','Rate Expiring',`${r.carrierName||r.carrier||'Carrier'} \u2022 ${days} day(s) remaining.`,'ratesheet',r.id||r.carrierName,'warning'); });\n    (db.plannerTasks||[]).forEach(t=>{ if(t.completed)return; if(t.dueDate){const d=new Date(t.dueDate+'T23:59:59'); if(d<now) push('task','\ud83d\udcc5','Planner Task Overdue',`${t.title||t.text||'Task'} \u2022 due ${t.dueDate}`,'planner',t.id,'warning'); } });\n    (db.shipments||[]).forEach(s=>{\n        const status=String(s.status||s.cargoStatus||'').toUpperCase();\n        if(status && !['COMPLETED','DELIVERED','CANCELLED'].includes(status) && !s.vessel && !s.etd) push('shipment','\ud83d\udea2','Shipment Data Incomplete',`${s.jobNo||s.shipmentNo||s.id||'Shipment'} is missing vessel/ETD data.`,'dsr',s.id,'info');\n        if(String(s.mode||s.type||'').toUpperCase()==='SEA') {\n            const dates=[\n                ['SI',s.siCutoff],['GATE',s.gateCutoff],['SB',s.sbCutoff],['GATE OPENING',s.gateOpening]\n            ];\n            const today=dateOnly(new Date());\n            dates.forEach(([type,d])=>{\n                if(!d) return;\n                const due=dateOnly(d);\n                const diff=Math.round((new Date(due+'T12:00:00')-new Date(today+'T12:00:00'))/86400000);\n                if(diff<0) push('cutoff-overdue','\u26d4',`${type} Cut-off Overdue`,`${s.jobNo||s.code||'Shipment'} \u2022 due ${due}`,'dsr',`${s.code||s.jobNo}|${type}`,'critical');\n                else if(diff===0) push('cutoff-today','\ud83d\udd34',`${type} Cut-off Today`,`${s.jobNo||s.code||'Shipment'} \u2022 ${shipmentCustomer(s)}`,'dsr',`${s.code||s.jobNo}|${type}`,'critical');\n                else if(diff===1) push('cutoff-tomorrow','\ud83d\udfe0',`${type} Cut-off Tomorrow`,`${s.jobNo||s.code||'Shipment'} \u2022 ${shipmentCustomer(s)}`,'dsr',`${s.code||s.jobNo}|${type}`,'warning');\n            });\n        }\n    });\n    return alerts.slice(0,80);\n}\nfunction renderAlertCenter(){\n    const list=document.getElementById('alert-center-list'), badge=document.getElementById('alert-count-badge'), summary=document.getElementById('alert-center-summary'); if(!list)return;\n    const alerts=collectERPAlerts(); if(badge){badge.textContent=alerts.length>99?'99+':String(alerts.length);badge.style.display=alerts.length?'inline-flex':'none';}\n    const badgeText=alerts.length>99?'99+':String(alerts.length); [document.getElementById('action-center-nav-badge'), document.getElementById('action-center-header-badge')].forEach(navBadge=>{ if(navBadge){navBadge.textContent=badgeText; navBadge.style.display=alerts.length?'inline-flex':'none';} });\n    if(summary) summary.textContent=alerts.length?`${alerts.length} active operational alert${alerts.length===1?'':'s'}`:'No active operational alerts';\n    if(!alerts.length){list.innerHTML='<div class=\"alert-empty\">\u2713 SYSTEM CLEAR<br><small>No active alerts detected.</small></div>';return;}\n    window._shahidActiveAlerts=alerts;\n    list.innerHTML=alerts.map((a,i)=>`<div class=\"alert-item alert-${a.priority}\" onclick=\"handleERPAlertByIndex(${i})\"><div class=\"alert-icon\">${a.icon}</div><div><div class=\"alert-title\">${escapeHtml(a.title)}</div><div class=\"alert-detail\">${escapeHtml(a.detail)}</div></div><div class=\"alert-time\">${a.action==='followup'?'OPEN':''}</div></div>`).join('');\n}\nfunction handleERPAlertByIndex(i){ const a=window._shahidActiveAlerts?.[i]; if(a) handleERPAlert(a); }\nfunction handleERPAlert(a){\n    document.getElementById('alert-center-panel')?.classList.remove('open');\n    document.getElementById('alertCenterBtn')?.setAttribute('aria-expanded','false');\n\n    if(!a) return;\n\n    // OPEN must take the user to the actual record, not only switch the tab.\n    // This is especially important for Follow-up alerts where the reference is\n    // the quote number shown in the Action Center.\n    if(a.action === 'rates' || a.action === 'followup'){\n        const modes = ['sea','air','lcl'];\n        for(const mode of modes){\n            const idx = (db.rates?.[mode] || []).findIndex(r =>\n                String(r.quoteNumber || '').toUpperCase() === String(a.ref || '').toUpperCase()\n            );\n            if(idx >= 0){\n                switchToTab('rates');\n                setTimeout(() => {\n                    try {\n                        previewSavedRecord('rates', mode, idx);\n                    } catch(e) {\n                        console.error('Action Center quote open failed:', e);\n                        alert('Unable to open this quotation.');\n                    }\n                }, 80);\n                return;\n            }\n        }\n        switchToTab('rates');\n        return;\n    }\n\n    if(a.action === 'ratesheet'){\n        const idx = (db.rateSheet || []).findIndex(r =>\n            String(r.id || r.carrierName || '').toUpperCase() === String(a.ref || '').toUpperCase()\n        );\n        switchToTab('ratesheet');\n        if(idx >= 0){\n            setTimeout(() => {\n                try {\n                    previewRateSheet(idx);\n                } catch(e) {\n                    console.error('Action Center rate open failed:', e);\n                    alert('Unable to open this rate.');\n                }\n            }, 80);\n        }\n        return;\n    }\n\n    if(a.action === 'planner'){\n        switchToTab('planner');\n        return;\n    }\n\n    if(a.action === 'dsr'){\n        switchToTab('dsr');\n        return;\n    }\n}\nfunction toggleAlertCenter(e){ e?.stopPropagation(); const panel=document.getElementById('alert-center-panel'); const btn=document.getElementById('alertCenterBtn'); if(!panel)return; alertCenterOpen=!panel.classList.contains('open'); panel.classList.toggle('open',alertCenterOpen); btn?.setAttribute('aria-expanded',String(alertCenterOpen)); if(alertCenterOpen)renderAlertCenter(); }\nfunction clearAllAlerts(){\n    const alerts=collectERPAlerts(); if(!alerts.length)return; const d=getAlertDismissals(); alerts.forEach(a=>d[alertKey(a)]=Date.now()); localStorage.setItem('erpAlertDismissals',JSON.stringify(d)); renderAlertCenter();\n}\ndocument.addEventListener('click',e=>{const wrap=document.querySelector('.alert-center-wrap'); if(alertCenterOpen&&wrap&&!wrap.contains(e.target)){document.getElementById('alert-center-panel')?.classList.remove('open');alertCenterOpen=false;}});\nfunction startAlertEngine(){ renderAlertCenter(); setInterval(renderAlertCenter,60000); }\n\n// Compatibility helpers for older action/quote update hooks. Current UI is\n// already updated by renderAlertCenter/renderEnhancedRates, so these helpers\n// simply route legacy calls into the canonical renderers.\nfunction updateActionCenterBadge(){\n    const count = typeof collectERPAlerts === 'function' ? collectERPAlerts().length : 0;\n    document.querySelectorAll('#action-center-nav-badge,#action-center-header-badge').forEach(el => {\n        el.textContent = count > 99 ? '99+' : String(count);\n        el.style.display = count ? 'inline-flex' : 'none';\n    });\n}\nfunction updateAlertBadge(){\n    const count = typeof collectERPAlerts === 'function' ? collectERPAlerts().length : 0;\n    const el = document.getElementById('alert-count-badge');\n    if(el){ el.textContent = count > 99 ? '99+' : String(count); el.style.display = count ? 'inline-flex' : 'none'; }\n}\nfunction updateQuoteActionButtons(tabId){\n    if(String(tabId || '') === 'rates' && typeof renderEnhancedRates === 'function') renderEnhancedRates();\n}\n\n// ==================== SQLITE BACKUP ====================\nasync function initSQLite() {\n    if (window.__ERP_SQLITE_READY && window.SQL) return window.SQL;\n    if (window.__ERP_SQLITE_PROMISE) return window.__ERP_SQLITE_PROMISE;\n    window.__ERP_SQLITE_PROMISE = (async () => {\n        if (!window.SHAHIDOfflineSQLite || typeof window.SHAHIDOfflineSQLite.Database !== 'function') {\n            throw new Error('SQLite offline engine is unavailable inside the bundled ERP runtime.');\n        }\n        // Amendment 7: use the self-contained local SQLite engine. This avoids\n        // sql-wasm/WASM fetches, CDN dependencies and file:// CORS restrictions.\n        window.SQL = { Database: window.SHAHIDOfflineSQLite.Database };\n        window.__ERP_SQLITE_READY = true;\n        return window.SQL;\n    })().catch(err => { window.__ERP_SQLITE_PROMISE = null; throw err; });\n    return window.__ERP_SQLITE_PROMISE;\n}\n\n/* ==================== COMPLETE SQLITE BACKUP ==================== */\nasync function buildCompleteSQLiteDatabase() {\n    await initSQLite();\n    if (!window.SHAHIDOfflineSQLite || typeof window.SHAHIDOfflineSQLite.build !== 'function') {\n        throw new Error('Offline SQLite builder is unavailable.');\n    }\n    // Keep the existing public contract (.export() / .close()) so every\n    // existing backup/export path continues to work unchanged.\n    const bytes = window.SHAHIDOfflineSQLite.build(db || {});\n    return {\n        export: () => new Uint8Array(bytes),\n        close: () => {}\n    };\n}\n\nasync function exportToSQLite() {\n    try {\n        const dbInstance = await buildCompleteSQLiteDatabase();\n        const data = dbInstance.export();\n        dbInstance.close();\n\n        const blob = new Blob([data], { type: 'application/x-sqlite3' });\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement('a');\n        a.href = url;\n        a.download = `Backup_${new Date().toISOString().split('T')[0]}.sqlite`;\n        document.body.appendChild(a);\n        a.click();\n        document.body.removeChild(a);\n        setTimeout(() => URL.revokeObjectURL(url), 1000);\n\n        alert('Complete SQLite backup downloaded successfully.');\n    } catch (e) {\n        console.error('SQLite export failed:', e);\n        alert('SQLite export failed: ' + e.message);\n    }\n}\n\nasync function exportSQLiteToFolder(folderHandle) {\n    try {\n        if (!folderHandle) throw new Error('Backup folder is not selected.');\n\n        const dbInstance = await buildCompleteSQLiteDatabase();\n        const data = dbInstance.export();\n        dbInstance.close();\n\n        const fileName = 'SHAHID_ERP.sqlite';\n        const fileHandle = await folderHandle.getFileHandle(fileName, { create: true });\n        const writable = await fileHandle.createWritable({ keepExistingData: false });\n        await writable.write(new Blob([data], { type: 'application/x-sqlite3' }));\n        await writable.close();\n\n        db.lastBackup = new Date().toISOString();\n        saveDB();\n\n        const statusEl = document.getElementById('backup-status');\n        if (statusEl) {\n            statusEl.textContent =\n                `\u2705 Complete SQLite backup: ${new Date().toLocaleString('en-IN')} ` +\n                `(saved to ${folderHandle.name}/${fileName})`;\n            statusEl.className = 'backup-status success';\n        }\n    } catch (e) {\n        console.error('Complete SQLite folder backup failed:', e);\n        const statusEl = document.getElementById('backup-status');\n        if (statusEl) {\n            statusEl.textContent = `\u274c SQLite backup failed: ${e.message}`;\n            statusEl.className = 'backup-status error';\n        }\n    }\n}\n\n\nasync function importFromSQLite(input) {\n    const file = (typeof File !== 'undefined' && input instanceof File)\n        ? input\n        : (input && input.files && input.files[0] ? input.files[0] : null);\n    if(!file){\n        return null;\n    }\n\n    try {\n        await initSQLite();\n        if(!window.SQL){\n            throw new Error(\n                'SQLite library failed to load. Please check your internet connection and refresh the page.'\n            );\n        }\n\n        const buffer = await file.arrayBuffer();\n        const sqliteDb = new window.SQL.Database(new Uint8Array(buffer));\n\n        try {\n            const tableCheck = sqliteDb.prepare(\n                \"SELECT name FROM sqlite_master WHERE type='table' AND name='erp_state'\"\n            );\n            const hasCompleteState = tableCheck.step();\n            tableCheck.free();\n\n            if(!hasCompleteState){\n                throw new Error(\n                    'This SQLite file is not a Complete SHAHID ERP backup.'\n                );\n            }\n\n            const stmt = sqliteDb.prepare(\n                'SELECT key, value_json FROM erp_state'\n            );\n            const importedState = {};\n\n            while(stmt.step()){\n                const row = stmt.getAsObject();\n\n                try{\n                    importedState[row.key] = JSON.parse(row.value_json);\n                }catch(parseError){\n                    console.warn(\n                        'Invalid JSON state key skipped:',\n                        row.key,\n                        parseError\n                    );\n                }\n            }\n\n            stmt.free();\n\n            if(!Object.keys(importedState).length){\n                throw new Error(\n                    'The SQLite backup contains no ERP state.'\n                );\n            }\n\n            // IMPORTANT:\n            // Do NOT replace db with importedState. Merge the complete\n            // database so current ERP data + imported ERP data coexist.\n            const current = (typeof db === 'object' && db !== null)\n                ? db\n                : {};\n\n            let merged;\n            try{\n                merged = window.shahidMasterMergeDatabase(current, importedState);\n            }catch(mergeError){\n                throw new Error(\n                    `SQLite master merge failed: ${mergeError.message}`\n                );\n            }\n\n            if(\n                !merged ||\n                typeof merged !== 'object' ||\n                Array.isArray(merged)\n            ){\n                throw new Error(\n                    'SQLite master merge returned an invalid database object.'\n                );\n            }\n\n            // Commit ONLY after the complete merge has passed validation.\n            Object.keys(db).forEach(key => delete db[key]);\n            Object.assign(db, merged);\n\n            if(typeof saveDB === 'function'){\n                const persisted = await Promise.resolve(saveDB());\n                if(persisted !== true) throw new Error('Database could not be saved. SQLite import was not confirmed as complete.');\n            }\n\n            // Make sure Planner Tasks and Planner Notes are immediately\n            // available after import without losing their records.\n            if(Array.isArray(db.plannerTasks)){\n                try{\n                    if(typeof plannerEnsureSrNumbers === 'function'){\n                        plannerEnsureSrNumbers();\n                    }\n                }catch(e){\n                    console.warn('Planner SR normalization after import skipped:', e);\n                }\n            }\n\n            const importedTaskCount = Array.isArray(importedState.plannerTasks)\n                ? importedState.plannerTasks.length\n                : 0;\n            const importedNoteCount = Array.isArray(importedState.plannerNotes)\n                ? importedState.plannerNotes.length\n                : 0;\n\n            const totalTaskCount = Array.isArray(db.plannerTasks)\n                ? db.plannerTasks.length\n                : 0;\n            const totalNoteCount = Array.isArray(db.plannerNotes)\n                ? db.plannerNotes.length\n                : 0;\n\n            alert(\n                '\u2705 SQLite Import + Merge successful.\\\\n\\\\n' +\n                'Current ERP data was preserved and the backup data was merged.\\\\n\\\\n' +\n                `Imported Tasks: ${importedTaskCount}\\\\n` +\n                `Imported Notes: ${importedNoteCount}\\\\n` +\n                `Total Tasks after merge: ${totalTaskCount}\\\\n` +\n                `Total Notes after merge: ${totalNoteCount}`\n            );\n\n            // Refresh the UI so imported Planner Tasks/Notes and all other\n            // merged ERP data are visible immediately.\n            try{\n                if(typeof populateDropdowns === 'function') populateDropdowns();\n                if(typeof loadPlannerDay === 'function'){\n                    loadPlannerDay(formatDateKey(plannerSelectedDate));\n                }\n                if(typeof renderPlannerCalendar === 'function'){\n                    renderPlannerCalendar();\n                }\n            }catch(refreshError){\n                console.warn('Post-import UI refresh warning:', refreshError);\n            }\n\n            return merged;\n\n        }finally{\n            sqliteDb.close();\n        }\n\n    }catch(err){\n        console.error('SQLite import/merge failed:', err);\n        alert('SQLite Import/Merge failed: ' + (err?.message || String(err)));\n        return null;\n    }finally{\n        try{ if(input && 'value' in Object(input) && !(typeof File !== 'undefined' && input instanceof File)) input.value = ''; }catch(_){}\n    }\n}\n\n\n// ==================== DSR DESIGN MODE ====================\nfunction toggleDsrDesignMode() {\n    dsrDesignMode = !dsrDesignMode;\n    const body = document.querySelector('#seaDsrBody, #airDsrBody');\n    if (body) body.classList.toggle('dsr-design-mode', dsrDesignMode);\n}\ndocument.addEventListener('dragstart', function(e) {\n    const field = e.target.closest('.dsr-field');\n    if (!field) return;\n    e.dataTransfer.setData('text/plain', field.dataset.fieldId || field.id || '');\n    setTimeout(() => field.classList.add('dragging'), 0);\n});\ndocument.addEventListener('dragover', function(e) {\n    e.preventDefault();\n    const field = e.target.closest('.dsr-field');\n    if (field && dsrDesignMode) field.classList.add('drag-over');\n});\ndocument.addEventListener('dragleave', function(e) {\n    const field = e.target.closest('.dsr-field');\n    if (field) field.classList.remove('drag-over');\n});\ndocument.addEventListener('drop', function(e) {\n    e.preventDefault();\n    const target = e.target.closest('.dsr-field');\n    if (!target || !dsrDesignMode) return;\n    target.classList.remove('drag-over');\n    const sourceId = e.dataTransfer.getData('text/plain');\n    const source = target.parentElement.querySelector(`[data-field-id=\"${sourceId}\"]`);\n    if (!source || source === target) return;\n    const parent = target.parentElement;\n    const children = Array.from(parent.children);\n    const srcIdx = children.indexOf(source);\n    const tgtIdx = children.indexOf(target);\n    if (srcIdx < tgtIdx) {\n        parent.insertBefore(source, target.nextSibling);\n    } else {\n        parent.insertBefore(source, target);\n    }\n    parent.querySelectorAll('.dragging').forEach(el => el.classList.remove('dragging'));\n});\n\n// ==================== GLOBAL OMNI-SEARCH ====================\nlet globalSearchTimeout = null;\n\nfunction debouncedGlobalSearch() {\n    clearTimeout(globalSearchTimeout);\n    globalSearchTimeout = setTimeout(() => performGlobalSearch(), 300);\n}\n\nfunction performGlobalSearch() {\n    const input = document.getElementById('global-search');\n    const resultsContainer = document.getElementById('global-search-results');\n    const term = input.value.trim().toLowerCase();\n    if (term.length < 2) {\n        resultsContainer.classList.remove('show');\n        resultsContainer.innerHTML = '';\n        return;\n    }\n    let matches = [];\n\n    function isMatch(rec, term) {\n        // Global search covers the key ERP identifiers requested for quick lookup:\n        // Booking No., Job No., Invoice No., plus the existing quote/shipment fields.\n        const text =\n            `${rec.quoteNumber||''} ${rec.quoteNo||''} ${rec.client||''} ${rec.customer||''} ${rec.pol||''} ${rec.pod||''} ${rec.carrier||''} ${rec.shipper||''} ${rec.code||''} ${rec.jobNo||''} ${rec.jobBkg||''} ${rec.bookingNo||''} ${rec.bookingNumber||''} ${rec.invoiceNo||''} ${rec.invoiceNumber||''} ${rec.blNumber||''} ${rec.carrierName||''} ${rec.containerNo||''} ${rec.containerNumber||''} ${rec.container||''} ${Array.isArray(rec.containers) ? rec.containers.map(c => c?.containerNo || c?.number || c?.no || '').join(' ') : ''}`.toLowerCase();\n        return text.includes(term);\n    }\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        db.drafts[mode].forEach((rec, idx) => {\n            if (isMatch(rec, term)) {\n                matches.push({\n                    category: 'Draft',\n                    tab: 'drafts',\n                    mode: mode,\n                    idx: idx,\n                    label: `${rec.quoteNumber} - ${rec.client}`,\n                    subtitle: `${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n                });\n            }\n        });\n    });\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        (Array.isArray(db.rates?.[mode]) ? db.rates[mode] : []).forEach((rec, idx) => {\n            if (isMatch(rec, term)) {\n                matches.push({\n                    category: 'Quote',\n                    tab: 'rates',\n                    mode: mode,\n                    idx: idx,\n                    label: `${rec.quoteNumber} - ${rec.client}`,\n                    subtitle: `${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n                });\n            }\n        });\n    });\n    db.shipments.forEach((rec, idx) => {\n        if (isMatch(rec, term)) {\n            matches.push({\n                category: 'Shipment',\n                tab: 'dsr',\n                mode: 'dsr',\n                idx: idx,\n                label: `${rec.code} - ${rec.shipper}`,\n                subtitle: `${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n            });\n        }\n    });\n    db.bldrafts.forEach((rec, idx) => {\n        if (isMatch(rec, term)) {\n            matches.push({\n                category: 'BL Draft',\n                tab: 'bldraft',\n                mode: 'bldraft',\n                idx: idx,\n                label: `${rec.blNumber || 'BL-Draft'} - ${rec.shipper}`,\n                subtitle: `${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n            });\n        }\n    });\n    db.rateSheet.forEach((rec, idx) => {\n        if (isMatch(rec, term)) {\n            matches.push({\n                category: 'Rate Sheet',\n                tab: 'ratesheet',\n                mode: 'ratesheet',\n                idx: idx,\n                label: `${rec.carrierName} - ${rec.freightType}`,\n                subtitle: `${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n            });\n        }\n    });\n    // Invoice No. is also searchable from the default/global search.\n    (db.invoices || []).forEach((rec, idx) => {\n        if (isMatch(rec, term)) {\n            matches.push({\n                category: 'Invoice',\n                tab: 'invoice',\n                mode: 'invoice',\n                idx: idx,\n                invoiceNo: rec.invoiceNo || rec.id || '',\n                label: `${rec.invoiceNo || rec.id || 'Invoice'} - ${rec.customer || rec.client || '-'}`,\n                subtitle: `${rec.quoteRef || '-'} \u2022 ${rec.pol || 'N/A'} \u2192 ${rec.pod || 'N/A'}`\n            });\n        }\n    });\n    if (matches.length === 0) {\n        resultsContainer.innerHTML =\n            `<div class=\"no-results\">No records found matching \"<strong>${input.value}</strong>\"</div>`;\n        resultsContainer.classList.add('show');\n        return;\n    }\n    matches = matches.slice(0, 15);\n    let html = '';\n    let lastCategory = '';\n    matches.forEach(item => {\n        if (item.category !== lastCategory) {\n            html += `<div class=\"result-group-title\">${item.category}</div>`;\n            lastCategory = item.category;\n        }\n        html += `<div class=\"result-item\" onclick=\"jumpToRecord('${item.tab}', '${item.mode}', ${item.idx})\">\n                    <div class=\"title\">${item.label}</div>\n                    <div class=\"subtitle\">${item.subtitle}</div>\n                    <span class=\"tag\">${item.category}</span>\n                </div>`;\n    });\n    resultsContainer.innerHTML = html;\n    resultsContainer.classList.add('show');\n}\n\nfunction jumpToRecord(tab, mode, idx) {\n    const resultsContainer = document.getElementById('global-search-results');\n    resultsContainer.classList.remove('show');\n    document.getElementById('global-search').value = '';\n    switchToTab(tab);\n    setTimeout(() => {\n        if (tab === 'drafts' || tab === 'rates') {\n            editRecord(tab, mode, idx);\n        } else if (tab === 'dsr') {\n            editDsrShipment(idx);\n        } else if (tab === 'invoice') {\n            const inv = (db.invoices || [])[idx];\n            if (inv) openInvoicePreviewV11(inv.invoiceNo || inv.id);\n        } else if (tab === 'bldraft') {\n            openBLModal(idx);\n        } else if (tab === 'ratesheet') {\n            openRateSheetModal(idx);\n        }\n    }, 400);\n}\ndocument.addEventListener('click', function(e) {\n    const wrapper = document.querySelector('.global-search-wrapper');\n    const results = document.getElementById('global-search-results');\n    if (wrapper && !wrapper.contains(e.target)) {\n        results.classList.remove('show');\n    }\n});\n\n\n// ==================== RATE REQUEST VALIDITY \u2014 DEFAULT + MANUAL DATE ====================\n(function initializeRateRequestValidityDefaults(){\n    const FIELD_IDS = ['rr-validity-sea1', 'rr-validity-sea2', 'rr-validity-air'];\n\n    function applyDefaultIfEmpty(){\n        const defaultValidity = getRateRequestDefaultValidityDate();\n        FIELD_IDS.forEach(id => {\n            const el = document.getElementById(id);\n            if (!el || String(el.value || '').trim()) return;\n            el.value = formatRateRequestDate(defaultValidity);\n            const suffix = id.replace('rr-validity-', '');\n            const picker = document.getElementById(`rr-validity-${suffix}-picker`);\n            if (picker) picker.value = defaultValidity;\n        });\n    }\n\n    const init = () => {\n        applyDefaultIfEmpty();\n        if (typeof syncAllRateRequestValidityPickers === 'function') syncAllRateRequestValidityPickers();\n    };\n\n    if (document.readyState === 'loading') {\n        document.addEventListener('DOMContentLoaded', init, { once:true });\n    } else {\n        init();\n    }\n})();\n\n/* ===== END JS/02-rate-request-sea-without-shipper.js ===== */\n\n/* ===== BEGIN JS/35-us-trucking.js ===== */\n/* Original source preserved from 09-measurement-tools.js; assigned to this functional module without code changes. */\n// ==================== MEASUREMENT DEFAULTS (New) ====================\nfunction refreshMeasurementDefaults() {\n    const d = db.defaults || {};\n    const dutyPct = document.getElementById('duty-pct');\n    if (dutyPct) dutyPct.value = d.inDuty || 0;\n    const dutyService = document.getElementById('duty-service');\n    if (dutyService) dutyService.value = d.inSocialWelfare || 0;\n    const dutyGst = document.getElementById('duty-gst');\n    if (dutyGst) dutyGst.value = d.gst || 0;\n    const insPct = document.getElementById('ins-pct');\n    if (insPct) insPct.value = d.insurance || 0;\n    const insGst = document.getElementById('ins-gst');\n    if (insGst) insGst.value = d.gst || 0;\n    const prodProfit = document.getElementById('prod-profit');\n    if (prodProfit) prodProfit.value = d.profitMargin || 0;\n    const prodDrawback = document.getElementById('prod-drawback');\n    if (prodDrawback) prodDrawback.value = d.drawback || 0;\n    const prodRodtep = document.getElementById('prod-rodtep');\n    if (prodRodtep) prodRodtep.value = d.rodtep || 0;\n    const usDutyPct = document.getElementById('us-duty-pct');\n    if (usDutyPct) usDutyPct.value = d.usDuty || 0;\n    const usDutyTariff = document.getElementById('us-duty-tariff');\n    if (usDutyTariff) usDutyTariff.value = d.usTariff || 0;\n    const usDutyMpf = document.getElementById('us-duty-mpf');\n    if (usDutyMpf) usDutyMpf.value = d.usMPF || 0;\n    const usDutyHmf = document.getElementById('us-duty-hmf');\n    if (usDutyHmf) usDutyHmf.value = d.usHMF || 0;\n    const defaultCur = d.defaultCurrency || 'USD';\n    ['duty-currency', 'prod-currency', 'ins-currency', 'us-duty-currency'].forEach(id => {\n        const sel = document.getElementById(id);\n        if (sel) {\n            sel.value = defaultCur;\n            setExchangeRate(id.replace('-currency', '-exrate'), id);\n        }\n    });\n}\n\nfunction saveMeasurementDefaults() {\n    db.defaults.gst = parseFloat(document.getElementById('def-gst').value) || 0;\n    db.defaults.insurance = parseFloat(document.getElementById('def-insurance').value) || 0;\n    db.defaults.profitMargin = parseFloat(document.getElementById('def-profit').value) || 0;\n    db.defaults.defaultCurrency = document.getElementById('def-currency').value || 'USD';\n    db.defaults.usDuty = parseFloat(document.getElementById('def-us-duty').value) || 0;\n    db.defaults.usTariff = parseFloat(document.getElementById('def-us-tariff').value) || 0;\n    db.defaults.usMPF = parseFloat(document.getElementById('def-us-mpf').value) || 0;\n    db.defaults.usHMF = parseFloat(document.getElementById('def-us-hmf').value) || 0;\n    db.defaults.inDuty = parseFloat(document.getElementById('def-in-duty').value) || 0;\n    db.defaults.inSocialWelfare = parseFloat(document.getElementById('def-in-social').value) || 0;\n    db.defaults.drawback = parseFloat(document.getElementById('def-drawback').value) || 0;\n    db.defaults.rodtep = parseFloat(document.getElementById('def-rodtep').value) || 0;\n    saveDB();\n    alert('Measurement defaults saved!');\n    refreshMeasurementDefaults();\n}\n\n// ============================================================\n// NEW FEATURES \u2013 DSR & REPORTS (V9/V11)\n// ============================================================\n\n/* ---------- HELPERS ---------- */\nfunction escapeHtml(text) {\n    if (!text) return '';\n    const div = document.createElement('div');\n    div.textContent = text;\n    return div.innerHTML;\n}\n\n// Global HTML escape helper. Several legacy/final UI modules run in separate\n// IIFEs and therefore cannot access their local `esc()` helpers. Keep this\n// global and data-only so all renderers use the same safe encoder.\nfunction esc(v) {\n    const text = String(v ?? '');\n    if (typeof escapeHtml === 'function') return escapeHtml(text);\n    return text.replace(/[&<>\"']/g, m => ({\n        '&':'&amp;', '<':'&lt;', '>':'&gt;', '\"':'&quot;', \"'\":'&#39;'\n    }[m]));\n}\nwindow.esc = esc;\n\nfunction dateOnly(v) {\n    if (!v) return '';\n    const d = new Date(v);\n    if (isNaN(d)) return String(v).slice(0, 10);\n    return d.toISOString().slice(0, 10);\n}\n\nfunction fmtDate(v) {\n    if (!v) return '-';\n    const d = new Date(v);\n    if (isNaN(d)) return escapeHtml(v);\n    return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });\n}\n\nfunction num(v) { return Number(v) || 0; }\n\nfunction norm(v) { return String(v || '').trim().toUpperCase(); }\n\nfunction inRange(v, from, to) {\n    const d = dateOnly(v);\n    return (!from || !d || d >= from) && (!to || !d || d <= to);\n}\n\n// Quotes from all modes\nfunction quoteRows() {\n    const all = [];\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        (db.rates?.[mode] || []).forEach(q => {\n            all.push({ ...q, __mode: mode.toUpperCase() });\n        });\n    });\n    return all;\n}\n\n// Shipment customer name\nfunction shipmentCustomer(s) {\n    return s.shipper || s.client || s.customer || s.consignee || '-';\n}\n\n// Shipment carrier\nfunction shipmentCarrier(s) {\n    return s.liner || s.carrier || s.carrierName || '-';\n}\n\n// Shipment mode\nfunction shipmentMode(s) {\n    return norm(s.mode || s.type || 'SEA');\n}\n\n/* ---------- RISK SCORE ---------- */\nfunction riskFor(s) {\n    let score = 0, reasons = [];\n    const cargo = norm(s.cargoStatus), docs = norm(s.docsStatus);\n    const now = new Date();\n    if (['CANCELLED', 'LOST'].includes(cargo)) { score += 60; reasons.push('Shipment cancelled/lost'); }\n    if (docs && !['BL APPROVED', 'TAX INVOICE SEND', 'INVOICE APPROVED', 'COMPLETED'].includes(docs)) {\n        score += 20; reasons.push('Documentation pending');\n    }\n    if (s.eta) {\n        const d = new Date(s.eta);\n        if (!isNaN(d) && d < now && !['DELIVERED', 'COMPLETED'].includes(cargo)) {\n            score += 30; reasons.push('ETA overdue');\n        }\n    }\n    if (s.etd) {\n        const d = new Date(s.etd);\n        if (!isNaN(d) && d < now && !['DEPARTED', 'IN TRANSIT', 'DELIVERED', 'COMPLETED'].includes(cargo)) {\n            score += 15; reasons.push('ETD milestone overdue');\n        }\n    }\n    if (!s.containerNo && shipmentMode(s) === 'SEA') { score += 10; reasons.push('Container not assigned'); }\n    if (!s.mblNo && shipmentMode(s) === 'SEA') { score += 8; reasons.push('MBL not available'); }\n    if (!s.hblNo) { score += 4; reasons.push('HBL not available'); }\n    if (!s.eta && !s.etd) { score += 5; reasons.push('ETD/ETA unavailable'); }\n    score = Math.min(100, score);\n    const severity = score >= 70 ? 'CRITICAL' : score >= 45 ? 'HIGH' : score >= 20 ? 'MEDIUM' : 'LOW';\n    return { score, severity, reasons };\n}\n\n/* ---------- CUT-OFFS FROM SHIPMENT ---------- */\nfunction cutoffsFor(s) {\n    const map = [\n        ['SI', s.siCutoff || s.siDeadline || s.siDate],\n        ['GATE', s.gateCutoff || s.gateDeadline || s.gateDate],\n        ['SB', s.sbCutoff || s.sbDeadline || s.sbDate],\n        ['GATE_OPENING', s.gateOpening || s.gateOpeningDate]\n    ];\n    // Legacy VGM/CY values are retained only if an existing shipment already has them.\n    if (s.vgmCutoff || s.vgmDeadline || s.vgmDate) map.push(['VGM', s.vgmCutoff || s.vgmDeadline || s.vgmDate]);\n    if (s.cyCutoff || s.cyDeadline || s.cyDate) map.push(['CY', s.cyCutoff || s.cyDeadline || s.cyDate]);\n    return map.filter(x => x[1]).map(([type, d]) => ({\n        type,\n        date: dateOnly(d),\n        job: s.jobNo || s.code || '-',\n        customer: shipmentCustomer(s),\n        vessel: s.vessel || s.flight || '-',\n        route: `${s.pol || '-'} \u2192 ${s.pod || '-'}`,\n        owner: s.sales || s.owner || '-',\n        raw: s\n    }));\n}";
})(window);


