/* SHAHID ERP 2.0 modular source segment 37/59. Source is assembled in original order and executed as one classic script to preserve global declaration hoisting. */
(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[36] = "\n\n\nfunction getEndOfMonthDate() {\n    const now = new Date();\n    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);\n    return `${lastDay.getFullYear()}-${String(lastDay.getMonth() + 1).padStart(2,'0')}-${String(lastDay.getDate()).padStart(2,'0')}`;\n}\n\n// Rate Request VALIDITY DEFAULT rule \u2014 fixed validity-cycle schedule.\n// Business cycle: VALIDITY dates are the 30th and the 14th of the following month.\n// The corresponding default becomes active on the 12th / 25th cut-offs:\n//   12th\u201324th  -> 30th of the current month\n//   25th\u201311th  -> 14th of the following month\n// Examples required by the user:\n//   12/Sep -> 30/Sep\n//   24/Sep -> 30/Sep\n//   25/Sep -> 14/Oct\n//   11/Oct -> 14/Oct\n//   12/Oct -> 30/Oct\n//   25/Oct -> 14/Nov\n// This is ONLY the initial/default date. Manual user selections are preserved.\nfunction getRateRequestDefaultValidityDate() {\n    const now = new Date();\n    const year = now.getFullYear();\n    const month = now.getMonth();\n    const day = now.getDate();\n\n    // First cycle cutoff: from the 12th through the 24th, the validity is\n    // the 30th of the current month (when a 30th exists).\n    if (day >= 12 && day <= 24) {\n        const daysInCurrentMonth = new Date(year, month + 1, 0).getDate();\n        if (daysInCurrentMonth >= 30) {\n            return `${year}-${String(month + 1).padStart(2,'0')}-30`;\n        }\n        // Defensive handling for February: no 30th exists, so use the\n        // next cycle's 14th rather than generating an invalid date.\n        const nextMonth = new Date(year, month + 1, 14);\n        return `${nextMonth.getFullYear()}-${String(nextMonth.getMonth() + 1).padStart(2,'0')}-14`;\n    }\n\n    // Second cycle cutoff: from the 25th through the end of the month,\n    // and from the 1st through the 11th of the next month, the validity\n    // is the 14th of the next month.\n    if (day >= 25) {\n        const nextMonth = new Date(year, month + 1, 14);\n        return `${nextMonth.getFullYear()}-${String(nextMonth.getMonth() + 1).padStart(2,'0')}-14`;\n    }\n\n    // day 1\u201311: the active cycle is still the 14th of the current month.\n    // If today is the 1st\u201311th and that 14th has not passed, use it.\n    return `${year}-${String(month + 1).padStart(2,'0')}-14`;\n}\n\n// Rate Request VALIDITY manual-date handler.\n// The browser date picker already provides date validation.\n// IMPORTANT: never convert the user's selected date to month-end.\nfunction setRateRequestMonthEnd(el) {\n    if (!el) return '';\n    return String(el.value || '').trim();\n}\n\n\nfunction formatEmailQuotationDate(value) {\n    if (!value) return '-';\n    const raw = String(value).trim();\n    let d;\n    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(raw)) {\n        const [y,m,day] = raw.split('-').map(Number);\n        d = new Date(y, m - 1, day);\n    } else {\n        d = new Date(raw);\n    }\n    if (isNaN(d.getTime())) return raw;\n    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n    return `${d.getFullYear()}-${months[d.getMonth()]}-${String(d.getDate()).padStart(2,'0')}`;\n}\n\nfunction buildRateRequestPreviewHTML(data) {\n    const format = data.format;\n    const company = db.companyName || 'GATEWAY EXIM';\n    const userName = getLoggedInUserName() || db.defaultUser || 'N/A';\n    \n    let rows = [];\n    // Add mode at the top\n    rows.push(['MODE', data.mode === 'AIR' ? '\u2708\ufe0f AIR' : '\ud83d\udea2 SEA']);\n\n    if (format === 'seaWithShipper') {\n        rows = rows.concat([\n            ['SHIPPER', data.shipper || '-'],\n            ['FORWARDER', data.forwarder || company],\n            ['POL', data.pol || '-'],\n            ['POD', data.pod || '-'],\n            ['INVENTORY', data.inventory || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['FREIGHT TERM', data.term || '-'],\n            ['DEST. FREE TIME', data.freeTime || '-']\n        ]);\n    } else if (format === 'seaWithoutShipper') {\n        rows = rows.concat([\n            ['FORWARDER', data.forwarder || company],\n            ['POL', data.pol || '-'],\n            ['POD', data.pod || '-'],\n            ['INVENTORY', data.inventory || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['VALIDITY', formatEmailQuotationDate(data.validity)],\n            ['FREIGHT TERM', data.term || '-'],\n            ['DEST. FREE TIME', data.freeTime || '-']\n        ]);\n    } else if (format === 'air') {\n        rows = rows.concat([\n            ['SHIPPER', data.shipper || '-'],\n            ['POL', data.pol || '-'],\n            ['POD', data.pod || '-'],\n            ['CLEARANCE DATE', data.clearance || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['PACKAGING', data.packaging || '-'],\n            ['PALLETIZED OR LOOSE', data.pallet || '-'],\n            ['DIMENSION (L x W x H)', data.dimension || '-'],\n            ['TEMP CARGO', data.temp || '-']\n        ]);\n    }\n\n    rows = dedupeRateRequestRows(rows);\n\n    let rowsHtml = rows.map(([label, value]) => `\n        <tr>\n            <td style=\"border:1px solid #d1d5db;padding:4px 7px;font-weight:700;width:30%;background:#f8fafc;\">${label}</td>\n            <td style=\"border:1px solid #d1d5db;padding:4px 7px;width:70%;\">${value}</td>\n        </tr>\n    `).join('');\n\n    let html = `\n    <div style=\"background:#ffffff;color:#1a1a1a;font-family:'Segoe UI',Arial,sans-serif;max-width:100%;margin:0 auto;padding:10px;box-sizing:border-box;\">\n        <div style=\"border-bottom:2px solid #1e3a8a;padding-bottom:6px;margin-bottom:8px;\">\n            <div style=\"font-size:0.9rem;font-weight:700;color:#1e3a8a;\">${company}</div>\n            <div style=\"font-size:0.65rem;color:#64748b;\">${db.companyAddress || ''}</div>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;\">\n            <div style=\"text-align:left;\">\n                <div style=\"font-size:1.2rem;color:#1e3a8a;font-weight:800;letter-spacing:1px;\">\ud83d\udce9 RATE REQUEST</div>\n                <div style=\"font-size:0.8rem;color:#64748b;\">${data.mode === 'AIR' ? '\u2708\ufe0f AIR' : '\ud83d\udea2 SEA'}</div>\n            </div>\n            <div style=\"text-align:right;\">\n                <div style=\"font-family:'Courier New',monospace;color:#d97706;font-weight:700;font-size:0.85rem;background:#fffbeb;padding:4px 10px;border-radius:4px;\">${new Date().toLocaleDateString('en-IN')}</div>\n            </div>\n        </div>\n        <p style=\"font-size:1.5 rem;color:#1a1a1a;margin:4px 0 10px 0;\">Please assist to quote the rates as per below.</p>\n        <table style=\"width:100%;border-collapse:collapse;font-size:0.78rem;\">\n            <thead>\n                <tr><th colspan=\"2\" style=\"background:#1e3a8a;color:white;padding:4px 7px;font-size:0.78rem;text-align:center;\">Rate Request Details</th></tr>\n            </thead>\n            <tbody>\n                ${rowsHtml}\n            </tbody>\n        </table>`;\n\n    // ---- \ud83c\udd95 ADD REMARKS SECTION ----\n    if (data.remarks && String(data.remarks).trim()) {\n        const remarkLines = String(data.remarks)\n            .replace(/<br\\s*\\/?>(?:\\s*)/gi, '\\n')\n            .replace(/<[^>]*>/g, '')\n            .split(/\\r\\n|\\r|\\n/)\n            .map(line => line.trim())\n            .filter(Boolean)\n            .map(line => line.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;'))\n            .map(line => `<div style=\"margin:0 0 5px 0;color:#dc2626;font-weight:700;font-size:0.85rem;line-height:1.4;\">${line}</div>`)\n            .join('');\n        html += `\n        <div style=\"margin-top:12px; border-top:1px solid #e2e8f0; padding-top:8px;\">\n            <div style=\"font-weight:700; color:#dc2626; font-size:0.78rem;\">\ud83d\udcdd Remarks</div>\n            <div style=\"padding:6px 10px; margin-top:4px;\">\n                ${remarkLines}\n            </div>\n        </div>`;\n    }\n\n    html += `</div>`;\n    return html;\n}\n\n\nfunction buildRateRequestCompactEmailHTML(data) {\n    const format = data.format;\n    const company = db.companyName || 'GATEWAY EXIM';\n    \n    let rows = [];\n    // Add MODE row at the top\n    rows.push(['MODE', data.mode === 'AIR' ? '\u2708\ufe0f AIR' : '\ud83d\udea2 SEA']);\n\n    if (format === 'seaWithShipper') {\n        rows = rows.concat([\n            ['SHIPPER', data.shipper || '-'],\n            ['FORWARDER', data.forwarder || company],\n\t\t\t['POL', data.pol || '-'],         \n            ['POD', data.pod || '-'],\n            ['INVENTORY', data.inventory || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['VALIDITY', formatEmailQuotationDate(data.validity)],\n            ['FREIGHT TERM', data.term || '-'],\n            ['DEST. FREE TIME', data.freeTime || '-']\n        ]);\n    } else if (format === 'seaWithoutShipper') {\n        rows = rows.concat([\n            ['FORWARDER', data.forwarder || company],\n\t\t\t['POL', data.pol || '-'],            \n            ['POD', data.pod || '-'],\n            ['INVENTORY', data.inventory || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['VALIDITY', formatEmailQuotationDate(data.validity)],\n            ['FREIGHT TERM', data.term || '-'],\n            ['DEST. FREE TIME', data.freeTime || '-']\n        ]);\n    } else if (format === 'air') {\n        rows = rows.concat([\n            ['SHIPPER', data.shipper || '-'],\n            ['POL', data.pol || '-'],\n            ['POD', data.pod || '-'],\n            ['CLEARANCE DATE', data.clearance || '-'],\n            ['COMMODITY', data.commodity || '-'],\n            ['GROSS WEIGHT', data.weight ? data.weight + ' Kgs' : '-'],\n            ['PACKAGING', data.packaging || '-'],\n            ['PALLETIZED OR LOOSE', data.pallet || '-'],\n            ['DIMENSION (L x W x H)', data.dimension || '-'],\n            ['TEMP CARGO', data.temp || '-']\n        ]);\n    }\n\n    rows = dedupeRateRequestRows(rows);\n\n    let rowsHtml = rows.map(([label, value]) => `\n        <tr>\n            <td style=\"border:1px solid #d1d5db;padding:4px 8px;font-weight:700;width:35%;background:#f8fafc;\">${label}</td>\n            <td style=\"border:1px solid #d1d5db;padding:4px 8px;width:65%;\">${value}</td>\n        </tr>\n    `).join('');\n\n    let html = `<div style=\"font-family:'Aptos','Segoe UI',Arial,sans-serif;max-width:17cm;min-width:6cm;width:auto;margin:0 auto;background:#ffffff;padding:4px;box-sizing:border-box;color:#1a1a1a;font-size:10px;\">\n        <p style=\"margin:0 0 4px 0;font-size:17px;line-height:1.4;\">Dear Sir/Madam,</p>\n        <br>\n        <p style=\"margin:0 0 15px 0;font-size:17px;line-height:1.4;\">Good Day !</p>\n        <p style=\"font-size:17px;color:#1a1a1a;margin:-4px 0 10px 0;\">Please assist to quote the rates as per below.</p>\n        <div style=\"font-size:17px;font-weight:800;color:#1e3a8a;\">RATE REQUEST \u2014 ${data.mode === 'AIR' ? '\u2708\ufe0f AIR' : '\ud83d\udea2 SEA'}</div>\n        <br>\n        <table style=\"width:15cm;min-width:15cm;max-width:100%;border-collapse:collapse;margin-top:0;font-size:15px;\">\n            <thead>\n                <tr><th colspan=\"2\" style=\"border:1px solid #1e3a8a;padding:4px 8px;text-align:center;background:#1e3a8a;color:white;font-weight:700;font-size:17px;line-height:1.4;vertical-align:middle;\">Rate Request Details</th></tr>\n            </thead>\n            <tbody>\n                ${rowsHtml}\n            </tbody>\n        </table>`;\n\n    // ---- RATE REQUEST REMARKS \u2014 PLAIN TEXT, LINE-BY-LINE (NO TABLE) ----\n    if (data.remarks && String(data.remarks).trim()) {\n        const remarkLines = String(data.remarks)\n            .split(/\\r\\n|\\r|\\n/)\n            .map(line => line.trim())\n            .filter(Boolean)\n            .map(line => `<div style=\"margin:0 0 6px 0;color:#1a1a1a;font-size:15px;line-height:1.4;\">${line.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;')}</div>`)\n            .join('');\n        html += `\n        <br>\n        <div style=\"font-size:17px;font-weight:700;color:#1e3a8a;margin-bottom:6px;\">Remarks</div>\n        <div style=\"font-size:15px;line-height:1.4;color:#1a1a1a;\">${remarkLines}</div>`;\n    }\n\n    html += `</div>`;\n    return html;\n}\n\n\n\nfunction previewRateRequest() {\n    const format = currentRateRequestFormat;\n    const data = getRateRequestData(format);\n    if (!data.pol || !data.pod) {\n        alert('Please select both POL and POD.');\n        return;\n    }\n    // \u2705 Store for copy function\n    _previewRRData = data;\n\n    const html = buildRateRequestPreviewHTML(data);\n    document.getElementById('modal-title').textContent = 'Rate Request Preview';\n    document.getElementById('previewBody').innerHTML = `\n        <div style=\"margin-bottom:10px; display:flex; gap:8px; flex-wrap:wrap;\">\n            <button class=\"btn btn-info\" onclick=\"copyRateRequestTables()\">\ud83d\udccb Copy Tables (Compact)</button>\n        </div>\n        ${html}\n    `;\n    document.getElementById('previewBody').style.background = 'white';\n    openModal('previewModal');\n}\n\n\nfunction copyRateRequestTables() {\n    // \u2705 Use stored data if available, else fetch from form\n    let data = _previewRRData;\n    if (!data) {\n        const format = currentRateRequestFormat;\n        data = getRateRequestData(format);\n        console.log('\ud83d\udcca No stored preview data, fetched from form:', data);\n    } else {\n        console.log('\ud83d\udcca Using stored preview data:', data);\n    }\n\n    if (!data.pol || !data.pod) {\n        alert('\u26a0\ufe0f Please select both POL and POD before copying.');\n        return;\n    }\n\n    const compactHtml = buildRateRequestCompactEmailHTML(data);\n    console.log('\ud83d\udcc4 HTML built, length:', compactHtml.length);\n\n    if (navigator.clipboard && navigator.clipboard.write) {\n        const blobHTML = new Blob([compactHtml], { type: 'text/html' });\n        const blobPlain = new Blob([`Rate Request - ${data.pol} to ${data.pod}`], { type: 'text/plain' });\n        const clipboardItem = new ClipboardItem({\n            'text/html': blobHTML,\n            'text/plain': blobPlain\n        });\n        navigator.clipboard.write([clipboardItem])\n            .then(() => {\n                alert('\u2705 Tables copied with formatting!');\n            })\n            .catch(function(err) {\n                console.warn('Clipboard API error:', err);\n                fallbackCopyText(compactHtml);\n                alert('\u26a0\ufe0f Copied as plain text (formatting may be lost).');\n            });\n    } else {\n        fallbackCopyText(compactHtml);\n        alert('\u2705 Copied as plain text.');\n    }\n}\n\n\nfunction populateDrumTypesDropdown() {\n    const sel = document.getElementById('rr-drum-type');\n    if (!sel) return;\n    const drums = db.drumTypes || [];\n    sel.innerHTML = '<option value=\"\">Select Drum Type</option>' +\n        drums.map(d => `<option value=\"${d.id}\">${d.name} (${d.length}\u00d7${d.width}\u00d7${d.height} cm, ${d.weightPerDrum} kg)</option>`).join('');\n}\n\n\nfunction onDrumTypeChange() {\n    const sel = document.getElementById('rr-drum-type');\n    if (!sel) return;\n    const id = sel.value;\n    if (!id) return;\n    const drum = (db.drumTypes || []).find(d => d.id === id);\n    if (!drum) return;\n    const lEl = document.getElementById('rr-drum-l');\n    const wEl = document.getElementById('rr-drum-w');\n    const hEl = document.getElementById('rr-drum-h');\n    const wtEl = document.getElementById('rr-drum-weight');\n    if (lEl) lEl.value = drum.length || '';\n    if (wEl) wEl.value = drum.width || '';\n    if (hEl) hEl.value = drum.height || '';\n    if (wtEl) wtEl.value = drum.weightPerDrum || '';\n    calculateDrumTotals();\n}\n\n\nfunction calculateDrumTotals() {\n    const qtyEl = document.getElementById('rr-drum-qty');\n    const wtEl = document.getElementById('rr-drum-weight');\n    const totalEl = document.getElementById('rr-drum-total');\n    if (!qtyEl || !wtEl || !totalEl) return;\n    const qty = parseFloat(qtyEl.value) || 0;\n    const wt = parseFloat(wtEl.value) || 0;\n    const total = qty * wt;\n    totalEl.value = total > 0 ? total.toFixed(2) + ' Kgs' : '0.00 Kgs';\n}\n\nfunction useDrumWeight() {\n    const totalEl = document.getElementById('rr-drum-total');\n    const gwEl = document.getElementById('rr-gross-weight');\n    if (!gwEl || !totalEl) return;\n    const totalVal = parseFloat(totalEl.value) || 0;\n    if (totalVal > 0) {\n        gwEl.value = totalVal.toFixed(2);\n    } else {\n        alert('Please enter Quantity and Weight per Drum to calculate total.');\n    }\n}\n\n\n\nfunction sendRateRequestEmail() {\n    const format = currentRateRequestFormat;\n    const data = getRateRequestData(format);\n    if (!data.pol || !data.pod) {\n        alert('Please select both POL and POD.');\n        return;\n    }\n\n    // Determine default CC based on mode\n    let defaultCC = '';\n    if (data.mode === 'AIR') {\n        defaultCC = db.defaultCCEmailAir || '';\n    } else {\n        // SEA\n        defaultCC = db.defaultCCEmailSea || '';\n    }\n\n    // Generate quote number\n    const now = new Date();\n    const base = `RR-${String(now.getFullYear()).slice(-2)}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}`;\n    const all = db.drafts.rr || [];\n    let seq = 1;\n    let qn = base;\n    while (all.some(r => r.quoteNumber === qn)) { seq++; qn = `${base}-${String(seq).padStart(2,'0')}`; }\n    data.quoteNumber = qn;\n\n    const htmlContent = buildRateRequestCompactEmailHTML(data);\n    currentEmailData = { data: data, mode: 'raterequest', htmlContent: htmlContent };\n\n    // Subject with mode\n    const modeLabel = data.mode === 'AIR' ? 'AIR' : 'SEA';\n    const subject = `${modeLabel} RATE REQUEST // ${qn} // ${data.pol} TO ${data.pod} // ${data.commodity}`;\n    document.getElementById('email-subject').value = subject;\n    document.getElementById('email-html-preview').innerHTML = htmlContent;\n    document.getElementById('email-cc').value = defaultCC;\n\n    openModal('emailModal');\n}\n\n\n\nfunction saveRateRequestDraft() {\n    const format = currentRateRequestFormat;\n    const data = getRateRequestData(format);\n    if (!data.pol || !data.pod) {\n        alert('Please select both POL and POD.');\n        return;\n    }\n    const qn = saveRateRequestDraftWithData(data);\n    alert(`Rate Request saved as Draft!\\nQuote Number: ${qn}`);\n}\n\n\nfunction saveRateRequestDraftWithData(data) {\n    // If no quote number, generate one\n    if (!data.quoteNumber) {\n        const now = new Date();\n        const base = `RQ-RR-${String(now.getFullYear()).slice(-2)}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}`;\n        const all = db.drafts.rr || [];\n        let seq = 1;\n        let qn = base;\n        while (all.some(r => r.quoteNumber === qn)) { seq++; qn = `${base}-${String(seq).padStart(2,'0')}`; }\n        data.quoteNumber = qn;\n    }\n    data.timestamp = new Date().toISOString();\n    data.lastModified = new Date().toISOString();\n    data.mode = 'rr';\n    data.status = 'DRAFT';\n    data.followUpStatus = 'PENDING';\n\n    if (!db.drafts.rr) db.drafts.rr = [];\n    db.drafts.rr.push(data);\n    saveDB();\n    return data.quoteNumber;\n}\n\nfunction previewRateRequestDraft(target, mode, idx) {\n    const rec = db[target][mode][idx];\n    if (!rec) {\n        alert('Record not found.');\n        return;\n    }\n    let format = rec.format || 'seaWithShipper';\n    if (rec.clearance !== undefined) format = 'air';\n    else if (rec.shipper && !rec.forwarder) format = 'seaWithShipper';\n    else if (!rec.shipper && rec.forwarder) format = 'seaWithoutShipper';\n    else if (rec.shipper && rec.forwarder) format = 'seaWithShipper';\n    \n    currentRateRequestFormat = format;\n    _previewRRData = rec;\n\n    const modeLabel = rec.mode === 'AIR' ? '\u2708\ufe0f AIR' : '\ud83d\udea2 SEA';\n    const html = buildRateRequestPreviewHTML(rec);\n    document.getElementById('modal-title').textContent = `${modeLabel} Rate Request Preview`;\n    document.getElementById('previewBody').innerHTML = `\n        <div style=\"margin-bottom:10px; display:flex; gap:8px; flex-wrap:wrap;\">\n            <button class=\"btn btn-info\" onclick=\"copyRateRequestTables()\">\ud83d\udccb Copy Tables (Compact)</button>\n        </div>\n        ${html}\n    `;\n    document.getElementById('previewBody').style.background = 'white';\n    openModal('previewModal');\n}\n\n\n\nfunction convertRRToQuote(target, mode, idx) {\n    // Get the RR draft data\n    const rrData = db[target][mode][idx];\n    if (!rrData) {\n        alert('Rate Request not found.');\n        return;\n    }\n\n    // Determine which mode (SEA, AIR, LCL) this RR belongs to\n    let targetMode = 'sea'; // default\n    if (rrData.format === 'air' || rrData.clearance !== undefined) {\n        targetMode = 'air';\n    } else if (rrData.format === 'seaWithShipper' || rrData.format === 'seaWithoutShipper') {\n        targetMode = 'sea';\n    } else {\n        // Fallback: check if specific fields exist\n        if (rrData.clearance !== undefined) targetMode = 'air';\n        else if (rrData.shipper !== undefined) targetMode = 'sea';\n        else targetMode = 'sea';\n    }\n\n    // Switch to the appropriate tab\n    switchToTab(targetMode);\n\n    // Map RR fields to quotation fields\n    const fieldMap = {\n        'client': rrData.shipper || rrData.forwarder || '',\n        'pol': rrData.pol || '',\n        'pod': rrData.pod || '',\n        'commodity': rrData.commodity || '',\n        'weight': rrData.weight || '',\n        'carrier': '', // RR doesn't have carrier \u2013 leave empty for user to fill\n        'incoterm': rrData.term || '',\n        'transit': '', // RR doesn't have transit time \u2013 user will fill\n        'validityDate': rrData.validity || '',\n    };\n\n    // If SEA, also set container\n    if (targetMode === 'sea') {\n        fieldMap.container = rrData.inventory || '';\n    }\n\n    // If AIR, also set pallets and volume (if available)\n    if (targetMode === 'air') {\n        fieldMap.pallets = '';\n        fieldMap.volume = '';\n    }\n\n    // Populate the form fields\n    Object.keys(fieldMap).forEach(key => {\n        const el = document.getElementById(`${targetMode}-${key}`);\n        if (el && fieldMap[key] !== undefined && fieldMap[key] !== null) {\n            el.value = fieldMap[key];\n        }\n    });\n\n    // Set the quote number from the RR draft\n    const qnBox = document.getElementById(`${targetMode}-qn-box`);\n    const qnValue = document.getElementById(`${targetMode}-qn-value`);\n    if (qnBox && qnValue && rrData.quoteNumber) {\n        qnValue.textContent = rrData.quoteNumber;\n        qnBox.classList.add('show');\n    }\n\n    // Confirm conversion and remove RR draft\n    if (confirm(`Convert RR draft \"${rrData.quoteNumber}\" to ${targetMode.toUpperCase()} quotation? The RR draft will be removed.`)) {\n        db[target][mode].splice(idx, 1);\n        saveDB();\n        renderRecords('drafts');\n        alert(`\u2705 RR draft converted to ${targetMode.toUpperCase()} quotation.\\nQuote Number: ${rrData.quoteNumber}\\n\\nPlease fill freight rates and charges, then click QUOTE to finalize.`);\n    }\n}\n\nfunction convertRRToQuoteFromPreview(target, mode, idx) {\n    closeModal('previewModal');\n    convertRRToQuote(target, mode, idx);\n}\n\n\n// Save all three default CCs\nfunction saveDefaultCC() {\n    db.defaultCCEmailSea = document.getElementById('default-cc-sea').value.trim();\n    db.defaultCCEmailAir = document.getElementById('default-cc-air').value.trim();\n    db.defaultCCEmailLcl = document.getElementById('default-cc-lcl').value.trim();\n    saveDB();\n    loadDefaultCC();\n    alert('Default CC emails saved!');\n    autoBackup();\n}\n\nfunction loadDefaultCC() {\n    const sea = document.getElementById('default-cc-sea');\n    const air = document.getElementById('default-cc-air');\n    const lcl = document.getElementById('default-cc-lcl');\n    const currentSea = document.getElementById('current-cc-sea');\n    const currentAir = document.getElementById('current-cc-air');\n    const currentLcl = document.getElementById('current-cc-lcl');\n\n    if (sea) sea.value = db.defaultCCEmailSea || '';\n    if (air) air.value = db.defaultCCEmailAir || '';\n    if (lcl) lcl.value = db.defaultCCEmailLcl || '';\n\n    if (currentSea) currentSea.textContent = db.defaultCCEmailSea || 'Not Set';\n    if (currentAir) currentAir.textContent = db.defaultCCEmailAir || 'Not Set';\n    if (currentLcl) currentLcl.textContent = db.defaultCCEmailLcl || 'Not Set';\n}\n\n// Render RR Drafts (dedicated tab)\nfunction renderRRDrafts() {\n    const list = document.getElementById('rrdrafts-list');\n    const counters = document.getElementById('rrdrafts-counters');\n    if (!list) return;\n\n    const searchText = (document.getElementById('rrdrafts-search-text')?.value || '').toLowerCase();\n    const searchQN = (document.getElementById('rrdrafts-search-qn')?.value || '').toLowerCase();\n    const searchDate = document.getElementById('rrdrafts-search-date')?.value || '';\n    const modeFilter = document.getElementById('rrdrafts-mode-filter')?.value || '';\n\n    let records = db.drafts.rr || [];\n    records = records.filter(r => {\n        const text = `${r.shipper||''} ${r.pol||''} ${r.pod||''} ${r.forwarder||''}`.toLowerCase();\n        if (searchText && !text.includes(searchText)) return false;\n        const qn = (r.quoteNumber || '').toLowerCase();\n        if (searchQN && !qn.includes(searchQN)) return false;\n        if (searchDate) {\n            const d = new Date(r.timestamp).toISOString().split('T')[0];\n            if (d !== searchDate) return false;\n        }\n        if (modeFilter && r.mode !== modeFilter) return false;\n        return true;\n    });\n\n    if (counters) {\n        counters.innerHTML = `\n            <div class=\"counter-card\" style=\"border-color:#ec4899;\">\n                <div class=\"counter-label\">\ud83d\udce9 Total Rate Requested</div>\n                <div class=\"counter-value\">${records.length}</div>\n            </div>\n        `;\n    }\n\n    if (records.length === 0) {\n        list.innerHTML = '<p style=\"color:var(--text-light);padding:20px;text-align:center;\">No RR drafts found.</p>';\n        return;\n    }\n\n    list.innerHTML = records.map((rec, idx) => {\n        const realIdx = db.drafts.rr.indexOf(rec);\n        const modeClass = 'highlight-rr';\n        const displayName = rec.shipper || rec.forwarder || rec.client || '?';\n        const route = `${rec.pol || '?'} \u2192 ${rec.pod || '?'}`;\n        const lastMod = rec.lastModified ? new Date(rec.lastModified).toLocaleString('en-IN') : new Date(rec.timestamp).toLocaleString('en-IN');\n        const modeIcon = rec.mode === 'AIR' ? '\u2708\ufe0f' : '\ud83d\udea2';\n        const modeLabel = rec.mode === 'AIR' ? 'AIR Rate Request' : 'SEA Rate Request';\n\n        return `<div class=\"record-card ${modeClass}\">\n            <div class=\"record-info\">\n                <h4>${modeIcon} ${modeLabel} \u2014 ${displayName} (${route})</h4>\n                <p>Format: ${rec.format || 'N/A'} | Status: <strong>${rec.status || 'DRAFT'}</strong></p>\n                <p class=\"quote-num\">\ud83d\udccb ${rec.quoteNumber || 'N/A'}</p>\n                <p class=\"last-modified\">\ud83d\udd50 Last Modified: ${lastMod}</p>\n            </div>\n            <div class=\"record-actions\">\n                <button class=\"btn btn-sm btn-preview\" onclick=\"previewRateRequestDraft('drafts','rr',${realIdx})\">\ud83d\udc41 Preview</button>\n                <button class=\"btn btn-sm btn-quoted\" onclick=\"convertRRToQuote('drafts','rr',${realIdx})\">\ud83d\udce4 Quote</button>\n                <button class=\"btn btn-sm btn-duplicate\" onclick=\"duplicateQuote('drafts','rr',${realIdx})\">\ud83d\udccb Duplicate</button>\n                <button class=\"btn btn-sm btn-draft\" onclick=\"editRecord('drafts','rr',${realIdx})\">\u270f\ufe0f Edit</button>\n                <button class=\"btn btn-sm btn-clear\" onclick=\"deleteRecord('drafts','rr',${realIdx})\">\ud83d\uddd1\ufe0f Delete</button>\n            </div>\n        </div>`;\n    }).join('');\n}\n\n// Clear RR Drafts filters\nfunction clearRRDraftsFilters() {\n    document.getElementById('rrdrafts-search-text').value = '';\n    document.getElementById('rrdrafts-search-qn').value = '';\n    document.getElementById('rrdrafts-search-date').value = '';\n    rrModeFilter = '';\n    sessionStorage.removeItem('rrModeFilter');\n    renderRecords('rrdrafts');\n}\n\n\n\n/* ===== END JS/53-quote-drafts-sync.js ===== */\n\n/* ===== BEGIN JS/54-rate-sheet-actions.js ===== */\n/* Original source preserved from 18-quote-drafts-sync.js; assigned to this functional module without code changes. */\n// ==================== RATE QUOTE FILTER HELPERS ====================\n// ==================== ALL QUOTE & RATE SHEET DATE/EXPORT HELPERS ====================\nfunction quoteTableDateOnly(value) {\n    if (!value) return null;\n    const d = new Date(value);\n    if (Number.isNaN(d.getTime())) return null;\n    return new Date(d.getFullYear(), d.getMonth(), d.getDate());\n}\nfunction quoteTableDateInRange(value, fromValue, toValue) {\n    if (!fromValue && !toValue) return true;\n    const d = quoteTableDateOnly(value);\n    if (!d) return false;\n    if (fromValue) {\n        const from = quoteTableDateOnly(fromValue);\n        if (from && d < from) return false;\n    }\n    if (toValue) {\n        const to = quoteTableDateOnly(toValue);\n        if (to && d > to) return false;\n    }\n    return true;\n}\nfunction quoteTableDateControls(prefix, onFilter, onReset, onExcel, onPdf) {\n    return `\n        <span style=\"font-weight:600;font-size:0.8rem;color:var(--text-light);white-space:nowrap;\">\ud83d\udcc5 Date:</span>\n        <label style=\"font-size:0.78rem;font-weight:600;white-space:nowrap;\">From <input id=\"${prefix}-date-from\" type=\"date\" style=\"padding:6px 8px;border:1px solid var(--border);border-radius:6px;\" /></label>\n        <label style=\"font-size:0.78rem;font-weight:600;white-space:nowrap;\">To <input id=\"${prefix}-date-to\" type=\"date\" style=\"padding:6px 8px;border:1px solid var(--border);border-radius:6px;\" /></label>\n        <button class=\"btn btn-sm btn-info\" type=\"button\" onclick=\"${onFilter}\">\ud83d\udd0d Filter</button>\n        <button class=\"btn btn-sm btn-clear\" type=\"button\" onclick=\"${onReset}\">\u21bb Reset</button>\n        <button class=\"btn btn-sm btn-export\" type=\"button\" onclick=\"${onExcel}\">\ud83d\udcca Excel</button>\n        <button class=\"btn btn-sm btn-pdf\" type=\"button\" onclick=\"${onPdf}\">\ud83d\udcc4 PDF</button>`;\n}\nfunction validateQuoteTableDateRange(prefix) {\n    const from = document.getElementById(`${prefix}-date-from`)?.value || '';\n    const to = document.getElementById(`${prefix}-date-to`)?.value || '';\n    if (from && to && from > to) {\n        alert('From Date cannot be later than To Date.');\n        return null;\n    }\n    return { from, to };\n}\nfunction quoteTableRowsToExcel(rows, columns, sheetName, fileName) {\n    if (typeof XLSX === 'undefined') return alert('Excel library is not loaded.');\n    if (!rows.length) return alert('No data to export for the selected filters.');\n    const out = rows.map(r => Object.fromEntries(columns.map(([header, getter]) => [header, getter(r)])));\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(out), sheetName);\n    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().slice(0,10)}.xlsx`);\n}\nfunction quoteTableRowsToPDF(rows, columns, title, fileName) {\n    if (!rows.length) return alert('No data to export for the selected filters.');\n    if (!window.jspdf?.jsPDF) return alert('PDF library is not loaded.');\n    const doc = new window.jspdf.jsPDF({ orientation:'landscape', unit:'mm', format:'a4' });\n    doc.setFontSize(15); doc.text(title, 10, 12);\n    const from = document.getElementById(`${fileName}-date-from`)?.value || '';\n    const to = document.getElementById(`${fileName}-date-to`)?.value || '';\n    doc.setFontSize(8); doc.text(`Date Range: ${from || 'All'} to ${to || 'All'} | Records: ${rows.length}`, 10, 18);\n    doc.autoTable({\n        startY: 23,\n        head: [columns.map(c => c[0])],\n        body: rows.map(r => columns.map(c => c[1](r))),\n        styles: { fontSize: 7, cellPadding: 1.8, overflow: 'linebreak' },\n        headStyles: { fillColor: [30,58,138], textColor: 255 },\n        margin: { left: 8, right: 8 }\n    });\n    doc.save(`${fileName}_${new Date().toISOString().slice(0,10)}.pdf`);\n}\n\nfunction normalizeDateOnly(value) {\n    if (!value) return null;\n    const d = new Date(value);\n    if (Number.isNaN(d.getTime())) return null;\n    d.setHours(0,0,0,0);\n    return d;\n}\n\nfunction isQuoteExpired(q) {\n    const d = normalizeDateOnly(q?.validityDate || q?.validTill || q?.validUntil);\n    if (!d) return false;\n    const today = new Date();\n    today.setHours(0,0,0,0);\n    return d < today;\n}\n\nfunction isQuoteConverted(q) {\n    if (!q) return false;\n    if (q.convertedToShipment === true || q.converted === true || q.convertedShipmentId) return true;\n    const refs = [q.shipmentCode, q.shipmentNo, q.jobNo, q.jobNumber, q.convertedJobNo]\n        .map(v => String(v || '').trim().toLowerCase()).filter(Boolean);\n    if (!refs.length) return false;\n    return (db.shipments || []).some(s => {\n        const sRefs = [s.jobNo, s.code, s.shipmentCode, s.quoteRef, s.quoteNumber, s.rateQuoteRef]\n            .map(v => String(v || '').trim().toLowerCase()).filter(Boolean);\n        return refs.some(r => sRefs.includes(r));\n    });\n}\n\n// ==================== ENHANCED RATES VIEW ====================\nlet ratesSortColumn = 'timestamp';\nlet ratesSortOrder = 'desc';";
})(window);


/* ===== ORIGINAL MODULE: JS/quotes-rates-d.js ===== */
/* SHAHID ERP 2.0 modular source segment 38/59. Source is assembled in original order and executed as one classic script to preserve global declaration hoisting. */
(function(g){
  var parts = g.__SHAHID_ERP_SOURCE_PARTS || (g.__SHAHID_ERP_SOURCE_PARTS = []);
  parts[37] = " // 'asc' or 'desc'\n\nfunction renderEnhancedRates() {\n    const container = document.getElementById('rates-list-container');\n    const paginationEl = document.getElementById('rates-pagination');\n    if (!container) return;\n\n    // ===== Preserve the existing Rate Quotes toolbar/filter state =====\n    // Remove only duplicate/legacy action bars. Keep the live rates toolbar\n    // so From/To values are not destroyed when FILTER re-renders the table.\n    document.querySelectorAll('#rates .rates-action-bar').forEach(el => {\n        if (el.id !== 'rates-toolbar') el.remove();\n    });\n\n    // ===== Create the toolbar only if it does not already exist =====\n    let toolbarEl = document.getElementById('rates-toolbar');\n    if (!toolbarEl) {\n        toolbarEl = document.createElement('div');\n        toolbarEl.id = 'rates-toolbar';\n        toolbarEl.className = 'rates-action-bar';\n        toolbarEl.style.cssText = 'display:flex; gap:6px; flex-wrap:wrap; margin:8px 0; align-items:center;';\n        toolbarEl.innerHTML = `\n            <span style=\"font-weight:600; font-size:0.8rem; color:var(--text-light); margin-right:8px;\">Actions:</span>\n            ${quoteTableDateControls('rates','applyRatesDateFilter()','resetRatesDateFilter()','exportRatesDateExcel()','exportRatesDatePDF()')}\n            <button class=\"btn btn-sm btn-preview\" onclick=\"ratesBulkAction('preview')\">\ud83d\udc41 Preview</button>\n            <button class=\"btn btn-sm btn-pdf\" onclick=\"ratesBulkAction('pdf')\">\ud83d\udcc4 PDF</button>\n            <button class=\"btn btn-sm btn-email\" onclick=\"ratesBulkAction('email')\">\ud83d\udce7 Email</button>\n            <button class=\"btn btn-sm btn-success\" onclick=\"ratesBulkAction('convert')\">\ud83d\udea2 Convert to Shipment</button>\n            <button class=\"btn btn-sm btn-duplicate\" onclick=\"ratesBulkAction('duplicate')\">\ud83d\udccb Duplicate</button>\n            <button class=\"btn btn-sm btn-draft\" onclick=\"ratesBulkAction('edit')\">\u270f\ufe0f Edit</button>\n            <button class=\"btn btn-sm btn-clear\" onclick=\"ratesBulkAction('delete')\">\ud83d\uddd1\ufe0f Delete</button>\n            <span style=\"margin-left:auto; font-size:0.75rem; color:var(--text-light);\" id=\"rates-selected-count\">0 selected</span>\n        `;\n        const filterRow = document.querySelector('#rates .filter-row');\n        if (filterRow) filterRow.after(toolbarEl);\n        else container.before(toolbarEl);\n\n        // Restore the last applied date filter when the toolbar is recreated.\n        const savedFrom = sessionStorage.getItem('ratesDateFrom') || '';\n        const savedTo = sessionStorage.getItem('ratesDateTo') || '';\n        const fromEl = document.getElementById('rates-date-from');\n        const toEl = document.getElementById('rates-date-to');\n        if (fromEl) fromEl.value = savedFrom;\n        if (toEl) toEl.value = savedTo;\n    }\n\n    // ===== Get filter values =====\n    const searchText = (document.getElementById('rates-search-text')?.value || '').toLowerCase();\n    const searchQN = (document.getElementById('rates-search-qn')?.value || '').toLowerCase();\n    const searchDate = document.getElementById('rates-search-date')?.value || '';\n    const statusFilter = document.getElementById('rates-status-filter')?.value || '';\n    const modeFilter = document.getElementById('rates-mode-filter')?.value || '';\n    const userFilter = document.getElementById('rates-user-filter')?.value || '';\n    const quickFilter = document.getElementById('rates-quick-filter')?.value || sessionStorage.getItem('ratesQuickFilter') || '';\n\n    // ===== Collect all quotes =====\n    let allQuotes = [];\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        (db.rates[mode] || []).forEach((quote, idx) => {\n            if (isRecordSoftDeleted(quote)) return;\n            allQuotes.push({\n                ...quote,\n                _mode: mode,\n                _idx: idx,\n                _modeLabel: mode.toUpperCase()\n            });\n        });\n    });\n\n    // ===== Populate user filter dropdown =====\n    const userSelect = document.getElementById('rates-user-filter');\n    if (userSelect) {\n        const users = [...new Set(allQuotes.map(q => q.sales || q.createdBy || db.defaultUser || 'Unknown'))].filter(Boolean);\n        const currentVal = userSelect.value;\n        userSelect.innerHTML = '<option value=\"\">All Users</option>' +\n            users.map(u => `<option value=\"${u}\" ${u === currentVal ? 'selected' : ''}>${u}</option>`).join('');\n    }\n\n    // ===== Apply filters =====\n    let filtered = allQuotes.filter(q => {\n        if (searchText) {\n            const searchable = `${q.quoteNumber||''} ${q.client||''} ${q.pol||''} ${q.pod||''}`.toLowerCase();\n            if (!searchable.includes(searchText)) return false;\n        }\n        if (searchQN && !(q.quoteNumber||'').toLowerCase().includes(searchQN)) return false;\n        if (searchDate) {\n            const d = new Date(q.timestamp).toISOString().split('T')[0];\n            if (d !== searchDate) return false;\n        }\n        if (!quoteTableDateInRange(q.timestamp, document.getElementById('rates-date-from')?.value || '', document.getElementById('rates-date-to')?.value || '')) return false;\n        if (statusFilter && (q.followUpStatus || 'PENDING') !== statusFilter) return false;\n        if (modeFilter && q._modeLabel !== modeFilter) return false;\n        if (userFilter && (q.sales || q.createdBy || db.defaultUser) !== userFilter) return false;\n        if (quickFilter === 'converted' && !isQuoteConverted(q)) return false;\n        if (quickFilter === 'expired' && !isQuoteExpired(q)) return false;\n        if (quickFilter === 'sea' && q._mode !== 'sea') return false;\n        if (quickFilter === 'air' && q._mode !== 'air') return false;\n        if (quickFilter === 'lcl' && q._mode !== 'lcl') return false;\n        return true;\n    });\n\n    // ===== Sort =====\n    const sortKey = ratesSortColumn;\n    const sortOrder = ratesSortOrder === 'asc' ? 1 : -1;\n    filtered.sort((a, b) => {\n        let valA = a[sortKey] || '';\n        let valB = b[sortKey] || '';\n        if (sortKey === 'timestamp') {\n            valA = new Date(valA);\n            valB = new Date(valB);\n            return sortOrder * (valA - valB);\n        }\n        valA = String(valA).toLowerCase();\n        valB = String(valB).toLowerCase();\n        return sortOrder * valA.localeCompare(valB);\n    });\n\n    // ===== Update counters =====\n    updateRatesCounters(allQuotes, filtered);\n\n    // ===== Pagination =====\n    const perPage = 15;\n    const total = filtered.length;\n    const totalPages = Math.ceil(total / perPage) || 1;\n    let page = parseInt(sessionStorage.getItem('ratesPage') || '1');\n    if (page < 1) page = 1;\n    if (page > totalPages) page = totalPages;\n    sessionStorage.setItem('ratesPage', String(page));\n\n    const start = (page - 1) * perPage;\n    const pageData = filtered.slice(start, start + perPage);\n\n    if (total === 0) {\n        container.innerHTML = '<p style=\"color:var(--text-light);padding:20px;text-align:center;\">No quotes found.</p>';\n        paginationEl.innerHTML = '';\n        updateSelectedCount();\n        return;\n    }\n\n    // ===== Build table =====\n    let html = `\n    <div class=\"rates-table-wrapper\">\n        <table class=\"rates-enhanced-table\" id=\"rates-table\">\n            <thead>\n                <tr>\n                    <th style=\"width:30px;\"><input type=\"checkbox\" id=\"rates-select-all\" onchange=\"toggleAllRatesCheckboxes()\" /></th>\n                    <th data-sort=\"quoteNumber\" onclick=\"sortRates('quoteNumber')\" style=\"width:12%;\">QUOTE REF <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"client\" onclick=\"sortRates('client')\" style=\"width:15%;\">CUSTOMER <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"pol\" onclick=\"sortRates('pol')\" style=\"width:14%;\">ORIGIN <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"pod\" onclick=\"sortRates('pod')\" style=\"width:14%;\">DESTINATION <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"_modeLabel\" onclick=\"sortRates('_modeLabel')\" style=\"width:8%;\">SERVICE <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"followUpStatus\" onclick=\"sortRates('followUpStatus')\" style=\"width:10%;\">STATUS <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"validityDate\" onclick=\"sortRates('validityDate')\" style=\"width:12%;\">VALID TILL <span class=\"sort-arrow\"></span></th>\n                    <th data-sort=\"timestamp\" onclick=\"sortRates('timestamp')\" style=\"width:10%;\">CREATED ON <span class=\"sort-arrow\"></span></th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    pageData.forEach((q, index) => {\n        const status = q.followUpStatus || 'PENDING';\n        const statusClass = `follow-up-${status.toLowerCase().replace('-','')}`;\n        const validityDate = q.validityDate ? new Date(q.validityDate) : null;\n        const today = new Date();\n        today.setHours(0,0,0,0);\n        let validityDisplay = '-';\n        if (validityDate) {\n            const diff = Math.ceil((validityDate - today) / (1000 * 60 * 60 * 24));\n            const month = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][validityDate.getMonth()];\n            const day = String(validityDate.getDate()).padStart(2,'0');\n            const year = String(validityDate.getFullYear()).slice(-2);\n            const datePart = `${day}-${month}-${year}`;\n            if (diff >= 0) {\n                validityDisplay = `${datePart} (<span class=\"validity-days\">${diff}</span>)`;\n            } else {\n                validityDisplay = `${datePart} (<span class=\"validity-days expired\">Expired</span>)`;\n            }\n        }\n\n        const createdDate = q.timestamp ? new Date(q.timestamp) : new Date();\n        const month = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][createdDate.getMonth()];\n        const day = String(createdDate.getDate()).padStart(2,'0');\n        const year = String(createdDate.getFullYear()).slice(-2);\n        const createdDisplay = `${day}-${month}-${year}`;\n\n        const serviceMap = { 'SEA': 'FCL', 'AIR': 'AIR', 'LCL': 'LCL' };\n        const service = serviceMap[q._modeLabel] || q._modeLabel;\n\n        const rowBg = (index % 2 === 1) ? '#C7F0EA' : 'transparent';\n\n        html += `\n            <tr style=\"background:${rowBg};\" data-quote='${JSON.stringify(q).replace(/'/g,\"&apos;\")}'>\n                <td style=\"text-align:center;\"><input type=\"checkbox\" class=\"rates-row-checkbox\" data-mode=\"${q._mode}\" data-index=\"${q._idx}\" onchange=\"updateSelectedCount()\" /></td>\n                <td><strong>${q.quoteNumber || 'N/A'}</strong></td>\n                <td>${q.client || '-'}</td>\n                <td>${q.pol || '-'}</td>\n                <td>${q.pod || '-'}</td>\n                <td><span class=\"service-badge\">${service}</span></td>\n                <td>\n                    <select class=\"status-dropdown ${statusClass}\" onchange=\"updateQuoteStatus(this, '${q._mode}', ${q._idx})\">\n                        <option value=\"PENDING\" ${status==='PENDING'?'selected':''}>\u23f3 Pending</option>\n                        <option value=\"SENT\" ${status==='SENT'?'selected':''}>\ud83d\udce4 Sent</option>\n                        <option value=\"FOLLOW-UP\" ${status==='FOLLOW-UP'?'selected':''}>\ud83d\udd04 Follow-up</option>\n                        <option value=\"WON\" ${status==='WON'?'selected':''}>\u2705 Won</option>\n                        <option value=\"LOST\" ${status==='LOST'?'selected':''}>\u274c Lost</option>\n                    </select>\n                </td>\n                <td>${validityDisplay}</td>\n                <td>${createdDisplay}</td>\n            </tr>\n        `;\n    });\n\n    html += `</tbody></table></div>`;\n    container.innerHTML = html;\n\n    // ===== Update sort arrows and selection count =====\n    updateSortArrows();\n    updateSelectedCount();\n\n    // ===== Pagination footer =====\n    if (totalPages <= 1) {\n        paginationEl.innerHTML = '';\n    } else {\n        let pagHtml = `<button class=\"page-btn\" onclick=\"changeRatesPage(${page - 1})\" ${page === 1 ? 'disabled' : ''}>\u2039 Prev</button>`;\n        pagHtml += `<span class=\"page-info\">Page ${page} of ${totalPages} (${total} records)</span>`;\n        pagHtml += `<button class=\"page-btn\" onclick=\"changeRatesPage(${page + 1})\" ${page === totalPages ? 'disabled' : ''}>Next \u203a</button>`;\n        paginationEl.innerHTML = pagHtml;\n    }\n}\n\nfunction updateSortArrows() {\n    document.querySelectorAll('#rates-table th[data-sort]').forEach(th => {\n        const col = th.dataset.sort;\n        const arrow = th.querySelector('.sort-arrow');\n        if (col === ratesSortColumn) {\n            arrow.textContent = ratesSortOrder === 'asc' ? ' \u25b2' : ' \u25bc';\n        } else {\n            arrow.textContent = '';\n        }\n    });\n}\n\nfunction sortRates(column) {\n    if (ratesSortColumn === column) {\n        ratesSortOrder = ratesSortOrder === 'asc' ? 'desc' : 'asc';\n    } else {\n        ratesSortColumn = column;\n        ratesSortOrder = 'asc';\n    }\n    renderRecords('rates');\n}\n\nfunction updateQuoteStatus(select, mode, idx) {\n    const newStatus = select.value;\n    const quote = db.rates[mode][idx];\n    if (!quote) return;\n    quote.followUpStatus = newStatus;\n    quote.followUpUpdated = new Date().toISOString();\n    quote.lastModified = new Date().toISOString();\n    // Lock the exact commercial data snapshot at the moment the quote is sent.\n    // Once locked, later status changes (FOLLOW-UP/WON/LOST) do not alter the rate snapshot.\n    if (newStatus === 'SENT' && quote.rateLocked !== true) {\n        lockQuotationRate(quote);\n    }\n    if (newStatus === 'LOST') {\n        setTimeout(() => {\n            appPrompt(\n                'Please enter reason for losing this quote:\\n\\nOptions:\\n- High Rates\\n- Slow Response\\n- No Service\\n- Client Not Interested\\n- Competitor Won\\n- Budget Constraints\\n- Other',\n                '',\n                (reason) => {\n                    if (reason && reason.trim()) {\n                        quote.lostReason = reason.trim();\n                        saveDB();\n                        renderRecords('rates');\n                    }\n                }\n            );\n        }, 100);\n    } else {\n        saveDB();\n        // Update only the status dropdown style\n        select.className = 'status-dropdown follow-up-' + newStatus.toLowerCase().replace('-','');\n    }\n}\n\nfunction toggleAllRatesCheckboxes() {\n    const checked = document.getElementById('rates-select-all').checked;\n    document.querySelectorAll('.rates-row-checkbox').forEach(cb => cb.checked = checked);\n    updateSelectedCount();\n}\n\nfunction updateSelectedCount() {\n    const checked = document.querySelectorAll('.rates-row-checkbox:checked').length;\n    const el = document.getElementById('rates-selected-count');\n    if (el) el.textContent = checked + ' selected';\n\n    const localChecked = document.querySelectorAll('#localcharges .dc-checkbox:checked, #localcharges .cc-checkbox:checked, #localcharges .thc-checkbox:checked').length;\n    const localHeader = document.getElementById('selected-count');\n    if (localHeader) localHeader.textContent = localChecked + ' selected';\n    document.querySelectorAll('#localcharges .lc-actions-right strong[id^=\"lc-selected-\"]').forEach(node => {\n        const id = node.id.replace('lc-selected-','');\n        const parts = id.split('-');\n        const kind = parts[0];\n        const mode = parts.slice(1).join('-');\n        let selector = '';\n        if (kind === 'dc') selector = `.dc-checkbox[data-mode=\"${mode}\"]:checked`;\n        else if (kind === 'cc') selector = `.cc-checkbox[data-type=\"${mode}\"]:checked`;\n        else if (kind === 'thc') selector = `.thc-checkbox[data-mode=\"${mode}\"]:checked`;\n        if (selector) node.textContent = String(document.querySelectorAll(selector).length);\n    });\n}\n\nfunction getSelectedQuotes() {\n    const selected = [];\n    document.querySelectorAll('.rates-row-checkbox:checked').forEach(cb => {\n        const mode = cb.dataset.mode;\n        const idx = Number(cb.dataset.index);\n        const q = db.rates?.[mode]?.[idx];\n        if (q) selected.push({ ...q, _mode: mode, _idx: idx });\n    });\n    return selected;\n}\nfunction ratesBulkAction(action) {\n    const selected = getSelectedQuotes();\n    if (selected.length === 0) {\n        alert('Please select at least one quote.');\n        return;\n    }\n\n    switch(action) {\n        case 'preview':\n            previewSavedRecord('rates', selected[0]._mode, selected[0]._idx);\n            break;\n        case 'pdf':\n            downloadSavedPDF('rates', selected[0]._mode, selected[0]._idx);\n            break;\n        case 'email':\n            emailSavedQuote('rates', selected[0]._mode, selected[0]._idx);\n            break;\n        case 'duplicate':\n            if (!confirm(`Duplicate ${selected.length} selected quote(s)?`)) return;\n            selected.forEach(q => duplicateQuote('rates', q._mode, q._idx));\n            renderRecords('rates');\n            alert(`Duplicated ${selected.length} quote(s).`);\n            break;\n        case 'edit':\n            editRecord('rates', selected[0]._mode, selected[0]._idx);\n            break;\n        case 'delete':\n            if (!confirm(`Move ${selected.length} selected quote(s) to Recycle Bin?`)) return;\n            const toDelete = selected.map(q => ({ mode: q._mode, idx: q._idx })).sort((a, b) => b.idx - a.idx);\n            const snapshots = [];\n            toDelete.forEach(({ mode, idx }) => {\n                const record = db.rates?.[mode]?.[idx];\n                if (record) {\n                    snapshots.push({ record, flags: { deleted: record.deleted, isDeleted: record.isDeleted, deletedAt: record.deletedAt, deletedOn: record.deletedOn, updated: record.updated, updatedAt: record.updatedAt } });\n                    window.shahidMarkRecordDeleted(record);\n                }\n            });\n            if (saveDB() !== true) {\n                snapshots.forEach(({record,flags}) => Object.keys(flags).forEach(key => { if (flags[key] === undefined) delete record[key]; else record[key] = flags[key]; }));\n                return alert('Unable to delete selected quotes because the database could not be saved.');\n            }\n            renderRecords('rates');\n            if (typeof window.renderRecycleBin === 'function') window.renderRecycleBin();\n            alert('Selected quotes moved to Recycle Bin.');\n            break;\n        case 'convert':\n            if (!confirm(`Convert ${selected.length} selected quote(s) to shipments?`)) return;\n            let converted = 0, skipped = 0;\n            selected.forEach(q => {\n                if (isQuoteConverted(q)) {\n                    skipped++;\n                    return;\n                }\n                try {\n                    addShipmentFromQuote('rates', q._mode, q._idx, true); // true = no modal\n                    converted++;\n                } catch(e) {\n                    console.error('Conversion error:', e);\n                    skipped++;\n                }\n            });\n            alert(`\u2705 Converted ${converted} quotes to shipments.\\n\u23ed\ufe0f ${skipped} skipped (already converted or errors).`);\n            renderRecords('rates');\n            break;\n        default:\n            alert('Unknown action.');\n    }\n}\n\nfunction changeRatesPage(page) {\n    sessionStorage.setItem('ratesPage', String(page));\n    renderRecords('rates');\n}\n\nfunction setRatesQuickFilter(value) {\n    const normalized = String(value || '').toLowerCase();\n    const allowed = ['', 'total', 'converted', 'expired', 'sea', 'air', 'lcl'];\n    const next = allowed.includes(normalized) ? normalized : '';\n    const el = document.getElementById('rates-quick-filter');\n    if (el) el.value = next;\n    if (next) sessionStorage.setItem('ratesQuickFilter', next);\n    else sessionStorage.removeItem('ratesQuickFilter');\n    sessionStorage.setItem('ratesPage', '1');\n    renderEnhancedRates();\n}\n\nfunction clearRatesFilters() {\n    document.getElementById('rates-search-text').value = '';\n    document.getElementById('rates-search-qn').value = '';\n    document.getElementById('rates-search-date').value = ''; // \u2705 NEW\n    document.getElementById('rates-status-filter').value = '';\n    document.getElementById('rates-mode-filter').value = '';\n    document.getElementById('rates-user-filter').value = '';\n    const qf = document.getElementById('rates-quick-filter'); if (qf) qf.value = '';\n    sessionStorage.removeItem('ratesQuickFilter');\n    sessionStorage.setItem('ratesPage', '1');\n    renderRecords('rates');\n}\n\nfunction updateRatesCounters(allQuotes, filtered) {\n    const countersEl = document.getElementById('rates-counters');\n    if (!countersEl) return;\n\n    const totalSea = db.rates.sea ? db.rates.sea.length : 0;\n    const totalAir = db.rates.air ? db.rates.air.length : 0;\n    const totalLcl = db.rates.lcl ? db.rates.lcl.length : 0;\n    const totalAll = totalSea + totalAir + totalLcl;\n\n    const converted = allQuotes.filter(q => isQuoteConverted(q)).length;\n    const expired = allQuotes.filter(q => isQuoteExpired(q)).length;\n\n    countersEl.innerHTML = `\n        <div class=\"counter-card\" style=\"border-color:#3b82f6;cursor:pointer;\" onclick=\"setRatesQuickFilter('sea')\" title=\"Show SEA quotes\"><div class=\"counter-label\">\ud83d\udea2 SEA</div><div class=\"counter-value\">${totalSea}</div></div>\n        <div class=\"counter-card\" style=\"border-color:#f59e0b;cursor:pointer;\" onclick=\"setRatesQuickFilter('air')\" title=\"Show AIR quotes\"><div class=\"counter-label\">\u2708\ufe0f AIR</div><div class=\"counter-value\">${totalAir}</div></div>\n        <div class=\"counter-card\" style=\"border-color:#10b981;cursor:pointer;\" onclick=\"setRatesQuickFilter('lcl')\" title=\"Show LCL quotes\"><div class=\"counter-label\">\ud83d\udce6 LCL</div><div class=\"counter-value\">${totalLcl}</div></div>\n        <div class=\"counter-card\" style=\"border-color:#8b5cf6;cursor:pointer;\" title=\"Show converted quotes\" onclick=\"setRatesQuickFilter('converted')\"><div class=\"counter-label\">\ud83d\udccb CONVERTED</div><div class=\"counter-value\">${converted}</div></div>\n        <div class=\"counter-card\" style=\"border-color:#ef4444;cursor:pointer;\" title=\"Show expired quotes\" onclick=\"setRatesQuickFilter('expired')\"><div class=\"counter-label\">\u23f0 EXPIRED</div><div class=\"counter-value\">${expired}</div></div>\n        <div class=\"counter-card\" style=\"border-color:#1e3a8a;cursor:pointer;\" title=\"Show all quotes\" onclick=\"setRatesQuickFilter('total')\"><div class=\"counter-label\">\ud83d\udcca TOTAL</div><div class=\"counter-value\">${totalAll}</div></div>\n    `;\n}\n\n// ==================== DATE FILTER / EXPORT ACTIONS ====================\nfunction applyRatesDateFilter() {\n    const r = validateQuoteTableDateRange('rates');\n    if (!r) return;\n\n    // Persist the active Rate Quotes date filter before re-rendering.\n    sessionStorage.setItem('ratesDateFrom', r.from);\n    sessionStorage.setItem('ratesDateTo', r.to);\n    sessionStorage.setItem('ratesPage', '1');\n\n    renderRecords('rates');\n}\nfunction resetRatesDateFilter() {\n    const a = document.getElementById('rates-date-from');\n    const b = document.getElementById('rates-date-to');\n    if (a) a.value = '';\n    if (b) b.value = '';\n    sessionStorage.removeItem('ratesDateFrom');\n    sessionStorage.removeItem('ratesDateTo');\n    sessionStorage.setItem('ratesPage', '1');\n    renderRecords('rates');\n}\nfunction applyDraftsDateFilter() { const r=validateQuoteTableDateRange('drafts'); if(!r) return; sessionStorage.setItem('draftsPage','1'); renderRecords('drafts'); }\nfunction resetDraftsDateFilter() { const a=document.getElementById('drafts-date-from'),b=document.getElementById('drafts-date-to'); if(a)a.value=''; if(b)b.value=''; sessionStorage.setItem('draftsPage','1'); renderRecords('drafts'); }\nfunction applyRRDateFilter() { const r=validateQuoteTableDateRange('rrdrafts'); if(!r) return; sessionStorage.setItem('rrPage','1'); renderRecords('rrdrafts'); }\nfunction resetRRDateFilter() { const a=document.getElementById('rrdrafts-date-from'),b=document.getElementById('rrdrafts-date-to'); if(a)a.value=''; if(b)b.value=''; sessionStorage.setItem('rrPage','1'); renderRecords('rrdrafts'); }\nfunction getRateQuotesExportRows() {\n    const r = validateQuoteTableDateRange('rates');\n    if (!r) return null;\n    const searchText = (document.getElementById('rates-search-text')?.value || '').toLowerCase();\n    const searchQN = (document.getElementById('rates-search-qn')?.value || '').toLowerCase();\n    const searchDate = document.getElementById('rates-search-date')?.value || '';\n    const statusFilter = document.getElementById('rates-status-filter')?.value || '';\n    const modeFilter = document.getElementById('rates-mode-filter')?.value || '';\n    const userFilter = document.getElementById('rates-user-filter')?.value || '';\n    const quickFilter = document.getElementById('rates-quick-filter')?.value || sessionStorage.getItem('ratesQuickFilter') || '';\n\n    const rows = [];\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        (db.rates?.[mode] || []).forEach(q => {\n            const row = { ...q, _mode: mode.toUpperCase(), _modeRaw: mode };\n            if (searchText) {\n                const searchable = `${q.quoteNumber || ''} ${q.client || ''} ${q.pol || ''} ${q.pod || ''}`.toLowerCase();\n                if (!searchable.includes(searchText)) return;\n            }\n            if (searchQN && !(q.quoteNumber || '').toLowerCase().includes(searchQN)) return;\n            if (searchDate) {\n                const d = quoteTableDateOnly(q.timestamp);\n                if (!d || `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` !== searchDate) return;\n            }\n            if (!quoteTableDateInRange(q.timestamp, r.from, r.to)) return;\n            if (statusFilter && (q.followUpStatus || 'PENDING') !== statusFilter) return;\n            if (modeFilter && row._mode !== modeFilter) return;\n            if (userFilter && (q.sales || q.createdBy || db.defaultUser) !== userFilter) return;\n            if (quickFilter === 'converted' && !isQuoteConverted(q)) return;\n            if (quickFilter === 'expired' && !isQuoteExpired(q)) return;\n            if (quickFilter === 'sea' && mode !== 'sea') return;\n            if (quickFilter === 'air' && mode !== 'air') return;\n            if (quickFilter === 'lcl' && mode !== 'lcl') return;\n            rows.push(row);\n        });\n    });\n    return rows;\n}\n\nfunction getDraftsExportRows() {\n    const r = validateQuoteTableDateRange('drafts');\n    if (!r) return null;\n    const searchText = (document.getElementById('drafts-search-text')?.value || '').toLowerCase();\n    const searchQN = (document.getElementById('drafts-search-qn')?.value || '').toLowerCase();\n    const searchDate = document.getElementById('drafts-search-date')?.value || '';\n    const quickFilter = document.getElementById('drafts-quick-filter')?.value || sessionStorage.getItem('draftsQuickFilter') || '';\n\n    const rows = [];\n    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {\n        (db.drafts?.[mode] || []).forEach(d => {\n            const row = { ...d, _mode: mode, _modeLabel: mode.toUpperCase() };\n            if (searchText) {\n                const text = `${d.client || ''} ${d.pol || ''} ${d.pod || ''} ${d.carrier || ''} ${d.quoteNumber || ''}`.toLowerCase();\n                if (!text.includes(searchText)) return;\n            }\n            if (searchQN && !(d.quoteNumber || '').toLowerCase().includes(searchQN)) return;\n            if (searchDate) {\n                const dd = quoteTableDateOnly(d.timestamp);\n                if (!dd || `${dd.getFullYear()}-${String(dd.getMonth()+1).padStart(2,'0')}-${String(dd.getDate()).padStart(2,'0')}` !== searchDate) return;\n            }\n            if (!quoteTableDateInRange(d.timestamp, r.from, r.to)) return;\n            if (quickFilter === 'sea' && mode !== 'sea') return;\n            if (quickFilter === 'air' && mode !== 'air') return;\n            if (quickFilter === 'lcl' && mode !== 'lcl') return;\n            rows.push(row);\n        });\n    });\n    return rows;\n}\n\nfunction getRRExportRows() {\n    const r = validateQuoteTableDateRange('rrdrafts');\n    if (!r) return null;\n    const searchText = (document.getElementById('rrdrafts-search-text')?.value || '').toLowerCase();\n    const searchQN = (document.getElementById('rrdrafts-search-qn')?.value || '').toLowerCase();\n    const searchDate = document.getElementById('rrdrafts-search-date')?.value || '';\n    const modeFilter = rrModeFilter || sessionStorage.getItem('rrModeFilter') || '';\n\n    return (db.drafts?.rr || []).filter(rr => {\n        if (searchText) {\n            const text = `${rr.shipper || ''} ${rr.forwarder || ''} ${rr.pol || ''} ${rr.pod || ''} ${rr.quoteNumber || ''}`.toLowerCase();\n            if (!text.includes(searchText)) return false;\n        }\n        if (searchQN && !(rr.quoteNumber || '').toLowerCase().includes(searchQN)) return false;\n        if (searchDate) {\n            const d = quoteTableDateOnly(rr.timestamp);\n            if (!d || `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` !== searchDate) return false;\n        }\n        if (!quoteTableDateInRange(rr.timestamp, r.from, r.to)) return false;\n        if (modeFilter && getRRDisplayMode(rr) !== modeFilter) return false;\n        return true;\n    });\n}\n\nfunction exportRatesDateExcel() {\n    const rows = getRateQuotesExportRows();\n    if (!rows) return;\n    quoteTableRowsToExcel(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Customer', x => x.client || '-'],\n        ['Origin', x => x.pol || '-'], ['Destination', x => x.pod || '-'],\n        ['Service', x => x._mode], ['Status', x => x.followUpStatus || 'PENDING'],\n        ['Valid Till', x => x.validityDate || '-'], ['Created On', x => x.timestamp || '-']\n    ], 'Rate Quotes', 'Rate_Quotes');\n}\nfunction exportRatesDatePDF() {\n    const rows = getRateQuotesExportRows();\n    if (!rows) return;\n    quoteTableRowsToPDF(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Customer', x => x.client || '-'],\n        ['Origin', x => x.pol || '-'], ['Destination', x => x.pod || '-'],\n        ['Service', x => x._mode], ['Status', x => x.followUpStatus || 'PENDING'],\n        ['Valid Till', x => x.validityDate || '-'], ['Created On', x => x.timestamp || '-']\n    ], 'Rate Quotes', 'rates');\n}\nfunction exportDraftsDateExcel() {\n    const rows = getDraftsExportRows();\n    if (!rows) return;\n    quoteTableRowsToExcel(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Customer', x => x.client || '-'],\n        ['Origin', x => x.pol || '-'], ['Destination', x => x.pod || '-'],\n        ['Service', x => x._mode], ['Valid Till', x => x.validityDate || '-'],\n        ['Created On', x => x.timestamp || '-']\n    ], 'Draft Quotations', 'Draft_Quotations');\n}\nfunction exportDraftsDatePDF() {\n    const rows = getDraftsExportRows();\n    if (!rows) return;\n    quoteTableRowsToPDF(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Customer', x => x.client || '-'],\n        ['Origin', x => x.pol || '-'], ['Destination', x => x.pod || '-'],\n        ['Service', x => x._mode], ['Valid Till', x => x.validityDate || '-'],\n        ['Created On', x => x.timestamp || '-']\n    ], 'Draft Quotations', 'drafts');\n}\nfunction exportRRDateExcel() {\n    const rows = getRRExportRows();\n    if (!rows) return;\n    quoteTableRowsToExcel(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Shipper', x => x.shipper || x.forwarder || '-'],\n        ['POL', x => x.pol || '-'], ['POD', x => x.pod || '-'],\n        ['Mode', x => getRRDisplayMode(x)], ['Created On', x => x.timestamp || '-']\n    ], 'Rate Requested', 'Rate_Requested');\n}\nfunction exportRRDatePDF() {\n    const rows = getRRExportRows();\n    if (!rows) return;\n    quoteTableRowsToPDF(rows, [\n        ['Quote Ref', x => x.quoteNumber || '-'], ['Shipper', x => x.shipper || x.forwarder || '-'],\n        ['POL', x => x.pol || '-'], ['POD', x => x.pod || '-'],\n        ['Mode', x => getRRDisplayMode(x)], ['Created On', x => x.timestamp || '-']\n    ], 'Rate Requested', 'rrdrafts');\n}\n\n// ==================== ENHANCED DRAFTS VIEW ====================\nlet draftsSortColumn = 'timestamp';\nlet draftsSortOrder = 'desc';";
})(window);


