/* ===== ORIGINAL MODULE: JS/mobile-enhancements.js ===== */
/**
 * @license
 * Shahid ERP Mobile & Touch Ergonomics Enhancement Module
 * Fixes mobile layouts, header overflow, database panel switching,
 * compact button/icon sizing, and drawer navigation.
 */
(function() {
  'use strict';

  function isMobileView() {
    return window.innerWidth <= 900;
  }

  function closeMobileNav() {
    const wrapper = document.querySelector('.app-wrapper');
    if (wrapper) {
      wrapper.classList.remove('mobile-nav-open', 'mobile-nav-hidden');
      const btn = document.getElementById('navToggleBtn');
      if (btn) {
        btn.setAttribute('aria-expanded', 'false');
        btn.setAttribute('aria-label', 'Show menu');
        btn.title = 'Show Menu';
      }
    }
  }

  function toggleNav() {
    const wrapper = document.querySelector('.app-wrapper');
    if (!wrapper) return;

    if (isMobileView()) {
      const wasOpen = wrapper.classList.contains('mobile-nav-open');
      // Older tab-switch hooks leave this class behind. It must not prevent reopening.
      wrapper.classList.remove('mobile-nav-hidden');
      wrapper.classList.toggle('mobile-nav-open', !wasOpen);
      const isOpen = wrapper.classList.contains('mobile-nav-open');
      const btn = document.getElementById('navToggleBtn');
      if (btn) {
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        btn.setAttribute('aria-label', isOpen ? 'Hide menu' : 'Show menu');
        btn.title = isOpen ? 'Hide Menu' : 'Show Menu';
      }
      if (isOpen) {
        // Navigation must remain usable even when browser privacy settings block storage.
        try { updateDrawerUserInfo(); } catch (e) { /* keep the drawer open; user details are optional */ }
      }
      return;
    }

    wrapper.classList.toggle('nav-collapsed');
    const isCollapsed = wrapper.classList.contains('nav-collapsed');
    try { localStorage.setItem('navCollapsed', isCollapsed ? 'true' : 'false'); } catch (e) {}
    const btn = document.getElementById('navToggleBtn');
    if (btn) {
      btn.setAttribute('aria-expanded', isCollapsed ? 'false' : 'true');
      btn.setAttribute('aria-label', isCollapsed ? 'Show menu' : 'Hide menu');
      btn.title = isCollapsed ? 'Show Menu' : 'Hide Menu';
    }
  }

  window.toggleNav = toggleNav;
  window.closeMobileNav = closeMobileNav;

  // Resilient Database Module Switcher
  // Keep this as a single entry point for the hamburger drawer and quick navigation.
  function activateDatabaseTab() {
    const contentArea = document.querySelector('.content-area');
    const dbPanel = document.getElementById('database');
    if (!dbPanel) return false;

    // Do not bypass the ERP's existing role/permission checks when invoked from a mobile control.
    if (typeof requireTabAccess === 'function' && !requireTabAccess('database', 'open this module')) {
      return false;
    }

    // Make panel visibility explicit so hidden-tab CSS cannot keep Database blank.
    document.querySelectorAll('.tab-panel').forEach(panel => {
      panel.classList.toggle('active', panel === dbPanel);
    });
    document.querySelectorAll('.tab-btn-vertical').forEach(button => {
      button.classList.toggle('active', button.dataset.tab === 'database');
    });
    document.querySelectorAll('.nav-category-header').forEach(header => header.classList.remove('active'));

    const dbBtn = document.querySelector('.tab-btn-vertical[data-tab="database"]');
    if (dbBtn) {
      const category = dbBtn.closest('.nav-category');
      if (category) {
        const header = category.querySelector('.nav-category-header');
        if (header) header.classList.add('active');
        const items = category.querySelector('.nav-category-items');
        if (items) items.classList.remove('collapsed');
      }
    }

    dbPanel.classList.add('active', 'database-management-active');
    dbPanel.setAttribute('data-db-rendered', 'true');
    dbPanel.setAttribute('tabindex', '-1');
    if (contentArea) {
      contentArea.classList.add('database-content-active');
      contentArea.scrollTop = 0;
    }
    dbPanel.scrollTop = 0;

    const clearLoadStatus = () => {
      const old = document.getElementById('database-load-status');
      if (old) old.remove();
    };
    const showLoadStatus = message => {
      let status = document.getElementById('database-load-status');
      if (!status) {
        status = document.createElement('div');
        status.id = 'database-load-status';
        status.setAttribute('role', 'alert');
        status.style.cssText = 'margin:0 0 12px;padding:10px 12px;border:1px solid #f5b4b4;border-radius:8px;background:#fff1f2;color:#991b1b;font-size:.82rem;line-height:1.4;';
        const heading = dbPanel.querySelector('.tab-heading');
        if (heading && heading.nextSibling) dbPanel.insertBefore(status, heading.nextSibling);
        else dbPanel.prepend(status);
      }
      status.textContent = message;
    };

    try {
      const render = typeof window.renderDatabase === 'function'
        ? window.renderDatabase
        : (typeof renderDatabase === 'function' ? renderDatabase : null);
      if (render) {
        render();
        clearLoadStatus();
      } else {
        showLoadStatus('Database view opened, but its renderer is unavailable. The existing data has not been changed.');
      }
    } catch (error) {
      console.error('Database tab failed to refresh:', error);
      showLoadStatus('Database view opened, but some saved values could not be refreshed. Your existing data has not been changed. Refresh the application and check the browser console if the problem continues.');
    }

    updateActiveBottomTab('database');
    if (isMobileView()) closeMobileNav();
    requestAnimationFrame(() => {
      if (contentArea) contentArea.scrollTo({ top: 0, behavior: 'auto' });
      dbPanel.scrollTop = 0;
      try { dbPanel.focus({ preventScroll: true }); } catch (_) { dbPanel.focus(); }
    });
    return true;
  }
  window.activateDatabaseTab = activateDatabaseTab;

  // Mobile Bottom Navigation Bar
  function setupMobileBottomBar() {
    if (document.getElementById('mobile-bottom-bar')) return;

    const bar = document.createElement('nav');
    bar.id = 'mobile-bottom-bar';
    bar.setAttribute('aria-label', 'Mobile Quick Navigation');
    bar.innerHTML = `
      <button type="button" class="mobile-bottom-tab" data-tab="raterequest" title="Rate Request">
        <span class="mobile-bottom-icon">📩</span>
        <span class="mobile-bottom-label">Rate Req</span>
      </button>
      <button type="button" class="mobile-bottom-tab" data-tab="export-quote" title="Export Quote">
        <span class="mobile-bottom-icon">📤</span>
        <span class="mobile-bottom-label">Quote</span>
      </button>
      <button type="button" class="mobile-bottom-tab" data-tab="dsr" title="DSR Shipments">
        <span class="mobile-bottom-icon">📊</span>
        <span class="mobile-bottom-label">DSR</span>
      </button>
      <button type="button" class="mobile-bottom-tab" data-tab="rates" title="Rates Quoted">
        <span class="mobile-bottom-icon">💰</span>
        <span class="mobile-bottom-label">Rates</span>
      </button>
      <button type="button" class="mobile-bottom-tab" data-tab="database" title="Database Management">
        <span class="mobile-bottom-icon">🗄️</span>
        <span class="mobile-bottom-label">Database</span>
      </button>
      <button type="button" class="mobile-bottom-tab" id="mobile-nav-drawer-btn" title="All Modules">
        <span class="mobile-bottom-icon">☰</span>
        <span class="mobile-bottom-label">Menu</span>
      </button>
    `;

    document.body.appendChild(bar);

    bar.querySelectorAll('.mobile-bottom-tab').forEach(tab => {
      tab.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();

        if (this.id === 'mobile-nav-drawer-btn') {
          toggleNav();
          return;
        }

        const targetTab = this.dataset.tab;
        if (targetTab) {
          closeMobileNav();
          if (targetTab === 'database') {
            activateDatabaseTab();
          } else if (typeof window.switchToTab === 'function') {
            window.switchToTab(targetTab);
          } else {
            const sideBtn = document.querySelector(`.tab-btn-vertical[data-tab="${targetTab}"]`);
            if (sideBtn) sideBtn.click();
          }
          updateActiveBottomTab(targetTab);
        }
      });
    });
  }

  function updateActiveBottomTab(tabId) {
    const bottomTabs = document.querySelectorAll('.mobile-bottom-tab');
    bottomTabs.forEach(t => {
      if (t.dataset.tab === tabId) {
        t.classList.add('active');
      } else {
        t.classList.remove('active');
      }
    });
  }

  // Drawer User Card & Search Header
  function setupDrawerHeader() {
    const nav = document.querySelector('.tab-nav-vertical');
    if (!nav || nav.querySelector('.mobile-drawer-topbar')) return;

    const topbar = document.createElement('div');
    topbar.className = 'mobile-drawer-topbar';
    topbar.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:rgba(15,23,42,0.95); border-bottom:1px solid rgba(255,255,255,0.1);">
        <div style="display:flex; align-items:center; gap:8px;">
          <span style="font-size:1.1rem;">👤</span>
          <div>
            <div id="drawer-user-name" style="font-size:0.82rem; font-weight:700; color:white; line-height:1.2;">Shahid ERP User</div>
            <div id="drawer-user-role" style="font-size:0.68rem; color:#38bdf8; font-weight:600;">Standard Access</div>
          </div>
        </div>
        <button type="button" class="drawer-close-btn" onclick="closeMobileNav()" style="background:transparent; border:none; color:white; font-size:1.3rem; padding:4px 8px; cursor:pointer;" title="Close Menu">✕</button>
      </div>
      <div style="padding:8px 12px; background:rgba(0,0,0,0.2); border-bottom:1px solid rgba(255,255,255,0.06);">
        <input type="text" id="drawer-search-input" placeholder="🔍 Search quotes, shipments..." style="width:100%; padding:6px 10px; border-radius:6px; border:1px solid rgba(255,255,255,0.2); background:rgba(255,255,255,0.12); color:white; font-size:0.78rem; outline:none;" />
      </div>
    `;

    nav.insertBefore(topbar, nav.firstChild);

    // Wire up drawer search
    const drawerSearch = topbar.querySelector('#drawer-search-input');
    if (drawerSearch) {
      drawerSearch.addEventListener('input', function() {
        const val = this.value;
        const mainSearch = document.getElementById('global-search');
        if (mainSearch) {
          mainSearch.value = val;
          if (typeof window.debouncedGlobalSearch === 'function') {
            window.debouncedGlobalSearch();
          }
        }
      });
    }
  }

  function updateDrawerUserInfo() {
    const nameEl = document.getElementById('drawer-user-name');
    const roleEl = document.getElementById('drawer-user-role');
    if (!nameEl || !roleEl) return;

    if (typeof window.checkLogin === 'function') {
      const u = window.checkLogin();
      if (u) {
        nameEl.textContent = u.name || u.id || 'Active User';
        roleEl.textContent = (u.role === 'master' ? '👑 Master Admin' : '👤 ' + (u.role || 'User').toUpperCase());
        return;
      }
    }
    nameEl.textContent = 'Shahid ERP';
    roleEl.textContent = 'Offline Session';
  }

  // Hook Tab Switches
  function hookTabSwitches() {
    document.addEventListener('click', function(e) {
      const btn = e.target.closest('.tab-btn-vertical');
      if (btn) {
        const tabId = btn.dataset.tab;
        if (tabId) updateActiveBottomTab(tabId);
        // Bubble-phase closing is intentional: the button's own tab/permission
        // handler must run before the drawer is dismissed on touch devices.
        if (isMobileView()) {
          setTimeout(() => {
            closeMobileNav();
            const contentArea = document.querySelector('.content-area');
            if (contentArea) contentArea.scrollTo({ top: 0, behavior: 'auto' });
          }, 0);
        }
      }

      // Drawer backdrop dismissal. The menu item's own handler has already had a chance to run.
      const wrapper = document.querySelector('.app-wrapper.mobile-nav-open');
      if (wrapper && isMobileView()) {
        const inDrawer = e.target.closest('.tab-nav-vertical');
        const inToggleBtn = e.target.closest('#navToggleBtn') || e.target.closest('.nav-toggle-btn');
        const inBottomMenuBtn = e.target.closest('#mobile-nav-drawer-btn');
        if (!inDrawer && !inToggleBtn && !inBottomMenuBtn) closeMobileNav();
      }
    }, false);

    // Intercept programmatic switches only to keep the mobile state in sync.
    if (typeof window.switchToTab === 'function' && !window.switchToTab.__SHAHID_MOBILE_HOOKED) {
      const originalSwitch = window.switchToTab;
      const patchedSwitch = function(target) {
        if (target === 'database') return activateDatabaseTab();
        const result = originalSwitch.apply(this, arguments);
        updateActiveBottomTab(target);
        if (isMobileView()) closeMobileNav();
        return result;
      };
      patchedSwitch.__SHAHID_MOBILE_HOOKED = true;
      window.switchToTab = patchedSwitch;
    }
  }

  // Responsive header branding
  function polishHeader() {
    const h1 = document.querySelector('header h1');
    if (h1 && !h1.dataset.polished) {
      h1.dataset.polished = 'true';
      const fullText = h1.textContent.trim();
      h1.innerHTML = `
        <span class="header-title-full" style="display:inline;">${fullText}</span>
        <span class="header-title-mobile" style="display:none;">🚢 Shahid ERP</span>
      `;
    }
  }

  // Wide Table Horizontal Scroll Indicator
  function setupTableScrollHints() {
    const tables = document.querySelectorAll('.table-wrap, .table-responsive');
    tables.forEach(wrap => {
      if (wrap.dataset.hinted) return;
      wrap.dataset.hinted = 'true';

      wrap.addEventListener('scroll', function() {
        if (this.dataset.scrolled !== 'true') {
          this.dataset.scrolled = 'true';
          const hint = this.querySelector('.mobile-table-scroll-hint');
          if (hint) hint.style.opacity = '0';
        }
      }, { passive: true });
    });
  }

  function init() {
    setupMobileBottomBar();
    setupDrawerHeader();
    updateDrawerUserInfo();
    hookTabSwitches();
    polishHeader();
    setupTableScrollHints();

    const activeSideBtn = document.querySelector('.tab-btn-vertical.active');
    if (activeSideBtn && activeSideBtn.dataset.tab) {
      updateActiveBottomTab(activeSideBtn.dataset.tab);
    }

    window.addEventListener('resize', function() {
      const wrapper = document.querySelector('.app-wrapper');
      if (!wrapper) return;
      if (!isMobileView()) {
        wrapper.classList.remove('mobile-nav-open', 'mobile-nav-hidden');
        const btn = document.getElementById('navToggleBtn');
        if (btn) {
          btn.setAttribute('aria-expanded', wrapper.classList.contains('nav-collapsed') ? 'false' : 'true');
          btn.setAttribute('aria-label', 'Toggle navigation menu');
        }
      } else {
        wrapper.classList.remove('nav-collapsed');
        wrapper.classList.remove('mobile-nav-open');
        const btn = document.getElementById('navToggleBtn');
        if (btn) { btn.setAttribute('aria-expanded', 'false'); btn.setAttribute('aria-label', 'Show menu'); }
      }
    }, { passive: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    setTimeout(init, 50);
  }
})();
